CREATE OR REPLACE FUNCTION auth_bag.decode_input(p_hex text)
 RETURNS bytea
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case when p_hex ~ '^([0-9a-f]{2}){1,32}$' then decode(p_hex, 'hex') end
$function$;
CREATE OR REPLACE FUNCTION auth_bag.eligible(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.profiles
     where id = p_user and active and deleted_at is null and role::text in ('student', 'monitor')
  )
$function$;
CREATE OR REPLACE FUNCTION auth_bag.lock_if_reached(p_scope text, p_max integer, p_lock_seconds integer)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  update auth_bag.attempts
     set locked_until = now() + make_interval(secs => p_lock_seconds), failures = 0, window_start = now()
   where scope = p_scope and failures >= p_max and (locked_until is null or locked_until <= now())
$function$;
CREATE OR REPLACE FUNCTION auth_bag.refund(p_scope text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  update auth_bag.attempts set failures = greatest(failures - 1, 0) where scope = p_scope
$function$;
CREATE OR REPLACE FUNCTION auth_bag.reserve(p_scope text, p_max integer, p_window_seconds integer, p_lock_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_row auth_bag.attempts;
begin
  insert into auth_bag.attempts as a (scope, window_start, failures)
  values (p_scope, now(), 1)
  on conflict (scope) do update
    set failures = case
          when a.locked_until > now() then a.failures
          when a.window_start < now() - make_interval(secs => p_window_seconds) then 1
          else a.failures + 1 end,
        window_start = case
          when a.locked_until > now() then a.window_start
          when a.window_start < now() - make_interval(secs => p_window_seconds) then now()
          else a.window_start end
  returning * into v_row;
  if v_row.locked_until > now() then
    return false;
  end if;
  if v_row.failures > p_max then
    update auth_bag.attempts
       set locked_until = now() + make_interval(secs => p_lock_seconds), failures = 0, window_start = now()
     where scope = p_scope;
    return false;
  end if;
  return true;
end $function$;
CREATE OR REPLACE FUNCTION auth_bag.valid_input(p_input bytea, p_catalog smallint, p_catalog_size integer)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select length(p_input) between 9 and 21
     and get_byte(p_input, 0) = p_catalog
     and not exists (
       select 1 from generate_series(1, length(p_input) - 1) i where get_byte(p_input, i) >= p_catalog_size
     )
$function$;
CREATE OR REPLACE FUNCTION bag_game.min_seconds_per_round()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$ select 2 $function$;
CREATE OR REPLACE FUNCTION bag_game.short_name(p_full text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  w text[] := array_remove(regexp_split_to_array(btrim(coalesce(p_full, '')), '\s+'), '');
  n int := coalesce(array_length(w, 1), 0);
  out text := '';
begin
  if n = 0 then return 'Học sinh'; end if;
  for i in 1 .. n - 1 loop out := out || left(w[i], 1) || '.'; end loop;
  return out || w[n];
end;
$function$;
CREATE OR REPLACE FUNCTION homework_private.actionable(n public.homework_notices)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select n.status='pending_duplicate_review' and n.deleted_at is null and not exists(select 1 from public.homework_duplicate_reviews rv where rv.notice_id=n.id and rv.revision=n.revision and rv.decision is not null)
$function$;
CREATE OR REPLACE FUNCTION homework_private.actor(p_class uuid)
 RETURNS public.profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.profiles;begin
 select * into a from public.profiles where id=auth.uid() and active and deleted_at is null;
 if a.id is null then raise exception 'Phiên đăng nhập không hợp lệ' using errcode='42501';end if;
 if not exists(select 1 from public.classes where id=p_class and (active or a.role::text='admin')) then raise exception 'Lớp không hoạt động';end if;
 if a.role::text='admin' then return a;end if;
 if a.role::text='teacher' and exists(select 1 from public.class_teachers where class_id=p_class and teacher_id=a.id and active) then return a;end if;
 if a.role::text in('student','monitor') and a.class_id=p_class then return a;end if;
 raise exception 'Bạn không có quyền trong lớp này' using errcode='42501';end$function$;
CREATE OR REPLACE FUNCTION homework_private.ai_config(st public.homework_settings)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select jsonb_build_object('semantic_duplicate_enabled',st.semantic_duplicate_enabled,'duplicate_review_threshold',st.pending_threshold,'duplicate_auto_threshold',st.reject_threshold)
$function$;
CREATE OR REPLACE FUNCTION homework_private.api_v3(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c uuid:=(p_data->>'class_id')::uuid; a public.profiles; n public.homework_notices; old public.homework_notices;
 s public.class_subjects; g public.english_groups; y uuid; rid uuid; target uuid; r jsonb; before_json jsonb;
 st public.homework_settings; decision text; pending boolean; win_start timestamptz;win_end timestamptz;wk public.weeks;m_start date;
begin
 a:=homework_private.actor(c);
 if a.role::text='admin' and p_action not in('load','inbox','read_notification','settings','alert_settings','hard_delete') then raise exception 'Admin chỉ giám sát Báo bài' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('homework:'||c::text,0));
 select school_year_id into y from public.classes where id=c;
 insert into public.homework_settings(class_id)values(c)on conflict do nothing;
 select * into st from public.homework_settings where class_id=c;
 if p_action='hard_delete' then return homework_private.hard_delete(c,a,p_data);end if;
 if p_action in('load','inbox') then
 perform homework_private.backlog(c);
 if p_action='inbox' then return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select id,title,message,kind,notice_id,is_read,created_at from public.homework_notifications hn where recipient_id=a.id and class_id=c and homework_private.notification_visible(hn,a) order by created_at desc limit 100)x),'[]');end if;
 select start_date::timestamp at time zone 'Asia/Ho_Chi_Minh',(end_date+1)::timestamp at time zone 'Asia/Ho_Chi_Minh' into win_start,win_end from public.school_years where id=y;
 if nullif(p_data->>'week_id','') is not null then
 select * into wk from public.weeks where id=(p_data->>'week_id')::uuid and school_year_id=y;
 if wk.id is null then raise exception 'Tuần không thuộc năm học';end if;
 win_start:=wk.start_date::timestamp at time zone 'Asia/Ho_Chi_Minh';win_end:=(wk.end_date+1)::timestamp at time zone 'Asia/Ho_Chi_Minh';
 end if;
 if nullif(p_data->>'month','') is not null then
  if (p_data->>'month') !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then raise exception 'Tháng không hợp lệ' using errcode='22023';end if;
  m_start:=to_date((p_data->>'month')||'-01','YYYY-MM-DD');
  win_start:=greatest(win_start,m_start::timestamp at time zone 'Asia/Ho_Chi_Minh');
  win_end:=least(win_end,(m_start+interval '1 month')::timestamp at time zone 'Asia/Ho_Chi_Minh');
  if win_end<win_start then win_end:=win_start;end if; -- tháng ngoài năm học: khung rỗng
 end if;
 r:=jsonb_build_object('settings',jsonb_build_object('seed_threshold',st.seed_threshold),
  'award_months',coalesce((select jsonb_agg(to_char(mm,'YYYY-MM') order by mm) from public.school_years sy, generate_series(date_trunc('month',sy.start_date::timestamp),date_trunc('month',least(sy.end_date,(now() at time zone 'Asia/Ho_Chi_Minh')::date)::timestamp),interval '1 month') mm where sy.id=y),'[]'),
 'subjects',coalesce((select jsonb_agg(to_jsonb(x) order by x.sort_order,x.name)from public.class_subjects x where x.class_id=c),'[]'),
 'groups',coalesce((select jsonb_agg(to_jsonb(x) order by x.name)from public.english_groups x where x.class_id=c and (a.role::text<>'student' or exists(select 1 from public.english_group_members m where m.english_group_id=x.id and m.student_id=a.id and m.left_at is null))),'[]'),
 'notices',coalesce((select jsonb_agg(homework_private.card(x,a.id) order by x.due_at,x.created_at)from public.homework_notices x where x.class_id=c and x.status='published' and homework_private.visible(x,a)),'[]'),
 'history',coalesce((select jsonb_agg(homework_private.card(x,a.id) order by x.created_at desc)from public.homework_notices x where x.class_id=c and x.author_id=a.id),'[]'),
 'queue','[]'::jsonb,'trash','[]'::jsonb,'audit','[]'::jsonb,'members','[]'::jsonb,'learners','[]'::jsonb);
 if a.role::text in('monitor','teacher') then
 r:=r||jsonb_build_object('queue',coalesce((select jsonb_agg((case when a.role::text='monitor' then homework_private.queue_card(x) else homework_private.card(x,a.id) end)||jsonb_build_object('candidate',case when a.role::text='monitor' then homework_private.queue_card(o) else homework_private.card(o,a.id) end)||
 case when a.role::text in('teacher','admin') then jsonb_build_object('score',rv.score,'reason',rv.reason,'decision',rv.decision)else '{}'::jsonb end order by x.pending_since)
 from public.homework_notices x left join public.homework_notices o on o.id=x.duplicate_of left join public.homework_duplicate_reviews rv on rv.notice_id=x.id and rv.revision=x.revision
 where x.class_id=c and homework_private.actionable(x)),'[]'));
 end if;
 if a.role::text in('teacher','admin') then
 r:=r||jsonb_build_object('settings',jsonb_build_object('seed_threshold',st.seed_threshold),
 'trash',coalesce((select jsonb_agg(homework_private.card(x,a.id)||jsonb_build_object('delete_reason',x.delete_reason) order by x.deleted_at desc)from public.homework_notices x where x.class_id=c and x.status='deleted'),'[]'),
 'audit',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc)from (select * from public.homework_contribution_events where class_id=c order by created_at desc limit 300)x),'[]'),
 'members',coalesce((select jsonb_agg(to_jsonb(m)) from public.english_group_members m join public.english_groups eg on eg.id=m.english_group_id where eg.class_id=c and m.left_at is null),'[]'),
 'learners',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name))from public.profiles p where p.class_id=c and p.active and p.deleted_at is null and p.role::text in('student','monitor')),'[]'));
 end if;
 if a.role::text='teacher' then
 r:=r||jsonb_build_object('ai_settings',homework_private.ai_config(st),
 'review_history',coalesce((select jsonb_agg(homework_private.card(x,a.id)||jsonb_build_object('candidate',homework_private.card(o,a.id),'score',rv.score,'reason',rv.reason,'decision',rv.decision) order by x.updated_at desc)
 from public.homework_notices x left join public.homework_notices o on o.id=x.duplicate_of left join public.homework_duplicate_reviews rv on rv.notice_id=x.id and rv.revision=x.revision
 where x.class_id=c and x.status='duplicate_rejected'),'[]'));
 end if;
 r:=r||jsonb_build_object('history_markers',coalesce((select jsonb_agg(jsonb_build_object('notice_id',t.notice_id,'marker','[Đã xóa vĩnh viễn]','original_created_at',t.original_created_at,'hard_deleted_at',t.hard_deleted_at) order by t.original_created_at desc)from public.homework_tombstones t where t.class_id=c and t.author_id=a.id),'[]'),
 'tombstones',case when a.role::text='admin' then coalesce((select jsonb_agg(to_jsonb(t) order by t.hard_deleted_at desc)from public.homework_tombstones t where t.class_id=c),'[]')
 when a.role::text='teacher' then coalesce((select jsonb_agg(jsonb_build_object('notice_id',t.notice_id,'event','Admin đã xóa vĩnh viễn notice','hard_deleted_at',t.hard_deleted_at) order by t.hard_deleted_at desc)from public.homework_tombstones t where t.class_id=c),'[]')else '[]'::jsonb end);
 -- Independent rankings; current validity is authoritative, timestamps attribute
 -- each event to its original week. No derived point total or weekly reset.
 r:=r||jsonb_build_object('leaderboard',coalesce((select jsonb_agg(to_jsonb(l))from (
 with counts as(select p.id,p.full_name,
 (select count(*) from public.homework_notices x where x.author_id=p.id and x.class_id=c and x.status='published' and x.published_at>=win_start and x.published_at<win_end) notices,
 (select count(*) from public.homework_notice_reactions hr join public.homework_notices x on x.id=hr.notice_id where x.author_id=p.id and x.class_id=c and x.status='published' and x.published_at>=win_start and x.published_at<win_end) hearts,
 (select count(*) from public.homework_notices x where x.author_id=p.id and x.class_id=c and x.school_year_id=y and x.status='published') year_notices,
 (select x.published_at from public.homework_notices x where x.author_id=p.id and x.class_id=c and x.school_year_id=y and x.status='published' order by x.published_at,x.id offset (st.seed_threshold-1) limit 1) seed_at
 from public.profiles p where p.class_id=c and p.role::text in('student','monitor'))
 select *,dense_rank()over(order by notices desc) notice_rank,dense_rank()over(order by hearts desc) heart_rank from counts)l),'[]'),
 'notifications',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc)from (select id,title,message,kind,notice_id,is_read,created_at from public.homework_notifications hn where recipient_id=a.id and class_id=c and homework_private.notification_visible(hn,a) order by created_at desc limit 100)x),'[]'));
 if a.role::text='admin' then r:=r||jsonb_build_object('alert_level',coalesce((select alert_level from public.homework_admin_preferences where admin_id=a.id),'system'),
 'health',jsonb_build_object('total',(select count(*)from public.homework_notices where class_id=c),'pending',(select count(*)from public.homework_notices where class_id=c and homework_private.actionable(homework_notices))));end if;
 return r;
 elsif p_action='read_notification' then update public.homework_notifications set is_read=true where id=(p_data->>'id')::uuid and recipient_id=a.id and class_id=c;return '{"ok":true}';
 elsif p_action='settings' then
 if a.role::text<>'admin' then raise exception 'Chỉ Admin được đổi cấu hình thi đua' using errcode='42501';end if;
 if exists(select 1 from jsonb_object_keys(p_data) k where k not in('class_id','seed_threshold')) then raise exception 'Chỉ ngưỡng Mầm xanh được cấu hình';end if;
 update public.homework_settings set seed_threshold=(p_data->>'seed_threshold')::int where class_id=c;
 perform homework_private.audit(c,null,a.id,'settings',jsonb_build_object('seed_threshold',st.seed_threshold),p_data);return '{"ok":true}';
 elsif p_action='ai_settings' then
 if a.role::text<>'teacher' then raise exception 'Chỉ Teacher được đổi cấu hình AI' using errcode='42501';end if;
 if exists(select 1 from jsonb_object_keys(p_data) k where k not in('class_id','semantic_duplicate_enabled','duplicate_review_threshold','duplicate_auto_threshold'))
 or jsonb_typeof(p_data->'semantic_duplicate_enabled') is distinct from 'boolean'
 or jsonb_typeof(p_data->'duplicate_review_threshold') is distinct from 'number'
 or jsonb_typeof(p_data->'duplicate_auto_threshold') is distinct from 'number'
 then raise exception 'Cấu hình AI không hợp lệ';end if;
 if (p_data->>'duplicate_review_threshold')::numeric<>trunc((p_data->>'duplicate_review_threshold')::numeric)
 or (p_data->>'duplicate_auto_threshold')::numeric<>trunc((p_data->>'duplicate_auto_threshold')::numeric)then raise exception 'Ngưỡng AI phải là số nguyên';end if;
 before_json:=homework_private.ai_config(st);
 update public.homework_settings set semantic_duplicate_enabled=(p_data->>'semantic_duplicate_enabled')::boolean,
 pending_threshold=(p_data->>'duplicate_review_threshold')::numeric::int,reject_threshold=(p_data->>'duplicate_auto_threshold')::numeric::int where class_id=c returning * into st;
 perform homework_private.audit(c,null,a.id,'ai_settings',before_json,homework_private.ai_config(st));return '{"ok":true}';
 elsif p_action='alert_settings' then
 if a.role::text<>'admin' then raise exception 'Chỉ Admin được đổi cảnh báo' using errcode='42501';end if;
 insert into public.homework_admin_preferences(admin_id,alert_level)values(a.id,p_data->>'alert_level')on conflict(admin_id)do update set alert_level=excluded.alert_level;
 perform homework_private.audit(c,null,a.id,'alert_settings',null,p_data);return '{"ok":true}';
 elsif p_action in('subject_save','group_save','group_assign') then
 if a.role::text<>'teacher' then raise exception 'Chỉ giáo viên được cấu hình' using errcode='42501';end if;
 if p_action='subject_save' then
 rid:=nullif(p_data->>'id','')::uuid;
 if rid is null then insert into public.class_subjects(class_id,name,short_name,icon,sort_order,is_english)values(c,trim(p_data->>'name'),coalesce(p_data->>'short_name',''),coalesce(p_data->>'icon','📚'),coalesce((p_data->>'sort_order')::int,0),coalesce((p_data->>'is_english')::boolean,false))returning id into rid;
 else
 select * into s from public.class_subjects where id=rid and class_id=c;
 if s.id is null then raise exception 'Không tìm thấy môn';end if;
 if s.is_english is distinct from coalesce((p_data->>'is_english')::boolean,s.is_english) and exists(select 1 from public.homework_notices where subject_id=rid)then raise exception 'Môn đã có bài; hãy tạo môn mới để giữ lịch sử';end if;
 update public.class_subjects set name=trim(p_data->>'name'),short_name=coalesce(p_data->>'short_name',short_name),icon=coalesce(p_data->>'icon',icon),sort_order=coalesce((p_data->>'sort_order')::int,sort_order),is_english=coalesce((p_data->>'is_english')::boolean,is_english),is_active=coalesce((p_data->>'is_active')::boolean,is_active),updated_at=now()where id=rid;
 end if;
 elsif p_action='group_save' then
 rid:=nullif(p_data->>'id','')::uuid;
 if rid is null then insert into public.english_groups(class_id,school_year_id,name)values(c,y,trim(p_data->>'name'))returning id into rid;
 else update public.english_groups set name=trim(p_data->>'name'),is_active=coalesce((p_data->>'is_active')::boolean,is_active)where id=rid and class_id=c;if not found then raise exception 'Không tìm thấy nhóm';end if;end if;
 else
 target:=(p_data->>'student_id')::uuid;rid:=(p_data->>'english_group_id')::uuid;
 if not exists(select 1 from public.profiles where id=target and class_id=c and active and role::text in('student','monitor'))or not exists(select 1 from public.english_groups where id=rid and class_id=c and school_year_id=y and is_active)then raise exception 'Nhóm/học sinh không hợp lệ';end if;
 update public.english_group_members set left_at=now()where student_id=target and school_year_id=y and left_at is null;
 insert into public.english_group_members(english_group_id,student_id,school_year_id)values(rid,target,y);
 end if;
 perform homework_private.audit(c,null,a.id,p_action,null,p_data);return jsonb_build_object('id',rid);
 end if;
 if p_action='submit' then
 rid:=nullif(p_data->>'id','')::uuid;
 if rid is not null then
 select * into old from public.homework_notices where id=rid and class_id=c;
 if old.id is null or old.status in('deleted','replaced') then raise exception 'Không thể sửa bài này';end if;
 if old.author_id<>a.id and not(a.role::text in('admin','teacher','monitor') and exists(select 1 from public.profiles where id=old.author_id and role::text in('student','monitor')))then raise exception 'Không có quyền sửa bài' using errcode='42501';end if;
 -- Monitor cannot alter pending/rejected cases through the edit endpoint.
 if a.role::text='monitor' and old.author_id<>a.id and old.status<>'published' then raise exception 'Cán sự chỉ được xem case đang chờ' using errcode='42501';end if;
 if not homework_private.visible(old,a) then raise exception 'Ngoài nhóm Tiếng Anh' using errcode='42501';end if;
 if (p_data->>'revision')::int is distinct from old.revision then raise exception 'Bài đã thay đổi; hãy tải lại';end if;
 end if;
 select * into s from public.class_subjects where id=(p_data->>'subject_id')::uuid and class_id=c and is_active;
 if s.id is null then raise exception 'Môn không hoạt động';end if;
 target:=nullif(p_data->>'english_group_id','')::uuid;
 if s.is_english then
 select * into g from public.english_groups where id=target and class_id=c and school_year_id=y and is_active;
 if g.id is null then raise exception 'Cần chọn nhóm Tiếng Anh';end if;
 if a.role::text='student' and not exists(select 1 from public.english_group_members where student_id=a.id and english_group_id=g.id and left_at is null)then raise exception 'Ngoài nhóm Tiếng Anh' using errcode='42501';end if;
 elsif target is not null then raise exception 'Môn này không dùng nhóm Tiếng Anh';end if;
 if rid is null then
 insert into public.homework_notices(class_id,school_year_id,subject_id,english_group_id,author_id,title,content,due_at,request_id)
 values(c,y,s.id,target,a.id,trim(p_data->>'title'),trim(p_data->>'content'),(p_data->>'due_at')::timestamptz,(p_data->>'request_id')::uuid)
 on conflict(author_id,request_id)do nothing returning * into n;
 if n.id is null then select * into n from public.homework_notices where author_id=a.id and request_id=(p_data->>'request_id')::uuid;
 if n.class_id<>c then raise exception 'Request không thuộc lớp';end if;return homework_private.card(n,a.id);end if;
 else
 before_json:=to_jsonb(old);
 -- Only whitespace-only text edits with a <24h deadline shift skip semantic
 -- review. Any other text change is classified by server AI before restoring
 -- publication. The prior publication timestamp and reactions are preserved.
 pending:=old.status<>'published' or s.id<>old.subject_id or target is distinct from old.english_group_id
 or abs(extract(epoch from ((p_data->>'due_at')::timestamptz-old.due_at)))>=86400
 or regexp_replace(trim(p_data->>'title'),'\s+',' ','g')<>regexp_replace(old.title,'\s+',' ','g')
 or regexp_replace(trim(p_data->>'content'),'\s+',' ','g')<>regexp_replace(old.content,'\s+',' ','g');
 update public.homework_notices set subject_id=s.id,english_group_id=target,title=trim(p_data->>'title'),content=trim(p_data->>'content'),due_at=(p_data->>'due_at')::timestamptz,
 revision=revision+1,updated_at=now(),pending_since=case when pending then now()else pending_since end,status=case when pending then 'pending_duplicate_review'else status end,duplicate_of=case when pending then null else duplicate_of end,duplicate_tombstone_id=case when pending then null else duplicate_tombstone_id end
 where id=rid returning * into n;
 end if;
 perform homework_private.audit(c,n.id,a.id,'submit',before_json,to_jsonb(n));
 return homework_private.card(n,a.id);
 end if;
 select * into n from public.homework_notices where id=(p_data->>'id')::uuid and class_id=c;
 if n.id is null then raise exception 'Không tìm thấy bài';end if;
 if not homework_private.visible(n,a) and n.author_id<>a.id then raise exception 'Ngoài nhóm Tiếng Anh' using errcode='42501';end if;
 before_json:=to_jsonb(n);
 if p_action='retry' then
 -- Retry reuses the existing edit permission; no content/status/revision change.
 if not homework_private.visible(n,a) or (n.author_id<>a.id and not(a.role::text in('teacher','admin') and exists(select 1 from public.profiles where id=n.author_id and role::text in('student','monitor'))))then raise exception 'Không có quyền kiểm tra lại bài' using errcode='42501';end if;
 if n.status<>'pending_duplicate_review' then return homework_private.card(n,a.id);end if;
 if not exists(select 1 from public.homework_duplicate_reviews rv where rv.notice_id=n.id and rv.revision=n.revision and (rv.score is not null or rv.decision is not null))then
 perform homework_private.audit(c,n.id,a.id,'ai_retry_requested',null,jsonb_build_object('revision',n.revision));end if;
 return homework_private.card(n,a.id);
 elsif p_action='heart' then
 if n.status<>'published' or not homework_private.visible(n,a)then raise exception 'Bài không nhận tim';end if;
 if n.author_id=a.id then raise exception 'Không được tự thả tim';end if;
 if (p_data->>'liked')::boolean then insert into public.homework_notice_reactions(notice_id,user_id)values(n.id,a.id)on conflict do nothing;
 else delete from public.homework_notice_reactions where notice_id=n.id and user_id=a.id;end if;
 if found then perform homework_private.audit(c,n.id,a.id,case when (p_data->>'liked')::boolean then 'heart_received'else 'heart_removed'end);end if;
 elsif p_action='remind' then
 if a.role::text not in('admin','teacher','monitor')then raise exception 'Không có quyền nhắc' using errcode='42501';end if;
 if n.status<>'published' then raise exception 'Chỉ nhắc bài đã công bố';end if;
 -- Cross-class actor quota has its own lock, always after class lock.
 perform pg_advisory_xact_lock(hashtextextended('homework-reminder-actor:'||a.id::text,0));
 if (select count(*)from public.homework_notice_reminders where notice_id=n.id and sent_at>now()-interval '24 hours')>=2
 or exists(select 1 from public.homework_notice_reminders where notice_id=n.id and sent_at>now()-interval '6 hours')
 or (select count(*)from public.homework_notice_reminders where sent_by=a.id and sent_at>now()-interval '24 hours')>=10 then raise exception 'Đã đạt giới hạn nhắc: 2 lần/bài/24 giờ, cách 6 giờ; 10 lần/người/24 giờ';end if;
 insert into public.homework_notice_reminders(notice_id,sent_by)values(n.id,a.id);
 insert into public.homework_notifications(class_id,recipient_id,notice_id,kind,title,message)
 select c,p.id,n.id,'reminder','🔔 Nhắc học tập',n.title||' — hạn '||to_char(n.due_at at time zone 'Asia/Ho_Chi_Minh','HH24:MI DD/MM/YYYY')from public.profiles p
 where p.class_id=c and p.active and p.deleted_at is null and p.role::text in('student','monitor')and homework_private.visible(n,p);
 perform homework_private.audit(c,n.id,a.id,'reminder');
 elsif p_action='delete' then
 if n.author_id<>a.id and not(a.role::text in('admin','teacher','monitor') and exists(select 1 from public.profiles where id=n.author_id and role::text in('student','monitor')))then raise exception 'Không có quyền xóa bài' using errcode='42501';end if;
 if a.role::text='monitor' and n.author_id<>a.id and n.status<>'published' then raise exception 'Cán sự chỉ được xem case đang chờ' using errcode='42501';end if;
 if length(trim(coalesce(p_data->>'reason','')))=0 then raise exception 'Cần lý do xóa';end if;
 if n.status='deleted' then return '{"ok":true}';end if;
 update public.homework_notices set previous_status=status,status='deleted',deleted_at=now(),deleted_by=a.id,delete_reason=trim(p_data->>'reason'),revision=revision+1,updated_at=now()where id=n.id;
 perform homework_private.audit(c,n.id,a.id,'notice_invalidated',before_json,p_data);
 elsif p_action='restore' then
 if a.role::text not in('admin','teacher')then raise exception 'Không có quyền khôi phục' using errcode='42501';end if;
 if n.status<>'deleted' then raise exception 'Bài không trong thùng rác';end if;
 -- Never resurrect a replaced/rejected post as published. A formerly published
 -- post is rechecked if the board changed while deleted.
 update public.homework_notices set status=case when previous_status='published' and exists(select 1 from public.homework_notices x where x.id<>n.id and x.class_id=c and x.subject_id=n.subject_id and x.english_group_id is not distinct from n.english_group_id and x.status='published' and abs(extract(epoch from(x.due_at-n.due_at)))<=86400 and not exists(select 1 from public.homework_duplicate_reviews rv where rv.decision='keep_both' and ((rv.notice_id=x.id and rv.candidate_id=n.id)or(rv.notice_id=n.id and rv.candidate_id=x.id)) and not exists(select 1 from public.homework_contribution_events ev where ev.notice_id in(x.id,n.id) and ev.event_type='submit' and ev.created_at>rv.decided_at)))then 'pending_duplicate_review'else coalesce(previous_status,'pending_duplicate_review')end,
 deleted_at=null,deleted_by=null,delete_reason=null,revision=revision+1,pending_since=now(),updated_at=now()where id=n.id;
 perform homework_private.audit(c,n.id,a.id,'notice_restored',before_json,null);
 elsif p_action='review' then
 if a.role::text not in('admin','teacher')then raise exception 'Không có quyền quyết định AI' using errcode='42501';end if;
 if n.status not in('pending_duplicate_review','duplicate_rejected')then raise exception 'Case đã được xử lý';end if;
 if not exists(select 1 from public.homework_duplicate_reviews rv where rv.notice_id=n.id and rv.revision=n.revision and rv.score is not null and rv.candidate_id=n.duplicate_of)then raise exception 'Chưa có kết quả so sánh hợp lệ cho phiên bản hiện tại';end if;
 decision:=p_data->>'decision';
 if decision is null or decision not in('keep_existing','replace_existing','keep_both')then raise exception 'Quyết định không hợp lệ';end if;
 select * into old from public.homework_notices where id=n.duplicate_of and class_id=c;
 if decision='keep_both' and length(trim(coalesce(p_data->>'reason','')))=0 then raise exception 'Giữ cả hai cần lý do';end if;
 if old.id is null then
 raise exception 'Chưa có kết quả so sánh hợp lệ; bài tiếp tục chờ kiểm tra';
 else
 if old.status<>'published' then raise exception 'Bài gốc đã thay đổi; cần kiểm tra AI lại';end if;
 if decision='replace_existing' then update public.homework_notices set status='replaced',revision=revision+1,updated_at=now()where id=old.id;
 perform homework_private.audit(c,old.id,a.id,'notice_replaced',to_jsonb(old),jsonb_build_object('replacement',n.id));end if;
 end if;
 update public.homework_notices set status=case when decision='keep_existing'then 'duplicate_rejected'else 'published'end,
 published_at=case when decision='keep_existing'then published_at else coalesce(published_at,now())end,updated_at=now()where id=n.id;
 insert into public.homework_duplicate_reviews(notice_id,revision,candidate_id,decision,decided_by,decision_reason,decided_at)
 values(n.id,n.revision,n.duplicate_of,decision,a.id,p_data->>'reason',now())on conflict(notice_id,revision)do update set decision=excluded.decision,decided_by=excluded.decided_by,decision_reason=excluded.decision_reason,decided_at=now();
 perform homework_private.audit(c,n.id,a.id,'review_'||decision,before_json,p_data);
 else raise exception 'Thao tác không hợp lệ';end if;
 perform homework_private.backlog(c);return '{"ok":true}';
end$function$;
CREATE OR REPLACE FUNCTION homework_private.api_v4(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.profiles;c uuid:=nullif(p_data->>'class_id','')::uuid;g public.grade_subject_catalog;
 s public.class_subjects;rid uuid:=nullif(p_data->>'id','')::uuid;gr integer:=nullif(p_data->>'grade','')::integer;
 out_data jsonb;before_json jsonb;scope uuid[];lim integer:=least(100,greatest(1,coalesce((p_data->>'limit')::int,100)));
 offst integer:=greatest(0,coalesce((p_data->>'offset')::int,0));start_at timestamptz:=nullif(p_data->>'from','')::timestamptz;
 end_at timestamptz:=nullif(p_data->>'to','')::timestamptz;who uuid:=nullif(p_data->>'actor_id','')::uuid;
 state text:=nullif(p_data->>'status','');event text:=nullif(p_data->>'event_type','');
begin
 select * into a from public.profiles where id=auth.uid() and active and deleted_at is null;
 if a.id is null then raise exception 'Cần đăng nhập' using errcode='42501';end if;
 if gr is not null and gr not between 6 and 12 then raise exception 'Khối không hợp lệ';end if;
 if p_action='context' then
 return jsonb_build_object('weeks',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'school_year_id',w.school_year_id,'week_number',w.week_number) order by w.start_date)from public.weeks w where a.role::text='admin' or exists(select 1 from public.classes x where x.school_year_id=w.school_year_id and x.active and ((a.role::text='teacher' and exists(select 1 from public.class_teachers t where t.class_id=x.id and t.teacher_id=a.id and t.active))or(a.role::text in('student','monitor') and a.class_id=x.id)))),'[]'),'grades',jsonb_build_array(6,7,8,9,10,11,12),'classes',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'code',x.code,'name',x.name,'grade',x.grade,'active',x.active,'school_year_id',x.school_year_id) order by x.grade,x.code,x.id)
 from public.classes x where a.role::text='admin' or (x.active and ((a.role::text='teacher' and exists(select 1 from public.class_teachers t where t.class_id=x.id and t.teacher_id=a.id and t.active))or(a.role::text in('student','monitor') and a.class_id=x.id)))),'[]'));
 end if;
 if p_action in('catalog_list','catalog_save','oversight') then
 if a.role::text<>'admin' then raise exception 'Chỉ Admin được giám sát/catalog' using errcode='42501';end if;
 if c is not null and not exists(select 1 from public.classes where id=c and (gr is null or grade=gr)) then raise exception 'Khối/lớp không khớp';end if;
 if p_action='catalog_list' then return coalesce((select jsonb_agg(to_jsonb(x) order by grade,sort_order,name) from public.grade_subject_catalog x where gr is null or x.grade=gr),'[]');end if;
 if p_action='catalog_save' then
 if exists(select 1 from jsonb_object_keys(p_data) k where k not in('class_id','id','grade','name','short_name','icon','sort_order','is_active','is_english')) then raise exception 'Payload catalog không hợp lệ';end if;
 if gr is null then raise exception 'Cần chọn khối';end if;
 -- Catalog edits and class activation share row locks; no inactive activation race.
 if rid is not null then
 select * into g from public.grade_subject_catalog where id=rid and grade=gr for update;
 if not found then raise exception 'Không tìm thấy môn catalog';end if;before_json:=to_jsonb(g);
 if g.is_english is distinct from coalesce((p_data->>'is_english')::boolean,g.is_english) and exists(select 1 from public.class_subjects cs where cs.catalog_subject_id=rid and (exists(select 1 from public.homework_notices n where n.subject_id=cs.id)or exists(select 1 from public.homework_tombstones t where t.subject_id=cs.id))) then raise exception 'Môn đã có lịch sử; giữ nguyên loại Tiếng Anh';end if;
 update public.grade_subject_catalog set name=trim(p_data->>'name'),short_name=coalesce(p_data->>'short_name',short_name),icon=coalesce(p_data->>'icon',icon),sort_order=coalesce((p_data->>'sort_order')::int,sort_order),is_active=coalesce((p_data->>'is_active')::boolean,is_active),is_english=coalesce((p_data->>'is_english')::boolean,is_english),updated_at=now() where id=rid returning * into g;
 else
 insert into public.grade_subject_catalog(grade,name,short_name,icon,sort_order,is_active,is_english) values(gr,trim(p_data->>'name'),coalesce(p_data->>'short_name',''),coalesce(p_data->>'icon','📚'),coalesce((p_data->>'sort_order')::int,0),coalesce((p_data->>'is_active')::boolean,true),coalesce((p_data->>'is_english')::boolean,false)) returning * into g;rid:=g.id;
 end if;
 update public.class_subjects set name=g.name,short_name=g.short_name,icon=g.icon,is_english=g.is_english,updated_at=now() where catalog_subject_id=rid;
 insert into public.homework_catalog_events(grade,actor_id,catalog_id,before_data,after_data)values(gr,a.id,rid,before_json,to_jsonb(g));
 perform homework_private.audit(cs.class_id,null,a.id,'catalog_save',before_json,to_jsonb(g)) from (select distinct class_id from public.class_subjects where catalog_subject_id=rid)cs;
 return to_jsonb(g);
 end if;
 select coalesce(array_agg(id),'{}'::uuid[])into scope from public.classes where (c is null or id=c)and(gr is null or grade=gr);
 if start_at is not null and end_at is not null and start_at>=end_at then raise exception 'Khoảng thời gian không hợp lệ';end if;
 out_data:=jsonb_build_object('metrics',(select jsonb_build_object('published',count(*)filter(where status='published'),'week',count(*)filter(where published_at>=date_trunc('week',now() at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh' and status='published'),'pending',count(*)filter(where homework_private.actionable(n)),'deleted',count(*)filter(where status='deleted'),'contributors',count(distinct author_id)filter(where status='published' and exists(select 1 from public.profiles p where p.id=n.author_id and p.role::text in('student','monitor'))))from public.homework_notices n where class_id=any(scope)),
 'hearts',(select count(*)from public.homework_notice_reactions r join public.homework_notices n on n.id=r.notice_id where n.class_id=any(scope)and n.status='published'));
 return out_data||jsonb_build_object(
 'history',coalesce((select jsonb_agg(row_data order by happened desc,id)from(
 select n.id,n.created_at happened,homework_private.card(n,a.id) row_data from public.homework_notices n where n.class_id=any(scope)and(who is null or n.author_id=who)and(state is null or n.status=state)and(start_at is null or n.created_at>=start_at)and(end_at is null or n.created_at<end_at)
 union all select t.notice_id,t.original_created_at,to_jsonb(t)||jsonb_build_object('id',t.notice_id,'status','hard_deleted','marker','[Đã xóa vĩnh viễn]')from public.homework_tombstones t where t.class_id=any(scope)and(who is null or t.author_id=who)and(state is null or state='hard_deleted')and(start_at is null or t.original_created_at>=start_at)and(end_at is null or t.original_created_at<end_at)
 order by happened desc,id limit lim offset offst)x),'[]'),
 'audit',coalesce((select jsonb_agg(x.row_data order by x.created_at desc,x.id)from(
 select *from(
 select e.id,e.class_id,e.actor_id,e.event_type,e.created_at,to_jsonb(e)row_data from public.homework_contribution_events e where e.class_id=any(scope)
 union all select t.notice_id,t.class_id,t.hard_deleted_by,'hard_delete',t.hard_deleted_at,jsonb_build_object('id',t.notice_id,'class_id',t.class_id,'actor_id',t.hard_deleted_by,'event_type','hard_delete','created_at',t.hard_deleted_at,'before_data',null,'after_data',to_jsonb(t))from public.homework_tombstones t where t.class_id=any(scope)
 )e where (who is null or e.actor_id=who)and(event is null or e.event_type=event)and(start_at is null or e.created_at>=start_at)and(end_at is null or e.created_at<end_at)order by created_at desc,id limit lim offset offst)x),'[]'),
 'catalog_audit',coalesce((select jsonb_agg(to_jsonb(x)order by x.created_at desc,x.id)from(select *from public.homework_catalog_events e where c is null and(gr is null or e.grade=gr)and(who is null or e.actor_id=who)and(event is null or e.event_type=event)and(start_at is null or e.created_at>=start_at)and(end_at is null or e.created_at<end_at)order by created_at desc,id limit lim offset offst)x),'[]'),
 'trash',coalesce((select jsonb_agg(row_data order by deleted_at desc,id)from(select n.id,n.deleted_at,homework_private.card(n,a.id)||jsonb_build_object('delete_reason',n.delete_reason)row_data from public.homework_notices n where n.class_id=any(scope)and status='deleted'order by n.deleted_at desc,n.id limit lim offset offst)x),'[]'),
 'people',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name)order by p.full_name)from public.profiles p where p.class_id=any(scope)or p.id in(select actor_id from public.homework_contribution_events where class_id=any(scope))or p.id in(select hard_deleted_by from public.homework_tombstones where class_id=any(scope))or(c is null and p.id in(select actor_id from public.homework_catalog_events where gr is null or grade=gr))),'[]'));
 end if;
 -- Lock assignment/class rows so deactivation cannot race an authorized mutation.
 perform 1 from public.classes where id=c for share;
 if a.role::text='teacher' then perform 1 from public.class_teachers where class_id=c and teacher_id=a.id for share;end if;
 a:=homework_private.actor(c);
 if p_action='subject_save' then
 if a.role::text<>'teacher' then raise exception 'Chỉ Teacher được cấu hình môn lớp' using errcode='42501';end if;
 if exists(select 1 from jsonb_object_keys(p_data) k where k not in('class_id','id','catalog_subject_id','sort_order','is_active')) then raise exception 'Chỉ sửa thứ tự/trạng thái môn lớp';end if;
 select *into g from public.grade_subject_catalog where id=(p_data->>'catalog_subject_id')::uuid and grade=(select grade from public.classes where id=c)for share;
 if not found then raise exception 'Catalog không thuộc khối lớp';end if;
 perform pg_advisory_xact_lock(hashtextextended('homework:'||c::text,0));
 if rid is null then select *into s from public.class_subjects where class_id=c and catalog_subject_id=g.id order by created_at,id limit 1;rid:=s.id;
 else select *into s from public.class_subjects where id=rid and class_id=c and catalog_subject_id=g.id;if not found then raise exception 'Môn không thuộc lớp/catalog';end if;end if;
 before_json:=case when s.id is null then null else to_jsonb(s)end;
 if rid is null then insert into public.class_subjects(class_id,catalog_subject_id,name,sort_order,is_active)values(c,g.id,g.name,coalesce((p_data->>'sort_order')::int,g.sort_order),coalesce((p_data->>'is_active')::boolean,true))returning id into rid;
 else update public.class_subjects set sort_order=coalesce((p_data->>'sort_order')::int,sort_order),is_active=coalesce((p_data->>'is_active')::boolean,is_active),updated_at=now()where id=rid;end if;
 perform homework_private.audit(c,null,a.id,'subject_save',before_json,(select to_jsonb(x)from public.class_subjects x where id=rid));return jsonb_build_object('id',rid);
 end if;
 out_data:=homework_private.api_v3(p_action,p_data);
 if p_action='load' and a.role::text='teacher' then out_data:=out_data||jsonb_build_object('history',coalesce((select jsonb_agg(homework_private.card(n,a.id) order by n.created_at desc,n.id)from public.homework_notices n where n.class_id=c),'[]'),'catalog',coalesce((select jsonb_agg(to_jsonb(cat) order by cat.sort_order,cat.name)from public.grade_subject_catalog cat where cat.is_active and cat.grade=(select grade from public.classes where id=c)),'[]'));end if;
 return out_data;
end$function$;
CREATE OR REPLACE FUNCTION homework_private.api_v5(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c uuid:=nullif(p_data->>'class_id','')::uuid;a public.profiles;n public.homework_notices;
 cor public.homework_corrections;rr public.homework_correction_rounds;rep public.homework_reports;
 rid uuid:=nullif(p_data->>'id','')::uuid;why text:=trim(coalesce(p_data->>'reason',''));issues text[];
 out_data jsonb;payload jsonb;stamp timestamptz;
begin
 if p_action in('context','catalog_list','catalog_save','oversight') then return homework_private.api_v4(p_action,p_data);end if;
 perform 1 from public.profiles where id=auth.uid() for share;
 perform 1 from public.classes where id=c for share;
 perform 1 from public.class_teachers where class_id=c and teacher_id=auth.uid() for share;
 a:=homework_private.actor(c);
 perform pg_advisory_xact_lock(hashtextextended('homework:'||c::text,0));
 if a.role::text='admin' and p_action not in('load','inbox','read_notification','settings','alert_settings','hard_delete') then raise exception 'Admin chỉ giám sát Báo bài' using errcode='42501';end if;

 if p_action='load' then
  out_data:=homework_private.api_v4(p_action,p_data);
  if a.role::text in('student','monitor','teacher') then
   out_data:=out_data||jsonb_build_object('corrections',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('rounds',(select jsonb_agg(to_jsonb(r) order by r.round)from public.homework_correction_rounds r where r.correction_id=x.id),
    'events',(select coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('actor_name',(select full_name from public.profiles where id=e.actor_id)) order by e.created_at),'[]') from public.homework_moderation_events e where e.correction_id=x.id and e.report_id is null)))
    from public.homework_corrections x join public.homework_notices hn on hn.id=x.notice_id where x.class_id=c and (hn.author_id=a.id or a.role::text='teacher')),'[]'));
  end if;
  if a.role::text='teacher' then
   out_data:=jsonb_set(out_data,'{audit}',coalesce(out_data->'audit','[]')||coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'event_type',e.event_type,'actor_id',e.actor_id,'notice_id',e.notice_id,'created_at',e.created_at,'before_data',null,'after_data',jsonb_build_object('actor_type',e.actor_type,'round',e.round,'reason',e.reason,'report_id',e.report_id,'correction_id',e.correction_id)) order by e.created_at desc) from public.homework_moderation_events e where e.class_id=c),'[]'));
   out_data:=out_data||jsonb_build_object('reports',coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('reporter_name',p.full_name,'reporter_code',coalesce(to_jsonb(p)->>'student_code',to_jsonb(p)->>'username',to_jsonb(p)->>'login_code'),
    'class_name',(select code from public.classes where id=r.class_id),'events',(select coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('actor_name',(select full_name from public.profiles where id=e.actor_id)) order by e.created_at),'[]')from public.homework_moderation_events e where e.report_id=r.id)) order by r.created_at desc)
    from public.homework_reports r join public.profiles p on p.id=r.reporter_id where r.class_id=c),'[]'),
    'report_statistics',coalesce((select jsonb_agg(to_jsonb(x)) from(select r.reporter_id,p.full_name,count(*) total,count(*)filter(where status='valid') valid,count(*)filter(where status='invalid') invalid,count(*)filter(where status='suspected_abuse') suspected_abuse
    from public.homework_reports r join public.profiles p on p.id=r.reporter_id where r.class_id=c group by r.reporter_id,p.full_name)x),'[]'));
  end if;
  return out_data;
 end if;

 if rid is not null and p_action not in('read_notification','group_save','group_assign','subject_save') then
  select * into n from public.homework_notices where id=rid and class_id=c for update;
 end if;
 if p_action in('submit','delete') and rid is not null then
  if n.id is null or n.author_id<>a.id then raise exception 'Chỉ tác giả được sửa/xóa bài' using errcode='42501';end if;
  if exists(select 1 from public.homework_corrections where notice_id=n.id and status in('awaiting_author','awaiting_teacher')) then raise exception 'Bài đang chỉnh sửa: dùng Gửi lại GV hoặc Xin rút bài';end if;
 end if;
 if p_action='remind' and a.role::text='monitor' and n.author_id is distinct from a.id then raise exception 'Cán sự không nhắc bài người khác' using errcode='42501';end if;
 -- Product decision, 2026-09-15: resolve the target's correction before replacing
 -- it through duplicate review. The shared class lock makes this race-safe with
 -- correction creation/closure and the existing replacement transaction.
 if p_action='review' and a.role::text='teacher' and p_data->>'decision'='replace_existing'
  and exists(select 1 from public.homework_corrections where notice_id=n.duplicate_of and status in('awaiting_author','awaiting_teacher')) then
  raise exception 'Bài cũ đang có yêu cầu chỉnh sửa. GV cần xử lý correction trước khi Thay bài cũ.';
 end if;

 if p_action not in('report','report_process','correction_request','correction_save','correction_submit','correction_decide','withdraw','emergency_remove') then
  return homework_private.api_v4(p_action,p_data);
 end if;
 if n.id is null then raise exception 'Không tìm thấy bài' using errcode='42501';end if;
 if not homework_private.visible(n,a) and n.author_id<>a.id then raise exception 'Ngoài nhóm Tiếng Anh' using errcode='42501';end if;
 if p_action in('report_process','correction_request','correction_decide','emergency_remove') and a.role::text<>'teacher' then raise exception 'Chỉ Teacher lớp được xử lý' using errcode='42501';end if;

 if p_action='report' then
  if a.role::text<>'monitor' or n.author_id=a.id then raise exception 'Chỉ Cán sự báo bài người khác' using errcode='42501';end if;
  if n.status<>'published' then raise exception 'Bài không còn công khai';end if;
  if exists(select 1 from jsonb_object_keys(p_data) k where k not in('class_id','id','category','note','action')) then raise exception 'Report payload không hợp lệ';end if;
  insert into public.homework_reports(class_id,notice_id,reporter_id,category,note)values(c,n.id,a.id,p_data->>'category',nullif(trim(p_data->>'note'),''))returning * into rep;
  perform homework_private.moderation_event(c,n.id,a.id,'report_created',null,null,null,rep.id);
  return '{"ok":true}';
 elsif p_action='report_process' then
  select * into rep from public.homework_reports where id=(p_data->>'report_id')::uuid and notice_id=n.id and class_id=c for update;
  if rep.id is null or rep.status<>'open' then raise exception 'Report đã xử lý hoặc không tồn tại';end if;
  if p_data->>'outcome' is null or p_data->>'outcome' not in('valid','invalid','suspected_abuse') then raise exception 'Kết quả report không hợp lệ';end if;
  update public.homework_reports set status=p_data->>'outcome',teacher_note=nullif(trim(p_data->>'note'),''),processed_at=clock_timestamp(),processed_by=a.id where id=rep.id;
  perform homework_private.moderation_event(c,n.id,a.id,'report_'||(p_data->>'outcome'),p_data->>'note',null,null,rep.id);
  return '{"ok":true}';
 end if;

 if n.status in('deleted','replaced') then raise exception 'Bài đã thay đổi hoặc đã gỡ';end if;
 select * into cor from public.homework_corrections where notice_id=n.id and status in('awaiting_author','awaiting_teacher') for update;
 if p_action='correction_request' then
  if cor.id is not null then raise exception 'Đã có yêu cầu chỉnh sửa đang mở';end if;
  if n.status<>'published' then raise exception 'Chỉ yêu cầu chỉnh sửa bài đã công bố';end if;
  if not exists(select 1 from public.profiles where id=n.author_id and role::text in('student','monitor')) then raise exception 'Chỉ yêu cầu tác giả học sinh/cán sự chỉnh sửa';end if;
  if length(why) not between 1 and 2000 then raise exception 'Cần hướng dẫn chỉnh sửa';end if;
  select array_agg(v) into issues from jsonb_array_elements_text(p_data->'issue_types')v;
  stamp:=clock_timestamp();
  insert into public.homework_corrections(class_id,notice_id)values(c,n.id)returning * into cor;
  insert into public.homework_correction_rounds(correction_id,round,requested_by,requested_at,due_at,issue_types,reason)values(cor.id,1,a.id,stamp,stamp+interval '72 hours',issues,why);
  perform homework_private.moderation_event(c,n.id,a.id,'correction_created',why,cor.id,cor.round);
  perform homework_private.notify_author(n,'requested','GV yêu cầu chỉnh sửa Báo bài. Hạn phản hồi: '||to_char((stamp+interval '72 hours') at time zone 'Asia/Ho_Chi_Minh','HH24:MI DD/MM/YYYY')||'. '||why);
  return to_jsonb(cor);
 elsif p_action='emergency_remove' then
  if not exists(select 1 from public.profiles where id=n.author_id and role::text in('student','monitor')) then raise exception 'Chỉ gỡ bài của học sinh/cán sự';end if;
  if p_data->>'category' is null or p_data->>'category' not in('inappropriate_content','posted_by_mistake','seriously_incorrect_information','other') or length(why) not between 1 and 2000 then raise exception 'Cần loại và lý do gỡ khẩn cấp';end if;
  perform homework_private.correction_delete(n,a.id,'GV gỡ bài ('||(p_data->>'category')||'): '||why,'emergency_removed',cor);
  return '{"ok":true}';
 end if;

 if cor.id is null or (p_data->>'correction_id')::uuid is distinct from cor.id or (p_data->>'round')::int is distinct from cor.round or (p_data->>'version')::int is distinct from cor.version then raise exception 'Yêu cầu đã thay đổi; hãy tải lại';end if;
 select * into rr from public.homework_correction_rounds where correction_id=cor.id and round=cor.round for update;
 if p_action in('correction_save','correction_submit','withdraw') and n.author_id<>a.id then raise exception 'Chỉ tác giả phản hồi' using errcode='42501';end if;
 stamp:=clock_timestamp();
 if cor.status='awaiting_author' and rr.due_at<=stamp then
  perform homework_private.expire_corrections(c);
  return jsonb_build_object('ok',false,'expired',true,'message','Đã hết hạn chỉnh sửa 72 giờ; bài đã được System gỡ.');
 end if;
 if p_action='withdraw' then
  if length(why) not between 1 and 2000 then raise exception 'Xin rút bài cần lý do';end if;
  perform homework_private.correction_delete(n,a.id,'Tác giả xin rút bài: '||why,'withdrawn_by_author',cor);
  return '{"ok":true}';
 elsif p_action in('correction_save','correction_submit') then
  if cor.status<>'awaiting_author' then raise exception 'Revision đã gửi; chờ GV xác nhận';end if;
  payload:=homework_private.validate_revision(n,p_data->'revision_data');
  update public.homework_correction_rounds set draft=payload,submitted_at=case when p_action='correction_submit' then stamp else null end where correction_id=cor.id and round=cor.round;
  update public.homework_corrections set status=case when p_action='correction_submit' then 'awaiting_teacher' else status end,version=version+1 where id=cor.id returning * into cor;
  perform homework_private.moderation_event(c,n.id,a.id,case when p_action='correction_submit' then 'revision_submitted' else 'revision_saved' end,null,cor.id,cor.round);
  return to_jsonb(cor)||jsonb_build_object('ok',true);
 elsif p_action='correction_decide' then
  if cor.status<>'awaiting_teacher' or rr.submitted_at is null then raise exception 'Chưa có revision gửi lại';end if;
  if p_data->>'decision' is null or p_data->>'decision' not in('approved','rejected') then raise exception 'Quyết định không hợp lệ';end if;
  if p_data->>'decision'='rejected' and length(why) not between 1 and 2000 then raise exception 'Chưa đạt cần lý do';end if;
  update public.homework_correction_rounds set decided_by=a.id,decided_at=clock_timestamp(),decision=p_data->>'decision',decision_reason=nullif(why,'')where correction_id=cor.id and round=cor.round;
  perform homework_private.moderation_event(c,n.id,a.id,'correction_'||(p_data->>'decision'),why,cor.id,cor.round);
  if p_data->>'decision'='approved' then
   payload:=homework_private.validate_revision(n,rr.draft);
   out_data:=homework_private.apply_correction(n,payload,a.id);
   update public.homework_corrections set status='approved',closed_at=clock_timestamp(),version=version+1 where id=cor.id;
   perform homework_private.notify_author(n,'approved','GV xác nhận chỉnh sửa đạt. Bài vẫn phải qua kiểm tra nội dung trùng theo quy định.');
   return out_data;
  elsif cor.round=1 then
   stamp:=clock_timestamp();
   insert into public.homework_correction_rounds(correction_id,round,requested_by,requested_at,due_at,issue_types,reason,draft)values(cor.id,2,a.id,stamp,stamp+interval '72 hours',rr.issue_types,why,rr.draft);
   update public.homework_corrections set round=2,status='awaiting_author',version=version+1 where id=cor.id returning * into cor;
   perform homework_private.moderation_event(c,n.id,a.id,'round_2_opened',why,cor.id,cor.round);
   perform homework_private.notify_author(n,'round_2','Lần chỉnh sửa cuối. Bạn có 72 giờ mới để gửi lại GV. '||why);
   return to_jsonb(cor);
  else
   perform homework_private.correction_delete(n,null,'Không đạt sau lần chỉnh sửa cuối. '||why,'rejected_final',cor);
   return '{"ok":true}';
  end if;
 end if;
 raise exception 'Thao tác không hợp lệ';
end $function$;
CREATE OR REPLACE FUNCTION homework_private.api_v6(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.profiles;c uuid:=nullif(p_data->>'class_id','')::uuid;n public.homework_notices;
 m public.homework_attachments;cor public.homework_corrections;rr public.homework_correction_rounds;
 out_data jsonb;mid uuid:=nullif(p_data->>'attachment_id','')::uuid;old_mid uuid;new_mid uuid;
 supplied boolean:=p_data ? 'attachment_id';op uuid:=nullif(p_data->>'media_operation_id','')::uuid;
 receipt public.homework_media_receipts;payload_hash text:=md5(p_action||p_data::text);
begin
 if p_action not in('submit','correction_save','correction_submit','correction_decide','correction_request','hard_delete') then
  if supplied then raise exception 'Thao tác không nhận ảnh';end if;
  return homework_private.api_v5(p_action,p_data);
 end if;
 a:=homework_private.actor(c);
 perform pg_advisory_xact_lock(hashtextextended('homework:'||c::text,0));
 if op is not null then
  select * into receipt from public.homework_media_receipts where owner_id=a.id and operation_id=op;
  if receipt.owner_id is not null then
   if receipt.class_id<>c or receipt.payload_hash<>payload_hash then raise exception 'Yêu cầu gửi lại đã thay đổi';end if;
   if receipt.correction_id is not null then return (select to_jsonb(x)||'{"ok":true}'::jsonb from public.homework_corrections x where x.id=receipt.correction_id);end if;
   return (select homework_private.card(x,a.id) from public.homework_notices x where x.id=receipt.notice_id);
  end if;
 end if;
 if p_action='submit' and nullif(p_data->>'id','') is null then
  select * into n from public.homework_notices where author_id=a.id and request_id=nullif(p_data->>'request_id','')::uuid;
  if n.id is not null then
   if n.class_id<>c then raise exception 'Request không thuộc lớp';end if;
   return homework_private.card(n,a.id);
  end if;
 end if;
 select * into n from public.homework_notices where id=nullif(p_data->>'id','')::uuid and class_id=c for update;
 select attachment_id into old_mid from public.homework_notice_media where notice_id=n.id;
 if n.id is not null then
  select * into cor from public.homework_corrections where notice_id=n.id and status in('awaiting_author','awaiting_teacher');
  select * into rr from public.homework_correction_rounds where correction_id=cor.id and round=cor.round;
 end if;
 if supplied then
  if p_action not in('submit','correction_save','correction_submit') or a.role::text='admin' or (n.id is not null and n.author_id<>a.id) then raise exception 'Chỉ tác giả thay ảnh' using errcode='42501';end if;
  if mid is not null then
   select * into m from public.homework_attachments where id=mid for update;
   if m.id is null or m.owner_id<>a.id or m.class_id<>c or m.status='deleting' or m.verified_at is null then raise exception 'Ảnh chưa được xác minh hoặc không thuộc tác giả' using errcode='42501';end if;
   if m.status='pending' then
    if m.expires_at<=clock_timestamp() or m.notice_id is distinct from n.id then raise exception 'Ảnh chờ hết hạn hoặc sai bài';end if;
    if n.id is null and m.request_id is distinct from nullif(p_data->>'request_id','')::uuid then raise exception 'Sai yêu cầu tạo bài';end if;
    if p_action='submit' and (m.correction_id is not null or (n.id is not null and m.base_revision<>n.revision)) then raise exception 'Ảnh thuộc revision khác';end if;
    if p_action<>'submit' and (m.correction_id is distinct from cor.id or m.correction_round is distinct from cor.round) then raise exception 'Ảnh thuộc correction khác';end if;
   elsif m.notice_id is distinct from n.id or (mid is distinct from old_mid and mid is distinct from rr.attachment_id) then raise exception 'Không thể dùng lại ảnh của bản khác';end if;
  end if;
 end if;
 out_data:=homework_private.api_v5(p_action,p_data-'attachment_id'-'media_operation_id');
 if coalesce((out_data->>'expired')::boolean,false) then return out_data;end if;
 if p_action='hard_delete' then
  if exists(select 1 from public.homework_attachments where notice_id=(p_data->>'id')::uuid and status='deleting') then out_data:=out_data||'{"media_cleanup":"queued"}'::jsonb;end if;
  return out_data;
 elsif p_action='correction_request' then
  update public.homework_correction_rounds set media_set=true,attachment_id=old_mid where correction_id=(out_data->>'id')::uuid and round=1;
 elsif p_action in('correction_save','correction_submit') then
  if supplied then
   update public.homework_correction_rounds set media_set=true,attachment_id=mid where correction_id=cor.id and round=cor.round;
   if mid is not null then update public.homework_attachments set status='active',finalized_at=coalesce(finalized_at,clock_timestamp()) where id=mid;end if;
   -- Old unsubmitted drafts have no history reference; submitted rounds remain retained.
   if rr.attachment_id is not null and not homework_private.media_referenced(rr.attachment_id) then perform homework_private.media_enqueue(rr.attachment_id,'superseded_draft');end if;
  end if;
 elsif p_action='submit' or (p_action='correction_decide' and p_data->>'decision'='approved') then
  if old_mid is not null then insert into public.homework_media_history(notice_id,attachment_id,revision) values(n.id,old_mid,n.revision) on conflict do nothing;end if;
  new_mid:=case when p_action='correction_decide' then case when rr.media_set then rr.attachment_id else old_mid end when supplied then mid else old_mid end;
  if new_mid is null then delete from public.homework_notice_media where notice_id=(out_data->>'id')::uuid;
  else
   insert into public.homework_notice_media(notice_id,attachment_id)values((out_data->>'id')::uuid,new_mid)on conflict(notice_id)do update set attachment_id=excluded.attachment_id;
   update public.homework_attachments set status='active',notice_id=(out_data->>'id')::uuid,finalized_at=coalesce(finalized_at,clock_timestamp())where id=new_mid;
  end if;
  out_data:=out_data||jsonb_build_object('attachment_id',new_mid);
 elsif p_action='correction_decide' and p_data->>'decision'='rejected' and cor.round=1 then
  update public.homework_correction_rounds set media_set=rr.media_set,attachment_id=rr.attachment_id where correction_id=cor.id and round=2;
 end if;
 if supplied then perform homework_private.audit(c,coalesce(n.id,(out_data->>'id')::uuid),a.id,'media_reference',jsonb_build_object('attachment_id',old_mid),jsonb_build_object('attachment_id',mid,'action',p_action));end if;
 if op is not null then insert into public.homework_media_receipts(owner_id,operation_id,notice_id,class_id,payload_hash,correction_id) values(a.id,op,coalesce(n.id,(out_data->>'id')::uuid),c,payload_hash,case when p_action in('correction_save','correction_submit') then cor.id end);end if;
 return out_data;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.api_v8(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 -- Removing a reaction deletes a row and releases space, so only adding one is
 -- withheld. Clearing an image (attachment_id present but null) is allowed for
 -- the same reason.
 if p_action='heart' and coalesce((p_data->>'liked')::boolean,false) then
  perform homework_private.storage_guard('reaction');
 elsif nullif(p_data->>'attachment_id','') is not null then
  perform homework_private.storage_guard('media');
 end if;
 return homework_private.api_v6(p_action,p_data);
end $function$;
CREATE OR REPLACE FUNCTION homework_private.apply_correction(n public.homework_notices, p jsonb, a uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare pending boolean;fresh public.homework_notices;begin
 pending:=n.status<>'published' or (p->>'subject_id')::uuid<>n.subject_id or nullif(p->>'english_group_id','')::uuid is distinct from n.english_group_id
  or abs(extract(epoch from ((p->>'due_at')::timestamptz-n.due_at)))>=86400
  or regexp_replace(trim(p->>'title'),'\s+',' ','g')<>regexp_replace(n.title,'\s+',' ','g')
  or regexp_replace(trim(p->>'content'),'\s+',' ','g')<>regexp_replace(n.content,'\s+',' ','g');
 update public.homework_notices set subject_id=(p->>'subject_id')::uuid,english_group_id=nullif(p->>'english_group_id','')::uuid,
 title=trim(p->>'title'),content=trim(p->>'content'),due_at=(p->>'due_at')::timestamptz,
 revision=revision+1,updated_at=clock_timestamp(),pending_since=case when pending then clock_timestamp() else pending_since end,
 status=case when pending then 'pending_duplicate_review' else status end,
 duplicate_of=case when pending then null else duplicate_of end,duplicate_tombstone_id=case when pending then null else duplicate_tombstone_id end
 where id=n.id returning * into fresh;
 -- The AI edit classifier uses submit events to recover the previous revision.
 perform homework_private.audit(n.class_id,n.id,a,'submit',to_jsonb(n),to_jsonb(fresh));
 return homework_private.card(fresh,a);
end $function$;
CREATE OR REPLACE FUNCTION homework_private.archive_admin()
 RETURNS public.profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.profiles;begin
 select * into a from public.profiles where id=auth.uid() and active and deleted_at is null;
 if a.id is null or a.role::text<>'admin' then raise exception 'Chỉ Admin dùng được kho lưu trữ' using errcode='42501';end if;
 return a;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.archive_blockers(p_year uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select coalesce(jsonb_agg(x),'[]'::jsonb) from (
  -- EC-714: an upload nobody finished is not year data; it must be cleaned up
  -- (FEAT-008 does that) rather than archived as if it were a published image.
  select jsonb_build_object('code','pending_media','detail',count(*)) x
   from public.homework_attachments where school_year_id=p_year and status='pending' having count(*)>0
  union all
  -- A row queued for purge is mid-flight: archiving it would capture an object
  -- that is about to disappear, and skipping it would silently lose data.
  select jsonb_build_object('code','deleting_media','detail',count(*))
   from public.homework_attachments where school_year_id=p_year and status='deleting' having count(*)>0
  union all
  -- EC-701 in advance: metadata with no usable object key.
  select jsonb_build_object('code','media_without_key','detail',count(*))
   from public.homework_attachments where school_year_id=p_year and status='active' and coalesce(trim(object_key),'')='' having count(*)>0
  union all
  select jsonb_build_object('code','open_correction','detail',count(*))
   from public.homework_corrections x join public.homework_notices n on n.id=x.notice_id
   where n.school_year_id=p_year and x.status in('awaiting_author','awaiting_teacher') having count(*)>0
  union all
  select jsonb_build_object('code','notice_pending_review','detail',count(*))
   from public.homework_notices where school_year_id=p_year and status='pending_duplicate_review' having count(*)>0
 ) s
$function$;
CREATE OR REPLACE FUNCTION homework_private.archive_counts(p_year uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 with cls as (select id from public.classes where school_year_id=p_year),
 nt as (select id from public.homework_notices where school_year_id=p_year)
 select jsonb_build_object(
  'classes',(select count(*) from cls),
  'profiles',(select count(*) from public.profiles where class_id in(select id from cls)),
  'class_subjects',(select count(*) from public.class_subjects where class_id in(select id from cls)),
  'english_groups',(select count(*) from public.english_groups where school_year_id=p_year),
  'english_group_members',(select count(*) from public.english_group_members where school_year_id=p_year),
  'notices',(select count(*) from nt),
  'reactions',(select count(*) from public.homework_notice_reactions where notice_id in(select id from nt)),
  'reminders',(select count(*) from public.homework_notice_reminders where notice_id in(select id from nt)),
  'reports',(select count(*) from public.homework_reports where notice_id in(select id from nt)),
  'corrections',(select count(*) from public.homework_corrections where notice_id in(select id from nt)),
  'correction_rounds',(select count(*) from public.homework_correction_rounds where correction_id in(select id from public.homework_corrections where notice_id in(select id from nt))),
  'duplicate_reviews',(select count(*) from public.homework_duplicate_reviews where notice_id in(select id from nt)),
  'tombstones',(select count(*) from public.homework_tombstones where class_id in(select id from cls)),
  'contribution_events',(select count(*) from public.homework_contribution_events where class_id in(select id from cls)),
  'moderation_events',(select count(*) from public.homework_moderation_events where class_id in(select id from cls)),
  'notifications',(select count(*) from public.homework_notifications where class_id in(select id from cls)),
  'media',(select count(*) from public.homework_attachments where school_year_id=p_year and status='active'))
$function$;
CREATE OR REPLACE FUNCTION homework_private.archive_fingerprint(p_year uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 with cls as (select id from public.classes where school_year_id=p_year),
 nt as (select id from public.homework_notices where school_year_id=p_year),
 rows_all as (
  select 'classes'||md5(t::text) h from public.classes t where school_year_id=p_year
  union all select 'profiles'||md5(row(t.id,t.full_name,t.role,t.active,t.class_id,t.deleted_at)::text) from public.profiles t where class_id in(select id from cls)
  union all select 'class_subjects'||md5(t::text) from public.class_subjects t where class_id in(select id from cls)
  union all select 'english_groups'||md5(t::text) from public.english_groups t where school_year_id=p_year
  union all select 'english_group_members'||md5(t::text) from public.english_group_members t where school_year_id=p_year
  union all select 'notices'||md5(t::text) from public.homework_notices t where school_year_id=p_year
  union all select 'reactions'||md5(t::text) from public.homework_notice_reactions t where notice_id in(select id from nt)
  union all select 'reminders'||md5(t::text) from public.homework_notice_reminders t where notice_id in(select id from nt)
  union all select 'reports'||md5(t::text) from public.homework_reports t where notice_id in(select id from nt)
  union all select 'corrections'||md5(t::text) from public.homework_corrections t where notice_id in(select id from nt)
  union all select 'rounds'||md5(t::text) from public.homework_correction_rounds t where correction_id in(select id from public.homework_corrections where notice_id in(select id from nt))
  union all select 'duplicate_reviews'||md5(t::text) from public.homework_duplicate_reviews t where notice_id in(select id from nt)
  union all select 'tombstones'||md5(t::text) from public.homework_tombstones t where class_id in(select id from cls)
  union all select 'contribution'||md5(t::text) from public.homework_contribution_events t where class_id in(select id from cls)
  union all select 'moderation'||md5(t::text) from public.homework_moderation_events t where class_id in(select id from cls)
  union all select 'notifications'||md5(t::text) from public.homework_notifications t where class_id in(select id from cls)
  union all select 'attachments'||md5(row(t.id,t.object_key,t.size_bytes,t.checksum,t.status,t.notice_id)::text) from public.homework_attachments t where school_year_id=p_year
  union all select 'notice_media'||md5(t::text) from public.homework_notice_media t where notice_id in(select id from nt)
  union all select 'media_history'||md5(t::text) from public.homework_media_history t where notice_id in(select id from nt)
 )
 select encode(sha256(convert_to(coalesce(string_agg(h,'|' order by h),''),'UTF8')),'hex') from rows_all
$function$;
CREATE OR REPLACE FUNCTION homework_private.archive_frozen(p_year uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare state text; token text;
begin
 if p_year is null then return false;end if;
 select archive_state into state from public.school_years where id=p_year;
 -- A row that cannot be attributed to a year is left alone: the guard protects
 -- frozen years, and refusing what it cannot place would break unrelated work.
 if state is null or state='active' then return false;end if;
 -- The purge's own writes. `purge_step` sets this for the duration of its
 -- transaction; it names an archive, and that archive must belong to this year
 -- and actually be purging, so the setting cannot be reused elsewhere.
 token:=coalesce(current_setting('homework.archive_purge',true),'');
 if token<>'' and exists(select 1 from public.homework_archives
   where id=token::uuid and school_year_id=p_year and status='purging') then return false;end if;
 return true;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.archive_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare years uuid[]; y uuid;
begin
 -- The end of the FEAT-006 media lifecycle, checked before anything else. The
 -- worker deletes an attachment row once R2 has confirmed the object is gone;
 -- that row is already marked for deletion and cannot introduce anything the
 -- archive does not have. Refusing it would strand attachment rows, and the
 -- bytes storage health counts, for ever. Read through the jsonb, not
 -- `old.status`: Postgres does not guarantee that the left side of AND
 -- short-circuits, so naming a column that only one table has fails on every
 -- other table this trigger is attached to.
 if tg_table_name='homework_attachments' and tg_op='DELETE' and to_jsonb(old)->>'status'='deleting' then return old;end if;

 -- Both sides of an update, and every owner on each side. Resolving only the
 -- new owner lets a frozen row be re-parented into an active year — it then
 -- escapes the purge entirely, and for an image that means bytes the year-end
 -- sweep never queues for deletion from R2. Resolving only *one* owner per side
 -- lets a row with an active class and a frozen notice walk in the other
 -- direction: past the freeze, and into a purge set it was never archived in.
 if tg_op<>'DELETE' then years:=homework_private.archive_guard_years(to_jsonb(new));end if;
 if tg_op<>'INSERT' then
  select coalesce(array_agg(distinct u),'{}'::uuid[]) into years
   from unnest(years||homework_private.archive_guard_years(to_jsonb(old))) u;
 end if;

 foreach y in array years loop
  if homework_private.archive_frozen(y) then
   raise exception 'Năm học đã đóng gói nên dữ liệu của năm đó không thay đổi được nữa (%.%).',tg_table_name,lower(tg_op)
    using errcode='42501';
  end if;
 end loop;
 return case when tg_op='DELETE' then old else new end;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.archive_guard_class()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if tg_op='DELETE' then
  if homework_private.archive_frozen(old.school_year_id) then
   raise exception 'Năm học đã đóng gói nên không xoá được lớp của năm đó.' using errcode='42501';
  end if;
  return old;
 end if;
 if new.school_year_id is distinct from old.school_year_id
  and (homework_private.archive_frozen(old.school_year_id) or homework_private.archive_frozen(new.school_year_id)) then
  raise exception 'Năm học đã đóng gói nên không chuyển lớp sang năm khác được.' using errcode='42501';
 end if;
 return new;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.archive_guard_years(p_row jsonb)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select coalesce(array_agg(distinct y),'{}'::uuid[]) from (
  select (p_row->>'school_year_id')::uuid
  union all select (select c.school_year_id from public.classes c where c.id=(p_row->>'class_id')::uuid)
  union all select (select n.school_year_id from public.homework_notices n where n.id=(p_row->>'notice_id')::uuid)
  union all select (select n.school_year_id from public.homework_notices n where n.id=(p_row->>'candidate_id')::uuid)
  union all select (select n.school_year_id from public.homework_notices n where n.id=(p_row->>'duplicate_of')::uuid)
  union all select (select m.school_year_id from public.homework_attachments m where m.id=(p_row->>'attachment_id')::uuid)
  union all select (select g.school_year_id from public.english_groups g where g.id=(p_row->>'english_group_id')::uuid)
  union all select (select n.school_year_id from public.homework_corrections c
    join public.homework_notices n on n.id=c.notice_id where c.id=(p_row->>'correction_id')::uuid)
  union all select (select n.school_year_id from public.homework_reports r
    join public.homework_notices n on n.id=r.notice_id where r.id=(p_row->>'report_id')::uuid)
 ) s(y) where y is not null
$function$;
CREATE OR REPLACE FUNCTION homework_private.archive_readonly(p_class uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select exists(select 1 from public.classes c join public.school_years y on y.id=c.school_year_id
  where c.id=p_class and y.archive_state<>'active')
$function$;
CREATE OR REPLACE FUNCTION homework_private.archive_release(p_year uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 -- 'purged' is in the list on purpose: a year whose data has been deleted must
 -- never drift back to writable because a later run was abandoned.
 if exists(select 1 from public.homework_archives where school_year_id=p_year and status in('building','verified','purging','purged')) then return;end if;
 update public.school_years set archive_state='active' where id=p_year and archive_state='archiving';
end $function$;
CREATE OR REPLACE FUNCTION homework_private.audit(c uuid, n uuid, a uuid, e text, b jsonb DEFAULT NULL::jsonb, v jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 insert into public.homework_contribution_events(class_id,notice_id,actor_id,event_type,before_data,after_data)values(c,n,a,e,b,v)
$function$;
CREATE OR REPLACE FUNCTION homework_private.backlog(c uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare qty int;
begin
  insert into public.homework_backlog_state(class_id)values(c)on conflict do nothing;
  perform 1 from public.homework_backlog_state where class_id=c for update;
  select count(*) into qty from public.homework_notices
  where class_id=c and homework_private.actionable(homework_notices)
    and pending_since<=now()-interval '24 hours';
  update public.homework_backlog_state set active=(qty>=5) where class_id=c;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.candidates(n public.homework_notices)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'content',x.content,'due_at',x.due_at,'revision',x.revision,'status',x.status,'published_at',x.published_at,'created_at',x.created_at)
 order by (x.published_at is null),x.published_at,x.created_at,x.id),'[]')from public.homework_notices x
 where x.id<>n.id and x.class_id=n.class_id and x.subject_id=n.subject_id and x.english_group_id is not distinct from n.english_group_id
 and x.status in('published','pending_duplicate_review') and abs(extract(epoch from(x.due_at-n.due_at)))<=86400
 -- A later unreviewed submission cannot suppress an earlier submission.
 and (x.published_at is not null or (x.created_at,x.id)<(n.created_at,n.id))
$function$;
CREATE OR REPLACE FUNCTION homework_private.card(n public.homework_notices, p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select homework_private.card_v5(n,p_user)||jsonb_build_object('attachment_id',(select attachment_id from public.homework_notice_media where notice_id=n.id))
$function$;
CREATE OR REPLACE FUNCTION homework_private.card_v4(n public.homework_notices, p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select jsonb_build_object('id',n.id,'class_id',n.class_id,'subject_id',n.subject_id,'english_group_id',n.english_group_id,
 'author_id',n.author_id,'author_name',p.full_name,'author_role',p.role,'title',n.title,'content',n.content,'due_at',n.due_at,
 'status',n.status,'created_at',n.created_at,'updated_at',n.updated_at,'published_at',n.published_at,'revision',n.revision,
 'subject',s.name,'icon',s.icon,'english_group',g.name,'duplicate_of',n.duplicate_of,'duplicate_tombstone_id',n.duplicate_tombstone_id,
 'hearts',(select count(*) from public.homework_notice_reactions r where r.notice_id=n.id),
 'liked',exists(select 1 from public.homework_notice_reactions r where r.notice_id=n.id and r.user_id=p_user),
 'can_retry',n.status='pending_duplicate_review' and not exists(select 1 from public.homework_duplicate_reviews rv where rv.notice_id=n.id and rv.revision=n.revision and (rv.score is not null or rv.decision is not null))
 and exists(select 1 from public.profiles actor where actor.id=p_user and (actor.id=n.author_id or (actor.role::text='teacher' and p.role::text in('student','monitor')))))
 from public.profiles p join public.class_subjects s on s.id=n.subject_id left join public.english_groups g on g.id=n.english_group_id where p.id=n.author_id
$function$;
CREATE OR REPLACE FUNCTION homework_private.card_v5(n public.homework_notices, p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select homework_private.card_v4(n,p_user)||jsonb_build_object(
 'deleted_actor_type',n.deleted_actor_type,'deleted_by',n.deleted_by,'deleted_at',n.deleted_at,'deleted_actor_name',case when n.deleted_actor_type='system' then 'System' else (select full_name from public.profiles where id=n.deleted_by) end,
 'correction', (select jsonb_build_object('id',c.id,'round',c.round,'status',c.status,'version',c.version,'due_at',r.due_at)
 from public.homework_corrections c join public.homework_correction_rounds r on r.correction_id=c.id and r.round=c.round
 where c.notice_id=n.id and c.status in('awaiting_author','awaiting_teacher')))
$function$;
CREATE OR REPLACE FUNCTION homework_private.class_subject_catalog_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare g public.grade_subject_catalog; cg smallint;begin
 select * into g from public.grade_subject_catalog where id=new.catalog_subject_id for share;
 select grade into cg from public.classes where id=new.class_id;
 if g.id is null or cg is distinct from g.grade then raise exception 'Môn không thuộc khối của lớp';end if;
 if tg_op='UPDATE' and (new.class_id is distinct from old.class_id or new.catalog_subject_id is distinct from old.catalog_subject_id) then raise exception 'Không đổi liên kết môn lớp';end if;
 if (tg_op='INSERT' or (new.is_active and not old.is_active)) and not g.is_active then raise exception 'Môn catalog đã ngừng hoạt động';end if;
 new.name:=g.name;new.short_name:=g.short_name;new.icon:=g.icon;new.is_english:=g.is_english;
 return new;end$function$;
CREATE OR REPLACE FUNCTION homework_private.correction_delete(n public.homework_notices, actor uuid, why text, outcome text, cor public.homework_corrections)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if n.status in('deleted','replaced') then raise exception 'Bài đã thay đổi'; end if;
 update public.homework_notices set previous_status=status,status='deleted',deleted_at=clock_timestamp(),deleted_by=actor,
  deleted_actor_type=case when actor is null then 'system' else 'user' end,delete_reason=why,revision=revision+1,updated_at=clock_timestamp() where id=n.id;
 if cor.id is not null then
  update public.homework_corrections set status=outcome,closed_at=clock_timestamp(),version=version+1 where id=cor.id;
 end if;
 perform homework_private.moderation_event(n.class_id,n.id,actor,outcome,why,cor.id,cor.round);
 perform homework_private.moderation_event(n.class_id,n.id,actor,case when actor is null then 'system_soft_delete' else 'user_soft_delete' end,why,cor.id,cor.round);
 perform homework_private.notify_author(n,outcome,why);
 perform homework_private.backlog(n.class_id);
end $function$;
CREATE OR REPLACE FUNCTION homework_private.deletion_attribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if new.status<>'deleted' then new.deleted_actor_type:=null;
 elsif new.deleted_by is not null then new.deleted_actor_type:='user'; end if;
 return new;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.expire_corrections(c uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare cor public.homework_corrections;n public.homework_notices;total integer:=0;begin
 perform pg_advisory_xact_lock(hashtextextended('homework:'||c::text,0));
 for cor in select x.* from public.homework_corrections x join public.homework_correction_rounds r on r.correction_id=x.id and r.round=x.round
 where x.class_id=c and x.status='awaiting_author' and r.due_at<=clock_timestamp() order by x.id for update of x loop
  select * into n from public.homework_notices where id=cor.notice_id for update;
  if n.status not in('deleted','replaced') then
   perform homework_private.correction_delete(n,null,'Không chỉnh sửa Báo bài trong 72 giờ sau yêu cầu của giáo viên.','timeout',cor);
   total:=total+1;
  end if;
 end loop;return total;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.hard_delete(c uuid, a public.profiles, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare n public.homework_notices; last_review public.homework_duplicate_reviews; target uuid:=(p->>'id')::uuid;
 reason_text text:=regexp_replace(coalesce(p->>'hard_delete_reason',''),'^[[:space:]]+|[[:space:]]+$','','g');
begin
 if a.role::text<>'admin' then raise exception 'Chỉ Admin được xóa vĩnh viễn' using errcode='42501';end if;
 if p->'confirm_irreversible' is distinct from 'true'::jsonb or jsonb_typeof(p->'hard_delete_reason') is distinct from 'string' or length(reason_text) not between 1 and 500 then raise exception 'Cần xác nhận không thể hoàn tác và lý do từ 1 đến 500 ký tự';end if;
 if exists(select 1 from jsonb_object_keys(p) k where k not in('class_id','id','confirm_irreversible','hard_delete_reason')) then raise exception 'Payload hard delete không hợp lệ';end if;
 -- Caller holds the common class transaction lock; re-read locked row after any restore.
 select * into n from public.homework_notices where id=target and class_id=c for update;
 if n.id is null then
 if exists(select 1 from public.homework_tombstones where notice_id=target and class_id=c)then return '{"ok":true,"already_deleted":true}';end if;
 raise exception 'Không tìm thấy bài';end if;
 if n.status<>'deleted' or n.deleted_at is null or not ((n.deleted_actor_type='user' and n.deleted_by is not null) or (n.deleted_actor_type='system' and n.deleted_by is null)) then raise exception 'Chỉ xóa vĩnh viễn bài đã soft-delete';end if;
 select * into last_review from (
 select rv.* from public.homework_duplicate_reviews rv where (rv.notice_id=n.id or rv.candidate_id=n.id) and rv.decision is not null
 union all
 select (jsonb_populate_record(null::public.homework_duplicate_reviews,ev.after_data)).* from public.homework_contribution_events ev
 where ev.notice_id=n.id and ev.event_type='duplicate_reference_redacted' and ev.after_data->>'decision' is not null
 ) decisions order by decided_at desc nulls last,id desc nulls last limit 1;
 -- This insert is a mandatory gate; any later error also rolls the entire transaction back.
 insert into public.homework_tombstones(notice_id,class_id,author_id,subject_id,english_group_id,original_created_at,original_published_at,final_status,soft_deleted_at,soft_deleted_by,soft_delete_actor_type,soft_delete_reason,hard_deleted_by,hard_delete_reason,was_duplicate,last_decision,decided_at,decided_by)
 values(n.id,c,n.author_id,n.subject_id,n.english_group_id,n.created_at,n.published_at,n.previous_status,n.deleted_at,n.deleted_by,n.deleted_actor_type,n.delete_reason,a.id,reason_text,
 n.duplicate_of is not null or n.duplicate_tombstone_id is not null or n.previous_status in('pending_duplicate_review','duplicate_rejected','replaced') or exists(select 1 from public.homework_duplicate_reviews where (notice_id=n.id and (candidate_id is not null or candidate_tombstone_id is not null or decision is not null)) or candidate_id=n.id) or exists(select 1 from public.homework_contribution_events where notice_id=n.id and event_type='duplicate_reference_redacted'),last_review.decision,last_review.decided_at,last_review.decided_by);
 -- Preserve other notice identities/decisions while irreversibly redacting comparison details.
 update public.homework_notices set duplicate_of=null,duplicate_tombstone_id=n.id where duplicate_of=n.id;
 update public.homework_duplicate_reviews set candidate_id=null,candidate_tombstone_id=n.id,score=null,reason=null,decision_reason=null where candidate_id=n.id and notice_id<>n.id;
 update public.homework_contribution_events set before_data=null,after_data=jsonb_build_object('redacted_notice_id',n.id)
 where notice_id is distinct from n.id and (position(n.id::text in coalesce(before_data::text,''))>0 or position(n.id::text in coalesce(after_data::text,''))>0);
 -- If the deleted notice owns a comparison, its surviving target still needs a
 -- minimal decision trace. No score, reason, content, deadline or prompt survives.
 insert into public.homework_contribution_events(class_id,notice_id,actor_id,event_type,after_data)
 select o.class_id,o.id,a.id,'duplicate_reference_redacted',jsonb_build_object('redacted_notice_id',n.id,'decision',rv.decision,'decided_at',rv.decided_at,'decided_by',rv.decided_by)
 from public.homework_duplicate_reviews rv join public.homework_notices o on o.id=rv.candidate_id where rv.notice_id=n.id and o.id<>n.id;
 delete from public.homework_notice_reactions where notice_id=n.id;
 delete from public.homework_notice_reminders where notice_id=n.id;
 delete from public.homework_notifications where notice_id=n.id;
 delete from public.homework_duplicate_reviews where notice_id=n.id;
 delete from public.homework_contribution_events where notice_id=n.id;
 delete from public.homework_notices where id=n.id;
 perform homework_private.backlog(c);
 return '{"ok":true}';
end$function$;
CREATE OR REPLACE FUNCTION homework_private.homework_maintenance_v4()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c uuid;begin
 for c in select id from public.classes where active loop
 perform pg_advisory_xact_lock(hashtextextended('homework:'||c::text,0));perform homework_private.backlog(c);
 end loop;
end$function$;
CREATE OR REPLACE FUNCTION homework_private.immutable_grade()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin if new.grade is distinct from old.grade then raise exception 'Đổi khối lớp cần flow riêng';end if;return new;end$function$;
CREATE OR REPLACE FUNCTION homework_private.immutable_tombstone()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin raise exception 'Hard-delete tombstone is immutable';end$function$;
CREATE OR REPLACE FUNCTION homework_private.media_after_attach()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if new.status='active' and old.status='pending' then
  insert into public.homework_media_outbox(attachment_id,kind,reason,safe_after,next_attempt_at)
  values(new.id,'staging','promoted_staging',greatest(clock_timestamp(),coalesce(new.grant_until,clock_timestamp()))+interval '3 minutes',greatest(clock_timestamp(),coalesce(new.grant_until,clock_timestamp()))+interval '3 minutes')
  on conflict do nothing;
 end if;return new;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.media_before_purge()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare m record;begin
 for m in select id from public.homework_attachments where notice_id=old.id loop
  perform homework_private.media_enqueue(m.id,'notice_hard_delete');
 end loop;
 return old;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.media_enqueue(target uuid, why text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare m public.homework_attachments;begin
 select * into m from public.homework_attachments where id=target for update;
 if m.id is null then return;end if;
 update public.homework_attachments set status='deleting' where id=target;
 insert into public.homework_media_outbox(attachment_id,reason,safe_after)
 values(target,why,greatest(clock_timestamp(),coalesce(m.grant_until,clock_timestamp()))+interval '3 minutes')
 on conflict(attachment_id) do update set kind='purge',reason=excluded.reason,token=gen_random_uuid(),next_attempt_at=clock_timestamp(),safe_after=greatest(homework_media_outbox.safe_after,excluded.safe_after);
end $function$;
CREATE OR REPLACE FUNCTION homework_private.media_referenced(target uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select exists(select 1 from public.homework_notice_media where attachment_id=target)
 or exists(select 1 from public.homework_media_history where attachment_id=target)
 or exists(select 1 from public.homework_correction_rounds where attachment_id=target)
$function$;
CREATE OR REPLACE FUNCTION homework_private.media_v6(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c uuid:=(p_data->>'class_id')::uuid; a public.profiles; m public.homework_attachments;
 n public.homework_notices;cor public.homework_corrections; target uuid:=nullif(p_data->>'notice_id','')::uuid;
 rid uuid:=nullif(p_data->>'request_id','')::uuid; mid uuid; until_time timestamptz;
begin
 a:=homework_private.actor(c);
 perform pg_advisory_xact_lock(hashtextextended('homework:'||c::text,0));
 if p_action='prepare' then
  if a.role::text not in('student','monitor','teacher') then raise exception 'Chỉ tác giả được tải ảnh' using errcode='42501';end if;
  if rid is null then raise exception 'Thiếu mã yêu cầu';end if;
  if target is not null then
   select * into n from public.homework_notices where id=target and class_id=c for update;
   if n.id is null or n.author_id<>a.id or n.status in('deleted','replaced') then raise exception 'Không có quyền thay ảnh' using errcode='42501';end if;
   select * into cor from public.homework_corrections where notice_id=target and status in('awaiting_author','awaiting_teacher');
   if cor.id is not null then
    if cor.status<>'awaiting_author' or cor.id is distinct from nullif(p_data->>'correction_id','')::uuid or cor.round is distinct from (p_data->>'round')::smallint or cor.version is distinct from (p_data->>'version')::int
     or exists(select 1 from public.homework_correction_rounds where correction_id=cor.id and round=cor.round and due_at<=clock_timestamp()) then raise exception 'Yêu cầu chỉnh sửa đã thay đổi';end if;
   elsif nullif(p_data->>'correction_id','') is not null or n.revision is distinct from (p_data->>'revision')::int then raise exception 'Bài đã thay đổi';end if;
  elsif nullif(p_data->>'correction_id','') is not null then raise exception 'Không có bản chỉnh sửa';end if;
  select * into m from public.homework_attachments where owner_id=a.id and upload_id=coalesce(nullif(p_data->>'upload_id','')::uuid,rid);
  if m.id is not null then
   if m.class_id<>c or m.notice_id is distinct from target or m.checksum is distinct from p_data->>'checksum' or m.size_bytes is distinct from (p_data->>'size_bytes')::int or m.width is distinct from (p_data->>'width')::int or m.height is distinct from (p_data->>'height')::int
    or m.correction_id is distinct from cor.id or m.status<>'pending' or m.expires_at<=clock_timestamp() then raise exception 'Yêu cầu tải ảnh đã thay đổi hoặc hết hạn';end if;
   return to_jsonb(m);
  end if;
  mid:=gen_random_uuid();
  insert into public.homework_attachments(id,owner_id,class_id,school_year_id,notice_id,request_id,upload_id,base_revision,correction_id,correction_round,object_key,staging_key,size_bytes,width,height,checksum)
  values(mid,a.id,c,(select school_year_id from public.classes where id=c),target,rid,coalesce(nullif(p_data->>'upload_id','')::uuid,rid),n.revision,cor.id,cor.round,
   'homework/'||c::text||'/'||mid::text||'/image.webp','pending/'||c::text||'/'||mid::text||'/upload.webp',
   (p_data->>'size_bytes')::int,(p_data->>'width')::int,(p_data->>'height')::int,p_data->>'checksum')returning * into m;
  return to_jsonb(m);
 end if;
 select * into m from public.homework_attachments where id=(p_data->>'attachment_id')::uuid and class_id=c for update;
 if m.id is null or m.status='deleting' then raise exception 'Không có ảnh khả dụng' using errcode='42501';end if;
 if p_action in('ticket','cancel') then
  if m.owner_id<>a.id or a.role::text='admin' or m.status<>'pending' then raise exception 'Chỉ tác giả dùng ảnh chờ' using errcode='42501';end if;
  if p_action='cancel' then perform homework_private.media_enqueue(m.id,'pending_canceled');return '{"ok":true,"cleanup":"queued"}';end if;
  if m.expires_at<=clock_timestamp() then raise exception 'Ảnh chờ đã hết hạn 24 giờ';end if;
  if m.notice_id is not null then
   select * into n from public.homework_notices where id=m.notice_id and author_id=a.id and class_id=c;
   if n.id is null or n.status in('deleted','replaced') then raise exception 'Bài không còn nhận ảnh';end if;
   if m.correction_id is not null then
    if not exists(select 1 from public.homework_corrections x join public.homework_correction_rounds r on r.correction_id=x.id and r.round=x.round where x.id=m.correction_id and x.notice_id=n.id and x.round=m.correction_round and x.status='awaiting_author' and r.due_at>clock_timestamp()) then raise exception 'Correction không còn nhận ảnh';end if;
   elsif n.revision<>m.base_revision or exists(select 1 from public.homework_corrections where notice_id=n.id and status in('awaiting_author','awaiting_teacher')) then raise exception 'Bài đã thay đổi';end if;
  end if;
  -- Covers short PUT/signing + bounded promotion work; cleanup sweeps again after this grant.
  until_time:=least(m.expires_at,clock_timestamp()+interval '5 minutes');
  update public.homework_attachments set grant_until=until_time where id=m.id returning * into m;
  return to_jsonb(m);
 elsif p_action='read' then
  if m.status='pending' then
   if a.id<>m.owner_id or m.verified_at is null or m.expires_at<=clock_timestamp() then raise exception 'Ảnh chờ riêng tư' using errcode='42501';end if;
  else
   select * into n from public.homework_notices where id=m.notice_id and class_id=c;
   if n.id is null then raise exception 'Ảnh đã gỡ' using errcode='42501';end if;
   if exists(select 1 from public.homework_notice_media where notice_id=n.id and attachment_id=m.id) then
    -- FEAT-006 P1: peer image access requires active English membership for
    -- Student AND Monitor; the legacy visible() helper exempts Monitor.
    if not (n.author_id=a.id or a.role::text in('teacher','admin') or (n.status='published' and (
     n.english_group_id is null or exists(
      select 1 from public.english_group_members membership
      where membership.english_group_id=n.english_group_id
       and membership.student_id=a.id and membership.left_at is null
     )
    ))) then raise exception 'Ngoài phạm vi bài' using errcode='42501';end if;
   elsif exists(select 1 from public.homework_media_history where notice_id=n.id and attachment_id=m.id) then
    if not(n.author_id=a.id or a.role::text in('teacher','admin')) then raise exception 'Lịch sử ảnh riêng tư' using errcode='42501';end if;
   elsif exists(select 1 from public.homework_correction_rounds r join public.homework_corrections x on x.id=r.correction_id where x.notice_id=n.id and r.attachment_id=m.id) then
    if not(n.author_id=a.id or a.role::text='teacher') then raise exception 'Ảnh chỉnh sửa riêng tư' using errcode='42501';end if;
   else raise exception 'Ảnh không còn tham chiếu' using errcode='42501';end if;
  end if;
  return jsonb_build_object('id',m.id,'object_key',m.object_key,'width',m.width,'height',m.height);
 end if;
 raise exception 'Thao tác ảnh không hợp lệ';
end $function$;
CREATE OR REPLACE FUNCTION homework_private.media_v8(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 -- Only new uploads are withheld. 'ticket', 'seal', 'read' and 'cancel' keep
 -- working so an upload already in flight can finish or be cleaned up instead
 -- of being stranded as a pending row nobody can resolve.
 if p_action='prepare' then perform homework_private.storage_guard('media');end if;
 return homework_private.media_v6(p_action,p_data);
end $function$;
CREATE OR REPLACE FUNCTION homework_private.moderation_event(c uuid, n uuid, a uuid, e text, reason_text text DEFAULT NULL::text, cor uuid DEFAULT NULL::uuid, rnd smallint DEFAULT NULL::smallint, rep uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 insert into public.homework_moderation_events(class_id,notice_id,actor_id,actor_type,event_type,reason,correction_id,round,report_id)
 values(c,n,a,case when a is null then 'system' else 'user' end,e,reason_text,cor,rnd,rep)
$function$;
CREATE OR REPLACE FUNCTION homework_private.notification_visible(hn public.homework_notifications, a public.profiles)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select a.role::text<>'admin' and (
    case when hn.kind like 'correction_%' then hn.recipient_id=a.id and exists(
      select 1 from public.homework_notices n where n.id=hn.notice_id and n.class_id=hn.class_id and n.author_id=a.id)
    else homework_private.notification_visible_v4(hn,a) end
  )
$function$;
CREATE OR REPLACE FUNCTION homework_private.notification_visible_v4(hn public.homework_notifications, a public.profiles)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select (hn.notice_id is null or exists(select 1 from public.homework_notices n where n.id=hn.notice_id and homework_private.visible(n,a)
 and (n.status='published' or a.role::text in('teacher','admin'))
 and (hn.kind not in('pending','pending_duplicate_review') or homework_private.actionable(n))))
 and (hn.kind<>'backlog' or exists(select 1 from public.homework_backlog_state b where b.class_id=hn.class_id and b.active))
$function$;
CREATE OR REPLACE FUNCTION homework_private.notify_author(n public.homework_notices, k text, msg text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 insert into public.homework_notifications(class_id,recipient_id,notice_id,kind,title,message)
 values(n.class_id,n.author_id,n.id,'correction_'||k,'Báo bài — cập nhật từ giáo viên/hệ thống',msg)
$function$;
CREATE OR REPLACE FUNCTION homework_private.notify_managers(c uuid, n uuid, k text, msg text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if k='system' then return; end if;
  insert into public.homework_notifications(class_id,recipient_id,notice_id,kind,title,message)
  select c,p.id,n,k,'Báo bài',msg
  from public.profiles p join public.class_teachers ct on ct.teacher_id=p.id
  where ct.class_id=c and ct.active and p.active and p.deleted_at is null and p.role::text='teacher';
end $function$;
CREATE OR REPLACE FUNCTION homework_private.queue_card(n public.homework_notices)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select jsonb_build_object('id',n.id,'subject',s.name,'english_group',g.name,
 'title',n.title,'content',n.content,'due_at',n.due_at,'author_name',p.full_name,
 'author_role',p.role,'created_at',n.created_at,'status',n.status)
 from public.profiles p join public.class_subjects s on s.id=n.subject_id
 left join public.english_groups g on g.id=n.english_group_id where p.id=n.author_id
$function$;
CREATE OR REPLACE FUNCTION homework_private.skip_admin_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if exists(select 1 from public.profiles p where p.id=new.recipient_id and p.role::text='admin') then
    return null;
  end if;
  return new;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.storage_admin()
 RETURNS public.profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.profiles;begin
 select * into a from public.profiles where id=auth.uid() and active and deleted_at is null;
 if a.id is null or a.role::text<>'admin' then raise exception 'Chỉ Admin xem được dung lượng hệ thống' using errcode='42501';end if;
 return a;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.storage_guard(p_kind text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare f jsonb:=homework_private.storage_state()->'flags';begin
 if coalesce((f->>'protection_mode')::boolean,false) then
  raise exception 'Hệ thống đang ở chế độ bảo vệ dung lượng. Bài dạng chữ, chỉnh sửa và báo cáo vẫn hoạt động.' using errcode='53100';
 end if;
 if p_kind='media' and coalesce((f->>'r2_upload_locked')::boolean,false) then
  raise exception 'Kho ảnh đã gần đầy nên tạm khóa ảnh mới. Bạn vẫn đăng được bài dạng chữ.' using errcode='53100';
 end if;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.storage_measure()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 insert into public.homework_storage_usage(provider,metadata_bytes,measured_at)
 values('database',pg_database_size(current_database()),clock_timestamp())
 on conflict(provider) do update set metadata_bytes=excluded.metadata_bytes,measured_at=excluded.measured_at;
 -- 'deleting' rows are queued for purge but their objects are still in the
 -- bucket: media_enqueue only writes an outbox job, with safe_after minutes in
 -- the future, and the row disappears only when the worker confirms removal.
 -- Excluding them made queuing a cleanup look like space had already been
 -- freed, which is how a queued cleanup could unlock uploads while R2 was still
 -- full. They are counted as used and reported separately so Admin can see how
 -- much is on its way out.
 insert into public.homework_storage_usage(provider,metadata_bytes,active_bytes,pending_bytes,deleting_bytes,media_count,measured_at)
 select 'r2',coalesce(sum(size_bytes),0),
  coalesce(sum(size_bytes) filter(where status='active'),0),
  coalesce(sum(size_bytes) filter(where status='pending'),0),
  coalesce(sum(size_bytes) filter(where status='deleting'),0),
  count(*) filter(where status in('active','pending')),clock_timestamp()
 from public.homework_attachments
 on conflict(provider) do update set metadata_bytes=excluded.metadata_bytes,active_bytes=excluded.active_bytes,
  pending_bytes=excluded.pending_bytes,deleting_bytes=excluded.deleting_bytes,
  media_count=excluded.media_count,measured_at=excluded.measured_at;
end $function$;
CREATE OR REPLACE FUNCTION homework_private.storage_state()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 with p as (
  select c.provider,c.configured_bytes,c.note,
   u.metadata_bytes,u.active_bytes,u.pending_bytes,u.deleting_bytes,u.media_count,
   u.provider_bytes,u.provider_measured_at,u.measured_at,
   u.provider is not null measured,
   -- A provider reading is authoritative only while it is recent. Preferring any
   -- non-null provider_bytes forever meant one old R2 answer kept driving the
   -- percentage: a later in-database measurement showing 97% could not raise the
   -- lock, and an old 97% could not be lowered by a cleanup. Six hours is well
   -- inside any sane refresh cadence, and outside it the reading simply stops
   -- counting rather than being trusted or deleted.
   case when u.provider_measured_at>clock_timestamp()-interval '6 hours' then u.provider_bytes end fresh_provider
  from public.homework_storage_capacity c left join public.homework_storage_usage u on u.provider=c.provider
 ), e as (
  -- metadata_bytes is the application's own accounting and always counts: it
  -- includes pending uploads the provider has not seen yet, so a provider figure
  -- that predates them must not pull the total back down. greatest() ignores
  -- NULL, so a stale or absent provider reading leaves metadata alone.
  select p.*, greatest(fresh_provider,metadata_bytes) total_bytes,
   provider_bytes is not null and fresh_provider is null provider_stale,
   case when not measured then 'none'
    when fresh_provider is not null and fresh_provider>=coalesce(metadata_bytes,0) then 'provider'
    else 'metadata' end source
  from p
 ), q as (
  select e.*,
   case when configured_bytes is null or total_bytes is null then null
    else round(total_bytes::numeric*100/configured_bytes,2) end percent,
   -- A snapshot nobody refreshed is not evidence of health; it is reported as
   -- stale so Admin can see the measurement stopped, but it is never escalated
   -- into protection by itself.
   measured_at is null or measured_at<clock_timestamp()-interval '24 hours' stale
  from e
 ), l as (
  select q.*, case
   when configured_bytes is null then 'unconfigured'
   when percent is null then 'unknown'
   when percent>=95 then 'critical' when percent>=85 then 'warning'
   when percent>=70 then 'info' else 'normal' end level
  from q
 )
 select jsonb_build_object(
  'providers',(select jsonb_object_agg(provider,to_jsonb(l)-'provider') from l),
  'flags',jsonb_build_object(
   'protection_mode',(select coalesce(bool_or(level='critical'),false) from l where provider='database'),
   'r2_upload_locked',(select coalesce(bool_or(level='critical'),false) from l where provider='r2')),
  'measured_at',(select max(measured_at) from l))
$function$;
CREATE OR REPLACE FUNCTION homework_private.validate_revision(n public.homework_notices, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.class_subjects;g uuid:=nullif(p->>'english_group_id','')::uuid;author public.profiles;begin
 if jsonb_typeof(p) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p) k where k not in('subject_id','english_group_id','title','content','due_at')) then raise exception 'Revision không hợp lệ';end if;
 if p->>'title' is null or p->>'content' is null or length(trim(p->>'title')) not between 1 and 200 or length(trim(p->>'content')) not between 1 and 6000
  or p->>'due_at' is null or not isfinite((p->>'due_at')::timestamptz) then raise exception 'Nội dung/hạn không hợp lệ';end if;
 select * into s from public.class_subjects where id=(p->>'subject_id')::uuid and class_id=n.class_id and is_active;
 if s.id is null then raise exception 'Môn không hoạt động';end if;
 select * into author from public.profiles where id=n.author_id;
 if s.is_english then
  if not exists(select 1 from public.english_groups where id=g and class_id=n.class_id and school_year_id=n.school_year_id and is_active) then raise exception 'Nhóm Tiếng Anh không hợp lệ';end if;
  if author.role::text='student' and not exists(select 1 from public.english_group_members where student_id=author.id and english_group_id=g and left_at is null) then raise exception 'Ngoài nhóm Tiếng Anh' using errcode='42501';end if;
 elsif g is not null then raise exception 'Môn này không dùng nhóm Tiếng Anh';end if;
 return jsonb_build_object('subject_id',s.id,'english_group_id',g,'title',trim(p->>'title'),'content',trim(p->>'content'),'due_at',(p->>'due_at')::timestamptz);
end $function$;
CREATE OR REPLACE FUNCTION homework_private.visible(n public.homework_notices, a public.profiles)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select a.role::text in('admin','teacher','monitor') or n.english_group_id is null or exists(
 select 1 from public.english_group_members m where m.english_group_id=n.english_group_id and m.student_id=a.id and m.left_at is null)
$function$;
CREATE OR REPLACE FUNCTION public.admin_assign_timetable_version(p_actor_id uuid, p_class_id uuid, p_school_year_id uuid, p_template_version_id uuid, p_effective_from date, p_effective_to date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.class_timetable_assignments%rowtype;v_id uuid;v_template_year uuid;v_class_year uuid;v_year_start date;v_year_end date;
begin
  if p_effective_from is null or p_effective_to is null or p_effective_from>p_effective_to then raise exception 'Khoảng hiệu lực TKB không hợp lệ.';end if;
  select school_year_id into v_class_year from public.classes where id=p_class_id;
  select start_date,end_date into v_year_start,v_year_end from public.school_years where id=p_school_year_id;
  select t.school_year_id into v_template_year from public.timetable_template_versions v join public.timetable_templates t on t.id=v.template_id where v.id=p_template_version_id;
  if v_class_year is null or v_class_year<>p_school_year_id then raise exception 'Lớp không thuộc năm học đã chọn.';end if;
  if v_year_start is null or v_year_end is null then raise exception 'Không tìm thấy năm học đã chọn.';end if;
  if p_effective_from<v_year_start or p_effective_to>v_year_end then raise exception 'Khoảng hiệu lực TKB phải nằm trong năm học đã chọn.';end if;
  if v_template_year is null or v_template_year<>p_school_year_id then raise exception 'Mẫu TKB không thuộc năm học của lớp.';end if;
  for r in select * from public.class_timetable_assignments where class_id=p_class_id and active and daterange(effective_from,effective_to,'[]')&&daterange(p_effective_from,p_effective_to,'[]') for update loop
    if r.effective_from<p_effective_from and r.effective_to>p_effective_to then
      update public.class_timetable_assignments set effective_to=p_effective_from-1,updated_at=now() where id=r.id;
      insert into public.class_timetable_assignments(class_id,school_year_id,template_version_id,effective_from,effective_to,active,created_by,created_at,updated_at)
      values(r.class_id,r.school_year_id,r.template_version_id,p_effective_to+1,r.effective_to,true,p_actor_id,now(),now());
    elsif r.effective_from<p_effective_from then
      update public.class_timetable_assignments set effective_to=p_effective_from-1,updated_at=now() where id=r.id;
    elsif r.effective_to>p_effective_to then
      update public.class_timetable_assignments set effective_from=p_effective_to+1,updated_at=now() where id=r.id;
    else
      update public.class_timetable_assignments set active=false,updated_at=now() where id=r.id;
    end if;
  end loop;
  insert into public.class_timetable_assignments(class_id,school_year_id,template_version_id,effective_from,effective_to,active,created_by,created_at,updated_at)
  values(p_class_id,p_school_year_id,p_template_version_id,p_effective_from,p_effective_to,true,p_actor_id,now(),now()) returning id into v_id;
  return v_id;
end$function$;
CREATE OR REPLACE FUNCTION public.admin_create_school_year(p_actor_id uuid, p_name text, p_start_date date, p_end_date date, p_set_active boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor_role text;
  v_actor_active boolean;
  v_name text:=btrim(coalesce(p_name,''));
  v_year_id uuid;
  v_today date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
  select role::text,active into v_actor_role,v_actor_active
  from public.profiles where id=p_actor_id;
  if v_actor_role is distinct from 'admin' or v_actor_active is distinct from true then
    raise exception 'ROOT_ADMIN_REQUIRED' using errcode='42501';
  end if;
  if length(v_name)<4 or length(v_name)>40 then raise exception 'SCHOOL_YEAR_NAME_INVALID' using errcode='22023'; end if;
  if p_start_date is null or p_end_date is null or p_end_date<p_start_date then raise exception 'SCHOOL_YEAR_DATES_INVALID' using errcode='22023'; end if;
  if exists(select 1 from public.school_years where lower(name)=lower(v_name)) then raise exception 'SCHOOL_YEAR_ALREADY_EXISTS' using errcode='23505'; end if;

  insert into public.school_years(name,start_date,end_date,is_active)
  values(v_name,p_start_date,p_end_date,false) returning id into v_year_id;

  insert into public.school_year_periods(school_year_id,period_number,start_time,end_time)
  select v_year_id,p.period_number,p.start_time,p.end_time from public.periods p
  on conflict (school_year_id,period_number) do nothing;

  insert into public.weeks(school_year_id,week_number,start_date,end_date,status,deadline_mode,registration_deadline,note)
  select v_year_id,g.i+1,p_start_date+(g.i*7),least(p_start_date+(g.i*7)+4,p_end_date),
    case when p_start_date+(g.i*7)+6<v_today then 'locked'::public.week_status
         when v_today between p_start_date+(g.i*7) and p_start_date+(g.i*7)+6 then 'open'::public.week_status
         else 'upcoming'::public.week_status end,
    'per_session_20',null,null
  from generate_series(0,greatest(0,floor((p_end_date-p_start_date)/7.0)::int)) as g(i)
  where p_start_date+(g.i*7)<=p_end_date;

  if coalesce(p_set_active,false) then perform public.admin_set_active_school_year(p_actor_id,v_year_id); end if;
  return v_year_id;
end;
$function$;
CREATE OR REPLACE FUNCTION public.admin_list_deleted_registrations(p_limit integer DEFAULT 200)
 RETURNS TABLE(id uuid, class_id uuid, student_id uuid, student_code text, student_name text, week_number integer, weekday integer, period_number integer, content text, status text, deleted_at timestamp with time zone, deleted_by uuid, deleted_by_name text, can_restore boolean, blocked_reason text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    r.id,
    r.class_id,
    r.student_id,
    s.student_code::text,
    coalesce(s.full_name,'Học sinh')::text,
    w.week_number,
    r.weekday,
    r.period_number,
    r.content,
    r.status::text,
    r.deleted_at,
    r.deleted_by,
    coalesce(d.full_name, 'Không rõ')::text,
    not exists(
      select 1 from public.registrations a
      where a.student_id=r.student_id and a.week_id=r.week_id
        and a.weekday=r.weekday and a.period_number=r.period_number
        and a.is_deleted=false
    ) as can_restore,
    case when exists(
      select 1 from public.registrations a
      where a.student_id=r.student_id and a.week_id=r.week_id
        and a.weekday=r.weekday and a.period_number=r.period_number
        and a.is_deleted=false
    ) then 'Học sinh đã có đăng ký khác đang hoạt động ở đúng tiết này.'
    else null end
  from public.registrations r
  left join public.profiles s on s.id=r.student_id
  left join public.profiles d on d.id=r.deleted_by
  left join public.weeks w on w.id=r.week_id
  where public.is_root_admin()
    and r.is_deleted=true
  order by r.deleted_at desc nulls last, r.updated_at desc
  limit greatest(1, least(coalesce(p_limit,200), 500))
$function$;
CREATE OR REPLACE FUNCTION public.admin_list_deleted_users(p_limit integer DEFAULT 200)
 RETURNS TABLE(id uuid, student_code text, full_name text, role text, class_id uuid, class_code text, deleted_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    p.id,
    p.student_code::text,
    coalesce(p.full_name,'Không tên')::text,
    p.role::text,
    p.class_id,
    c.code::text,
    p.deleted_at
  from public.profiles p
  left join public.classes c on c.id=p.class_id
  where public.is_root_admin()
    and p.deleted_at is not null
  order by p.deleted_at desc
  limit greatest(1, least(coalesce(p_limit,200), 500))
$function$;
CREATE OR REPLACE FUNCTION public.admin_replace_school_year_periods(p_actor_id uuid, p_school_year_id uuid, p_periods jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor_role text;
  v_actor_active boolean;
  v_total integer;
  v_distinct integer;
  v_overlap boolean;
begin
  select role::text,active into v_actor_role,v_actor_active
  from public.profiles where id=p_actor_id;
  if v_actor_role is distinct from 'admin' or v_actor_active is distinct from true then
    raise exception 'ROOT_ADMIN_REQUIRED' using errcode='42501';
  end if;
  if not exists(select 1 from public.school_years where id=p_school_year_id) then
    raise exception 'SCHOOL_YEAR_NOT_FOUND' using errcode='22023';
  end if;
  if p_periods is null or jsonb_typeof(p_periods)<>'array' or jsonb_array_length(p_periods)=0 or jsonb_array_length(p_periods)>20 then
    raise exception 'PERIODS_INVALID' using errcode='22023';
  end if;

  with parsed as (
    select
      (x->>'number')::integer as period_number,
      (x->>'start')::time as start_time,
      (x->>'end')::time as end_time
    from jsonb_array_elements(p_periods) x
  )
  select count(*),count(distinct period_number)
  into v_total,v_distinct
  from parsed
  where period_number between 1 and 20 and start_time<end_time;

  if v_total<>jsonb_array_length(p_periods) or v_distinct<>v_total then
    raise exception 'PERIODS_INVALID' using errcode='22023';
  end if;

  with parsed as (
    select
      (x->>'number')::integer as period_number,
      (x->>'start')::time as start_time,
      (x->>'end')::time as end_time
    from jsonb_array_elements(p_periods) x
  ), ordered as (
    select *,lag(end_time) over(order by start_time,period_number) as previous_end
    from parsed
  )
  select exists(select 1 from ordered where previous_end is not null and start_time<previous_end)
  into v_overlap;
  if v_overlap then
    raise exception 'PERIODS_OVERLAP' using errcode='22023';
  end if;

  delete from public.school_year_periods where school_year_id=p_school_year_id;
  insert into public.school_year_periods(school_year_id,period_number,start_time,end_time,updated_at)
  select p_school_year_id,(x->>'number')::integer,(x->>'start')::time,(x->>'end')::time,now()
  from jsonb_array_elements(p_periods) x;
end;
$function$;
CREATE OR REPLACE FUNCTION public.admin_restore_registration(p_registration_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_registration public.registrations%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode='42501';
  end if;

  if not public.is_root_admin() then
    raise exception 'Chỉ Admin mới khôi phục được dữ liệu đã xoá.' using errcode='42501';
  end if;

  select * into v_registration
  from public.registrations
  where id=p_registration_id
  for update;

  if not found then
    raise exception 'Không tìm thấy đăng ký.' using errcode='P0002';
  end if;

  if coalesce(v_registration.is_deleted,false)=false then
    raise exception 'Đăng ký này chưa bị xoá.' using errcode='22023';
  end if;

  -- Chặn trước va chạm với uq_registrations_active_student_slot để lỗi đọc được.
  if exists(
    select 1 from public.registrations a
    where a.student_id=v_registration.student_id
      and a.week_id=v_registration.week_id
      and a.weekday=v_registration.weekday
      and a.period_number=v_registration.period_number
      and a.is_deleted=false
  ) then
    raise exception 'Học sinh đã có đăng ký khác đang hoạt động ở đúng tiết này; hãy xử lý đăng ký đó trước.'
      using errcode='23505';
  end if;

  update public.registrations
  set is_deleted=false,
      deleted_at=null,
      deleted_by=null,
      updated_at=now()
  where id=v_registration.id;

  return true;
end;
$function$;
CREATE OR REPLACE FUNCTION public.admin_restore_user(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_profile public.profiles%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode='42501';
  end if;

  if not public.is_root_admin() then
    raise exception 'Chỉ Admin mới khôi phục được dữ liệu đã xoá.' using errcode='42501';
  end if;

  select * into v_profile from public.profiles where id=p_user_id for update;

  if not found then
    raise exception 'Không tìm thấy tài khoản.' using errcode='P0002';
  end if;

  if v_profile.deleted_at is null then
    raise exception 'Tài khoản này chưa bị xoá.' using errcode='22023';
  end if;

  -- Xoá mềm đặt active=false + deleted_at; khôi phục trả lại đúng cặp đó.
  update public.profiles
  set deleted_at=null,
      active=true
  where id=v_profile.id;

  return true;
end;
$function$;
CREATE OR REPLACE FUNCTION public.admin_set_active_school_year(p_actor_id uuid, p_school_year_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor_role text;
  v_actor_active boolean;
begin
  select role::text,active into v_actor_role,v_actor_active
  from public.profiles where id=p_actor_id;
  if v_actor_role is distinct from 'admin' or v_actor_active is distinct from true then
    raise exception 'ROOT_ADMIN_REQUIRED' using errcode='42501';
  end if;
  if not exists(select 1 from public.school_years where id=p_school_year_id) then
    raise exception 'SCHOOL_YEAR_NOT_FOUND' using errcode='22023';
  end if;

  update public.school_years set is_active=false where is_active=true and id<>p_school_year_id;
  update public.school_years set is_active=true where id=p_school_year_id;
end;
$function$;
CREATE OR REPLACE FUNCTION public.ai_automation_is_enabled(p_class_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select ai_automation_enabled from public.class_settings where class_id=p_class_id),false)
$function$;
CREATE OR REPLACE FUNCTION public.apply_device_use_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- BR-010-018 / AC-010-020. Đọc policy rồi ghi kết quả là hai việc, và giữa
  -- chúng một giao dịch khác có thể commit một khoảng khoá mới. Nếu để mặc,
  -- cái thua cuộc là học sinh: đăng ký của em ấy đã đọc "chưa khoá", còn hàm
  -- tính lại của Teacher thì chưa nhìn thấy dòng đăng ký chưa commit — không
  -- bên nào sai, nhưng kết quả là device=true lọt qua một buổi đang khoá.
  --
  -- Khoá tư vấn theo từng slot khép vòng đó lại: mọi lần ghi đăng ký giữ khoá
  -- chia sẻ (nên các đăng ký đồng thời không chặn nhau), còn mọi lần đổi policy
  -- ở mục 6 giữ khoá độc quyền. Vì thế hai thao tác buộc phải xếp hàng, và dù
  -- thứ tự nào thì bên chạy sau cũng nhìn thấy kết quả đã commit của bên chạy
  -- trước. Khoá hết hiệu lực khi giao dịch kết thúc.
  perform pg_advisory_xact_lock_shared(
    public.device_use_slot_key(new.class_id,new.weekday,new.period_number));

  new.effective_uses_electronic_device := public.device_use_effective(
    new.uses_electronic_device, new.class_id, new.week_id, new.weekday, new.period_number);
  return new;
end $function$;
CREATE OR REPLACE FUNCTION public.apply_smart_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enabled boolean:=public.ai_automation_is_enabled(new.class_id);
  v_should_review boolean:=false;
  v_force boolean:=coalesce(current_setting('app.force_ai_rereview',true),'')='on';
begin
  if v_force and (public.is_root_admin() or public.teacher_has_class(new.class_id)) then
    new.status:='submitted'; new.approval_source:='manual'; new.ai_review_status:=case when v_enabled then 'pending' else 'not_needed' end;
    new.ai_decision:=null; new.ai_category:=null; new.ai_confidence:=null; new.ai_revision_status:=null; new.ai_revision_confidence:=null;
    new.ai_reason:=null; new.ai_model:=null; new.ai_reviewed_at:=null; new.approved_at:=null; new.approved_by:=null;
    new.auto_review_reason:=case when v_enabled then 'GV/Admin chủ động yêu cầu AI duyệt lại.' else 'AI đang tắt; chuyển giáo viên duyệt.' end;
    return new;
  end if;

  if tg_op='UPDATE' and new.status='needs_revision' and old.status is distinct from 'needs_revision'
     and (public.is_root_admin() or public.teacher_has_class(new.class_id)) then
    new.revision_overdue_at:=null; new.approval_source:='manual'; new.ai_review_status:='not_needed';
    new.ai_decision:=null; new.ai_category:=null; new.ai_confidence:=null; new.ai_revision_status:=null; new.ai_revision_confidence:=null;
    new.ai_reason:=null; new.ai_model:=null; new.ai_reviewed_at:=null; new.approved_at:=null; new.approved_by:=null;
  end if;

  if auth.uid()=new.student_id and new.status='approved' then
    new.status:='submitted'; new.approval_source:='manual'; new.approved_at:=null; new.approved_by:=null;
  end if;

  -- HS sửa một đăng ký đã duyệt: bản ghi phải quay về đúng trạng thái của một
  -- đăng ký mới, nên xoá luôn phản hồi cũ của giáo viên (phản hồi đó gắn với
  -- nội dung vừa bị thay). Nhờ vậy auto_review_reason bên dưới cũng rơi vào
  -- nhánh "đăng ký mới" thay vì "HS đã sửa theo phản hồi GV".
  -- ai_review_count cố ý KHÔNG reset: đó là hạn mức chống gọi AI lặp, không
  -- phải trạng thái duyệt.
  if tg_op='UPDATE' and old.status='approved' and auth.uid()=new.student_id then
    new.teacher_comment:=null;
  end if;

  if new.status='submitted' then
    if tg_op='INSERT' or old.status is distinct from 'submitted' or old.content is distinct from new.content
       or old.note is distinct from new.note or old.uses_electronic_device is distinct from new.uses_electronic_device then
      v_should_review:=true;
    end if;
  end if;

  if v_should_review then
    new.approval_source:='manual'; new.ai_decision:=null; new.ai_category:=null; new.ai_confidence:=null;
    new.ai_revision_status:=null; new.ai_revision_confidence:=null; new.ai_reason:=null; new.ai_model:=null; new.ai_reviewed_at:=null;
    new.approved_at:=null; new.approved_by:=null;
    if v_enabled then
      new.ai_review_status:='pending';
      new.auto_review_reason:=case when coalesce(new.teacher_comment,'')<>'' then 'HS đã sửa theo phản hồi GV; Groq AI duyệt lại.'
        when coalesce(new.is_emergency,false) then 'Đăng ký bổ sung; Groq AI kiểm tra trước.' else 'Groq AI kiểm tra đăng ký mới.' end;
    else
      new.ai_review_status:='not_needed'; new.auto_review_reason:='AI đang tắt; chuyển giáo viên duyệt.';
    end if;
  elsif new.status='approved' and auth.uid() is distinct from new.student_id and new.approval_source<>'ai' then
    new.approval_source:='manual';
  end if;
  return new;
end; $function$;
CREATE OR REPLACE FUNCTION public.bag_auth_attempt(p_email text, p_code text, p_input_hex text, p_ip text, p_catalog smallint, p_catalog_size integer, p_account_max integer, p_account_window integer, p_account_lock integer, p_ip_max integer, p_ip_window integer, p_ip_lock integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ip_scope text := 'ip:' || coalesce(nullif(p_ip, ''), 'unknown');
  v_user uuid;
  v_scope text;
  v_input bytea := auth_bag.decode_input(p_input_hex);
  v_row record;
  v_match boolean := false;
  v_reason text;
begin
  -- Always IP first, then account: one lock order, so parallel attempts cannot deadlock.
  if not auth_bag.reserve(v_ip_scope, p_ip_max, p_ip_window, p_ip_lock) then
    return jsonb_build_object('ok', false);
  end if;

  select id into v_user from auth.users where lower(email) = lower(p_email) and deleted_at is null limit 1;
  v_scope := 'account:' || coalesce(v_user::text, 'code:' || lower(coalesce(p_code, '')));
  if not auth_bag.reserve(v_scope, p_account_max, p_account_window, p_account_lock) then
    perform auth_bag.refund(v_ip_scope);
    return jsonb_build_object('ok', false);
  end if;

  select verifier, credential_version into v_row
    from auth_bag.credentials where user_id = v_user and enabled and catalog_version = p_catalog;

  if v_row.verifier is not null and v_input is not null and auth_bag.valid_input(v_input, p_catalog, p_catalog_size) then
    v_match := extensions.crypt(encode(v_input, 'hex'), v_row.verifier) = v_row.verifier;
  else
    -- Same cost as a real check.
    perform extensions.crypt(coalesce(p_input_hex, ''), '$2a$10$abcdefghijklmnopqrstuu5XdWm0nD6i1DxNGUwwvQw2n8cq2O0Wm');
  end if;

  v_reason := case
    when v_user is null or not v_match then 'mismatch'
    when not auth_bag.eligible(v_user) then 'ineligible'
  end;

  if v_reason is not null then
    perform auth_bag.lock_if_reached(v_scope, p_account_max, p_account_lock);
    perform auth_bag.lock_if_reached(v_ip_scope, p_ip_max, p_ip_lock);
    insert into auth_bag.audit (event, user_id, reason) values ('login', v_user, v_reason);
    return jsonb_build_object('ok', false);
  end if;

  -- Success clears the account counter (never an active lock) and hands the IP slot back.
  delete from auth_bag.attempts where scope = v_scope and (locked_until is null or locked_until <= now());
  perform auth_bag.refund(v_ip_scope);
  insert into auth_bag.audit (event, user_id, reason) values ('login', v_user, 'ok');
  return jsonb_build_object('ok', true, 'user_id', v_user, 'credential_version', v_row.credential_version);
end $function$;
CREATE OR REPLACE FUNCTION public.bag_auth_disable(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update auth_bag.credentials
     set enabled = false, credential_version = credential_version + 1, updated_at = now()
   where user_id = p_user;
  insert into auth_bag.audit (event, user_id, reason) values ('disable', p_user, 'ok');
end $function$;
CREATE OR REPLACE FUNCTION public.bag_auth_enroll(p_user uuid, p_input_hex text, p_catalog smallint, p_catalog_size integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_input bytea := auth_bag.decode_input(p_input_hex);
  v_version integer;
begin
  if v_input is null or not auth_bag.valid_input(v_input, p_catalog, p_catalog_size) then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  if not auth_bag.eligible(p_user) then
    raise exception 'not_eligible' using errcode = '42501';
  end if;
  insert into auth_bag.credentials as c (user_id, catalog_version, verifier)
  values (p_user, p_catalog, extensions.crypt(encode(v_input, 'hex'), extensions.gen_salt('bf', 10)))
  on conflict (user_id) do update
    set catalog_version = excluded.catalog_version,
        verifier = excluded.verifier,
        credential_version = c.credential_version + 1,
        enabled = true,
        updated_at = now()
  returning credential_version into v_version;
  insert into auth_bag.audit (event, user_id, reason) values ('enroll', p_user, 'ok');
  return v_version;
end $function$;
CREATE OR REPLACE FUNCTION public.bag_auth_status(p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object('enabled', coalesce(bool_or(enabled), false), 'updated_at', max(updated_at))
    from auth_bag.credentials where user_id = p_user
$function$;
CREATE OR REPLACE FUNCTION public.bag_auth_still_valid(p_user uuid, p_version integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from auth_bag.credentials where user_id = p_user and enabled and credential_version = p_version)
     and auth_bag.eligible(p_user)
$function$;
CREATE OR REPLACE FUNCTION public.bag_game(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  me public.profiles;
  v_season int;
  v_year public.school_years;
  v_ticket bag_game.tickets;
  v_score int;
  v_class_name text;
  v_board jsonb;
  v_scope text;
  v_want_season int;
  v_rejected boolean := false;
begin
  select * into me from public.profiles
   where id = auth.uid() and active and deleted_at is null and role::text in ('student', 'monitor');
  if me.id is null then
    raise exception 'Chỉ học sinh đang học mới chơi được.' using errcode = '42501';
  end if;
  select season into v_season from bag_game.config;
  select * into v_year from public.school_years where is_active order by start_date desc nulls last limit 1;

  if p_action = 'start' then
    if coalesce((p_data->>'rules')::int, 0) <> v_season then
      raise exception 'Trò chơi vừa được cập nhật. Hãy tải lại trang.' using errcode = '22023';
    end if;
    delete from bag_game.tickets where started_at < clock_timestamp() - interval '1 day';
    if (select count(*) from bag_game.tickets
         where profile_id = me.id and started_at > clock_timestamp() - interval '1 hour') >= 60 then
      raise exception 'Bạn chơi nhiều quá rồi, nghỉ một chút nhé!' using errcode = '53400';
    end if;
    insert into bag_game.tickets (profile_id, season) values (me.id, v_season) returning * into v_ticket;
    return jsonb_build_object('ticket', v_ticket.id);

  elsif p_action = 'submit' then
    v_score := (p_data->>'score')::int;
    if v_score is null or v_score < 0 or v_score > 1000 then
      raise exception 'Điểm không hợp lệ.' using errcode = '22023';
    end if;
    delete from bag_game.tickets
     where id = (p_data->>'ticket')::uuid and profile_id = me.id
     returning * into v_ticket;
    v_rejected := v_ticket.id is null or v_ticket.season <> v_season
       or v_ticket.started_at < clock_timestamp() - interval '3 hours'
       or v_score * bag_game.min_seconds_per_round() > extract(epoch from clock_timestamp() - v_ticket.started_at);
    if not v_rejected and v_score > 0 and v_year.id is not null and v_year.archive_state = 'active' then
      select coalesce(nullif(c.code, ''), c.name, me.class_name, '') into v_class_name
        from (select 1) one left join public.classes c on c.id = me.class_id;
      insert into bag_game.scores as s (profile_id, season, school_year_id, class_id, class_name, score)
      values (me.id, v_season, v_year.id, me.class_id, coalesce(v_class_name, ''), v_score)
      on conflict (profile_id, season, school_year_id) do update
        set score = excluded.score, class_id = excluded.class_id, class_name = excluded.class_name,
            achieved_at = excluded.achieved_at
        where excluded.score > s.score;
    end if;
    p_action := 'board';

  elsif p_action = 'set_visibility' then
    insert into bag_game.prefs (profile_id, show_on_board) values (me.id, coalesce((p_data->>'show')::boolean, false))
    on conflict (profile_id) do update set show_on_board = excluded.show_on_board;
    p_action := 'board';
  end if;

  if p_action <> 'board' then
    raise exception 'Unknown action' using errcode = '22023';
  end if;

  v_scope := coalesce(p_data->>'scope', 'year');
  v_want_season := coalesce((p_data->>'season')::int, v_season);

  if v_scope = 'year' then
    select coalesce(jsonb_agg(r order by (r->>'score')::int desc, r->>'at'), '[]'::jsonb) into v_board from (
      select jsonb_build_object('name', p.full_name, 'class', s.class_name, 'score', s.score,
                                'at', s.achieved_at, 'me', p.id = me.id) r
        from bag_game.scores s
        join public.profiles p on p.id = s.profile_id
        join bag_game.prefs f on f.profile_id = s.profile_id and f.show_on_board
       where s.season = v_season and s.school_year_id = v_year.id
         and me.class_id is not null and s.class_id = me.class_id
         and p.active and p.deleted_at is null
       order by s.score desc, s.achieved_at
       limit 10) q;
  elsif v_scope = 'all' then
    select coalesce(jsonb_agg(r order by (r->>'score')::int desc, r->>'at'), '[]'::jsonb) into v_board from (
      select jsonb_build_object(
               'name', case when current_learner then p.full_name else bag_game.short_name(p.full_name) end,
               'class', case when current_learner then coalesce(nullif(c.code, ''), c.name, p.class_name, b.class_name) else b.class_name end,
               'year', case when current_learner then null else y.name end,
               'left', not current_learner,
               'score', b.score, 'at', b.achieved_at, 'me', p.id = me.id) r
        from (select distinct on (s.profile_id) s.*
                from bag_game.scores s
               where s.season = v_want_season
               order by s.profile_id, s.score desc, s.achieved_at) b
        join public.profiles p on p.id = b.profile_id
        join bag_game.prefs f on f.profile_id = b.profile_id and f.show_on_board
        join public.school_years y on y.id = b.school_year_id
        left join public.classes c on c.id = p.class_id
        cross join lateral (select p.active and p.deleted_at is null as current_learner) cl
       order by b.score desc, b.achieved_at
       limit 10) q;
  else
    raise exception 'Unknown scope' using errcode = '22023';
  end if;

  return jsonb_build_object(
    'board', v_board,
    'rejected', v_rejected,
    'scope', v_scope,
    'season', v_want_season,
    'current_season', v_season,
    'seasons', (select coalesce(jsonb_agg(distinct season order by season), '[]'::jsonb) from bag_game.scores),
    'year_name', v_year.name,
    'my_year_best', (select score from bag_game.scores
                      where profile_id = me.id and season = v_season and school_year_id = v_year.id),
    'my_all_best', (select max(score) from bag_game.scores where profile_id = me.id and season = v_season),
    'show_on_board', coalesce((select show_on_board from bag_game.prefs where profile_id = me.id), false)
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.bootstrap_root_admin(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists(select 1 from public.profiles where role='admin') then raise exception 'ROOT_ADMIN_ALREADY_EXISTS'; end if;
  if not exists(select 1 from public.profiles where id=p_user_id and role='teacher' and active=true) then raise exception 'ROOT_ADMIN_TARGET_MUST_BE_ACTIVE_TEACHER'; end if;
  update public.profiles set role='admin',class_id=null,active=true,deleted_at=null where id=p_user_id;
  update public.class_teachers set active=false,updated_at=now() where teacher_id=p_user_id and active=true;
  insert into public.audit_logs(actor_id,action,entity_type,entity_id,new_data,source,created_at)
  values(p_user_id,'BOOTSTRAP_ROOT_ADMIN','profile',p_user_id,jsonb_build_object('role','admin'),'system',now());
end; $function$;
