 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  insert into public.device_use_policy_signals(class_id,version,changed_at)
  values(p_class_id,1,now())
  on conflict (class_id) do update
    set version = public.device_use_policy_signals.version + 1, changed_at = now()
$function$;
CREATE OR REPLACE FUNCTION public.device_use_effective(p_requested boolean, p_class_id uuid, p_week_id uuid, p_weekday integer, p_period_number integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
