     and public.device_use_policy_state(p_class_id,p_week_id,p_weekday,p_period_number) <> 'locked'
$function$;
CREATE OR REPLACE FUNCTION public.device_use_guard_override_week()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists(
    select 1 from public.classes c
      join public.weeks w on w.id = new.week_id
     where c.id = new.class_id and c.school_year_id = w.school_year_id) then
    raise exception 'DEVICE_POLICY_OVERRIDE_WEEK_MISMATCH'
      using hint='Tuần này không thuộc năm học của lớp.';
  end if;
  return new;
end $function$;
CREATE OR REPLACE FUNCTION public.device_use_guard_year_freeze()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE' then
    perform public.device_use_assert_year_writable(old.class_id);
    return old;
  end if;
  perform public.device_use_assert_year_writable(new.class_id);
  if tg_op = 'UPDATE' and old.class_id is distinct from new.class_id then
    perform public.device_use_assert_year_writable(old.class_id);
  end if;
  return new;
end $function$;
CREATE OR REPLACE FUNCTION public.device_use_live_override(p_interval_id uuid, p_week_id uuid, p_weekday integer, p_period_number integer, p_session_start timestamp with time zone)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select o.id from public.device_use_session_overrides o
   where o.interval_id = p_interval_id and o.week_id = p_week_id
     and o.weekday = p_weekday and o.period_number = p_period_number
     and o.mode = 'allow'
     and p_session_start > o.created_at
     and (o.revoked_at is null or p_session_start <= o.revoked_at)
$function$;
CREATE OR REPLACE FUNCTION public.device_use_locking_interval(p_class_id uuid, p_week_id uuid, p_weekday integer, p_period_number integer, p_session_start timestamp with time zone)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select i.id from public.device_use_lock_intervals i
   where i.class_id=p_class_id and i.weekday=p_weekday and i.period_number=p_period_number
     and p_session_start > i.locked_at
     and (i.unlocked_at is null or p_session_start <= i.unlocked_at)
   order by i.locked_at desc limit 1
$function$;
CREATE OR REPLACE FUNCTION public.device_use_policy(p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_class uuid := nullif(p_payload->>'class_id','')::uuid;
  v_week  uuid := nullif(p_payload->>'week_id','')::uuid;
  v_wd    integer := nullif(p_payload->>'weekday','')::integer;
  v_pn    integer := nullif(p_payload->>'period_number','')::integer;
  v_now   timestamptz := now();
  v_start timestamptz;
  v_row   public.device_use_lock_intervals%rowtype;
  v_manager boolean;
  v_recurring text;
  v_ovr   public.device_use_session_overrides%rowtype;
  v_moved integer;
  v_interval uuid;
begin
  if v_class is null then
    raise exception 'DEVICE_POLICY_CLASS_REQUIRED' using errcode='22023';
  end if;

  v_manager := public.can_manage_class(v_class);

  -- Sol RC1 §8. `state` và `history` không cùng một quyền. `state` là thứ học
  -- sinh cần để biết vì sao ô chọn bị khoá; `history` mang `locked_by`,
  -- `unlocked_by`, `created_by`, `revoked_by` — ai bấm nút, lúc nào — và học
  -- sinh không có việc gì với thông tin đó.
  if p_action = 'state' then
    -- `coalesce` ở đây không phải cho đẹp. Với một giáo viên không phụ trách lớp
    -- này, `current_student_class_id()` trả NULL, nên phép so sánh trả NULL, nên
    -- cả biểu thức trả NULL, nên `if not (NULL)` không vào nhánh nào và hàm chạy
    -- tiếp như thể đã được phép. Kiểm tra quyền mà kết quả là NULL thì phải coi
    -- là từ chối.
    if not coalesce(v_manager or v_class = public.current_student_class_id(), false) then
      raise exception 'DEVICE_POLICY_FORBIDDEN' using errcode='42501';
    end if;
  elsif p_action = 'history' then
    if not v_manager then
      raise exception 'DEVICE_POLICY_FORBIDDEN' using errcode='42501';
    end if;
  else
    -- Ghi: chỉ giáo viên được phân công. Admin cố tình không được (DEC-109).
    if not public.teacher_has_class(v_class) then
      raise exception 'DEVICE_POLICY_FORBIDDEN' using errcode='42501';
    end if;
    -- Sol RC4 R-003 / FEAT-007 RB-711. Chốt chặn đứng ở đây, trước khoá tư vấn
    -- và trước mọi câu ghi, nên một thao tác bị từ chối không để lại gì: không
    -- khoảng khoá, không ngoại lệ, không tín hiệu, không dòng audit, không đăng
    -- ký nào bị tính lại. Chỉ chặn **ghi** — `state` và `history` ở hai nhánh
    -- trên vẫn đọc được bình thường sau khi năm học đã đóng gói.
    --
    -- Trigger ở mục 5b cũng gọi đúng hàm này, nên câu dưới đây **không** thừa:
    -- nó bắt cả những nhánh không ghi gì. `lock` một slot đang khoá và `unlock`
    -- một slot đang mở trả về sớm mà không chạm bảng nào (EC-010-001/002); nếu
    -- chỉ có trigger thì hai lệnh đó sẽ *thành công* trong một năm đã đóng
    -- băng, và "bị từ chối" sẽ trở thành "im lặng báo không có gì đổi".
    perform public.device_use_assert_year_writable(v_class);
  end if;

  if p_action = 'state' then
    if v_week is null then
      raise exception 'DEVICE_POLICY_WEEK_REQUIRED' using errcode='22023';
    end if;
    -- Sol RC1 §10. `state` trả lời "buổi của tuần đang xem thì sao", còn nút
    -- Khóa/Mở hỏi "slot này **bây giờ** có đang khoá không". Với một tuần cũ
    -- nằm trong khoảng khoá đã đóng, câu trả lời thứ nhất là `locked` còn câu
    -- thứ hai là `open` — nếu trang chỉ có một trong hai thì giáo viên sẽ thấy
    -- nút "Mở từ bây giờ" cho một slot chẳng có gì để mở. Trả cả hai.
    -- Sol RC7 R-008. `override_id` **phải** là ngoại lệ của đúng khoảng khoá
    -- đang chi phối buổi này, không phải "ngoại lệ nào đó của lớp+tuần+ô còn
    -- chưa hủy". Hai dòng như vậy là hợp lệ (RC1 P1: mỗi chu kỳ khoá giữ ngoại
    -- lệ của mình), nên câu hỏi sai không chỉ trả lời sai mà còn làm cả RPC
    -- `state` gãy với "more than one row returned by a subquery".
    --
    -- Giờ bắt đầu và khoảng khoá được giải **một lần** ở hai lateral dưới đây
    -- rồi dùng lại, thay vì gọi lại resolver ở từng khoá JSON.
    return coalesce((
      select jsonb_agg(
        case when v_manager then jsonb_build_object(
               'weekday',s.weekday,'period_number',s.period_number,
               'state',public.device_use_policy_state(v_class,v_week,s.weekday,s.period_number),
               'session_start',t.ss,
               'current_recurring_state',case when exists(
                   select 1 from public.device_use_lock_intervals i
                    where i.class_id=v_class and i.weekday=s.weekday
                      and i.period_number=s.period_number and i.unlocked_at is null)
                 then 'locked' else 'open' end,
               'locked_at',(select i.locked_at from public.device_use_lock_intervals i
                             where i.class_id=v_class and i.weekday=s.weekday and i.period_number=s.period_number
                               and i.unlocked_at is null),
               'override_id',public.device_use_live_override(u.iv,v_week,s.weekday,s.period_number,t.ss))
        -- Học sinh chỉ nhận đúng thứ cần để hiển thị: buổi nào, trạng thái gì,
        -- bắt đầu lúc mấy giờ. Không có ai-bấm-nút, không có id nội bộ.
        else jsonb_build_object(
               'weekday',s.weekday,'period_number',s.period_number,
               'state',public.device_use_policy_state(v_class,v_week,s.weekday,s.period_number),
               'session_start',t.ss)
        end order by s.weekday,s.period_number)
      from public.device_use_week_slots(v_class,v_week) s
      cross join lateral (select public.study_session_start(v_class,v_week,s.weekday,s.period_number) as ss) t
      cross join lateral (select public.device_use_locking_interval(
                            v_class,v_week,s.weekday,s.period_number,t.ss) as iv) u
    ), '[]'::jsonb);
  end if;

  if p_action = 'history' then
    return jsonb_build_object(
      'intervals', coalesce((select jsonb_agg(to_jsonb(i) order by i.locked_at desc)
                              from public.device_use_lock_intervals i where i.class_id=v_class),'[]'::jsonb),
      'overrides', coalesce((select jsonb_agg(to_jsonb(o) order by o.created_at desc)
                              from public.device_use_session_overrides o where o.class_id=v_class),'[]'::jsonb));
  end if;

  if v_wd is null or v_pn is null then
    raise exception 'DEVICE_POLICY_SLOT_REQUIRED' using errcode='22023';
  end if;

  -- Nửa còn lại của khoá tư vấn ở mục 4: độc quyền, nên nó đợi mọi lần ghi
  -- đăng ký đang dở của đúng slot này commit xong rồi mới đọc để tính lại.
  perform pg_advisory_xact_lock(public.device_use_slot_key(v_class,v_wd,v_pn));

  if p_action = 'lock' then
    -- EC-010-001: khoá một slot đang khoá thì trả về trạng thái hiện tại, không
    -- tạo khoảng chồng. Ràng buộc unique ở mục 1 là lưới an toàn thứ hai.
    select * into v_row from public.device_use_lock_intervals
     where class_id=v_class and weekday=v_wd and period_number=v_pn and unlocked_at is null;
    if found then
      return jsonb_build_object('action','lock','changed',false,'interval_id',v_row.id,
                                'locked_at',v_row.locked_at,'registrations_updated',0);
    end if;
    insert into public.device_use_lock_intervals(class_id,weekday,period_number,locked_at,locked_by)
      values(v_class,v_wd,v_pn,v_now,auth.uid()) returning * into v_row;
    v_moved := public.device_use_recompute(v_class,v_wd,v_pn);
    perform public.device_use_bump_signal(v_class);
    insert into public.audit_logs(actor_id,class_id,action,entity_type,entity_id,new_data,source)
      values(auth.uid(),v_class,'device_use_lock','device_use_lock_intervals',v_row.id::text,
             jsonb_build_object('weekday',v_wd,'period_number',v_pn,'locked_at',v_row.locked_at,
                                'registrations_updated',v_moved),'server');
    return jsonb_build_object('action','lock','changed',true,'interval_id',v_row.id,
                              'locked_at',v_row.locked_at,'registrations_updated',v_moved);
  end if;

  if p_action = 'unlock' then
    -- EC-010-002: mở một slot đang mở là no-op. Không tạo khoảng giả để "ghi
    -- nhận" thao tác — một khoảng có locked_at = unlocked_at sẽ là một lời nói
    -- dối trong lịch sử.
    select * into v_row from public.device_use_lock_intervals
     where class_id=v_class and weekday=v_wd and period_number=v_pn and unlocked_at is null;
    if not found then
      return jsonb_build_object('action','unlock','changed',false,'registrations_updated',0);
    end if;
    update public.device_use_lock_intervals
       set unlocked_at=v_now, unlocked_by=auth.uid(), updated_at=v_now
     where id=v_row.id returning * into v_row;
    v_moved := public.device_use_recompute(v_class,v_wd,v_pn);
    perform public.device_use_bump_signal(v_class);
    insert into public.audit_logs(actor_id,class_id,action,entity_type,entity_id,new_data,source)
      values(auth.uid(),v_class,'device_use_unlock','device_use_lock_intervals',v_row.id::text,
             jsonb_build_object('weekday',v_wd,'period_number',v_pn,'locked_at',v_row.locked_at,
                                'unlocked_at',v_row.unlocked_at,'registrations_updated',v_moved),'server');
    return jsonb_build_object('action','unlock','changed',true,'interval_id',v_row.id,
                              'unlocked_at',v_row.unlocked_at,'registrations_updated',v_moved);
  end if;

  if p_action in ('allow_session','revoke_allow') then
    if v_week is null then
      raise exception 'DEVICE_POLICY_WEEK_REQUIRED' using errcode='22023';
    end if;
    -- Sol RC1 P1. Một override là ngoại lệ của một khoảng khoá, nên phải có
    -- khoảng khoá đang khoá đúng buổi này thì mới có gì để làm ngoại lệ. Tìm nó
    -- ở đây, trước cả kiểm tra giờ, và dùng chính nó làm chủ sở hữu của
    -- override — frontend ẩn nút là chuyện của frontend, §13 đòi cưỡng chế ở
    -- backend.
    v_start := public.study_session_start(v_class,v_week,v_wd,v_pn);
    if v_start is null then
      raise exception 'DEVICE_POLICY_SESSION_TIME_UNRESOLVED' using errcode='P0001';
    end if;
    v_interval := public.device_use_locking_interval(v_class,v_week,v_wd,v_pn,v_start);
    if v_interval is null then
      raise exception 'DEVICE_POLICY_SESSION_NOT_LOCKED' using errcode='42501',
        hint='Buổi này không nằm trong khoảng khoá nào nên không có gì để mở riêng.';
    end if;
    -- BR-010-006 / BR-010-007 / DEC-113: chỉ thao tác được với buổi chưa bắt đầu.
    if v_start <= v_now then
      raise exception 'DEVICE_POLICY_SESSION_ALREADY_STARTED' using errcode='42501';
    end if;
  end if;

  if p_action = 'allow_session' then
    select * into v_ovr from public.device_use_session_overrides
     where interval_id=v_interval and week_id=v_week and weekday=v_wd and period_number=v_pn and revoked_at is null;
    if found then
      return jsonb_build_object('action','allow_session','changed',false,'override_id',v_ovr.id,
                                'registrations_updated',0);
    end if;
    insert into public.device_use_session_overrides(interval_id,class_id,week_id,weekday,period_number,mode,created_by)
      values(v_interval,v_class,v_week,v_wd,v_pn,'allow',auth.uid()) returning * into v_ovr;
    v_moved := public.device_use_recompute(v_class,v_wd,v_pn);
    perform public.device_use_bump_signal(v_class);
    insert into public.audit_logs(actor_id,class_id,action,entity_type,entity_id,new_data,source)
      values(auth.uid(),v_class,'device_use_allow_session','device_use_session_overrides',v_ovr.id::text,
             jsonb_build_object('week_id',v_week,'weekday',v_wd,'period_number',v_pn,
                                'created_at',v_ovr.created_at,'registrations_updated',v_moved),'server');
    return jsonb_build_object('action','allow_session','changed',true,'override_id',v_ovr.id,
                              'registrations_updated',v_moved);
  end if;

  if p_action = 'revoke_allow' then
    select * into v_ovr from public.device_use_session_overrides
     where interval_id=v_interval and week_id=v_week and weekday=v_wd and period_number=v_pn and revoked_at is null;
    if not found then
      return jsonb_build_object('action','revoke_allow','changed',false,'registrations_updated',0);
    end if;
    update public.device_use_session_overrides
       set revoked_at=v_now, revoked_by=auth.uid()
     where id=v_ovr.id returning * into v_ovr;
    v_moved := public.device_use_recompute(v_class,v_wd,v_pn);
    perform public.device_use_bump_signal(v_class);
    insert into public.audit_logs(actor_id,class_id,action,entity_type,entity_id,new_data,source)
      values(auth.uid(),v_class,'device_use_revoke_allow','device_use_session_overrides',v_ovr.id::text,
             jsonb_build_object('week_id',v_week,'weekday',v_wd,'period_number',v_pn,
                                'revoked_at',v_ovr.revoked_at,'registrations_updated',v_moved),'server');
    return jsonb_build_object('action','revoke_allow','changed',true,'override_id',v_ovr.id,
                              'registrations_updated',v_moved);
  end if;

  raise exception 'DEVICE_POLICY_UNKNOWN_ACTION: %', p_action using errcode='22023';
end $function$;
CREATE OR REPLACE FUNCTION public.device_use_policy_state(p_class_id uuid, p_week_id uuid, p_weekday integer, p_period_number integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_start timestamptz; v_interval uuid;
begin
  -- Đường nhanh, và cũng là lý do FEAT-010 không làm chậm một lớp chưa bao giờ
  -- khoá gì: nếu slot không có khoảng khoá nào thì câu trả lời là 'open' bất
  -- kể mọi thứ khác, nên không cần giải thời gian bắt đầu buổi.
  if not exists(
    select 1 from public.device_use_lock_intervals i
    where i.class_id=p_class_id and i.weekday=p_weekday and i.period_number=p_period_number
  ) then return 'open'; end if;

  v_start := public.study_session_start(p_class_id,p_week_id,p_weekday,p_period_number);

  -- EC-010-010 / DEC-110. Có policy nhưng không biết buổi bắt đầu lúc nào thì
  -- không được đoán về phía nào cả. Chỉ raise ở đây, tức là chỉ khi biên thực
  -- sự cần thiết — một lớp không có policy vẫn ghi đăng ký bình thường dù thời
  -- khoá biểu có thiếu.
  if v_start is null then
    raise exception 'DEVICE_POLICY_SESSION_TIME_UNRESOLVED'
      using errcode='P0001',
            hint='Không xác định được giờ bắt đầu của buổi học nên không thể áp dụng chính sách thiết bị.';
  end if;

  v_interval := public.device_use_locking_interval(p_class_id,p_week_id,p_weekday,p_period_number,v_start);
  if v_interval is null then return 'open'; end if;

  -- Luật đối xứng với khoảng khoá — ngoại lệ có hiệu lực với buổi bắt đầu
  -- **sau** khi nó được tạo và thôi có hiệu lực với buổi bắt đầu **sau** khi nó
  -- bị hủy — nằm ở `device_use_live_override()` phía trên, và **chỉ** ở đó.
  -- Nhờ vậy DEC-113 (không hồi tố) là một tính chất của công thức, không phải
  -- một điều RPC phải nhớ từ chối; RPC vẫn từ chối, ở mục 6, nhưng hai lớp bảo
  -- vệ độc lập nhau.
  return case
    when public.device_use_live_override(v_interval,p_week_id,p_weekday,p_period_number,v_start) is not null
    then 'allow_override' else 'locked' end;
end $function$;
CREATE OR REPLACE FUNCTION public.device_use_recompute(p_class_id uuid, p_weekday integer, p_period_number integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_count integer;
begin
  with target as (
    select r.id, public.device_use_effective(r.uses_electronic_device,r.class_id,r.week_id,r.weekday,r.period_number) as eff
    from public.registrations r
    where r.class_id=p_class_id and r.weekday=p_weekday and r.period_number=p_period_number
  ), changed as (
    update public.registrations r
       set effective_uses_electronic_device = t.eff
      from target t
     where r.id=t.id and r.effective_uses_electronic_device is distinct from t.eff
    returning 1
  ) select count(*)::integer into v_count from changed;
  return v_count;
end $function$;
CREATE OR REPLACE FUNCTION public.device_use_slot_key(p_class_id uuid, p_weekday integer, p_period_number integer)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select pg_catalog.hashtextextended(
    p_class_id::text || ':' || p_weekday::text || ':' || p_period_number::text,
    0
  )
$function$;
CREATE OR REPLACE FUNCTION public.device_use_week_slots(p_class_id uuid, p_week_id uuid)
 RETURNS TABLE(weekday integer, period_number integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select distinct s.weekday, s.period_number from (
    select o.weekday, o.period_number
      from public.week_schedule_overrides o
     where o.class_id=p_class_id and o.week_id=p_week_id and o.is_study_period=true
    union all
    select sc.weekday, sc.period_number
      from public.study_schedule sc
     where sc.class_id=p_class_id and sc.is_study_period=true
       and not exists(select 1 from public.week_schedule_overrides ox
                       where ox.class_id=p_class_id and ox.week_id=p_week_id)
  ) s
$function$;
CREATE OR REPLACE FUNCTION public.device_use_year_freeze_guard_rc9()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- R-009: a DELETE on a FEAT-010 child row may itself be caused by
  -- classes(id) ON DELETE CASCADE. In that specific shape the parent class row
  -- is already unavailable to this child trigger. FEAT-004/FEAT-007 own the
  -- parent-class lifecycle decision, so the child trigger must not re-resolve
  -- the disappearing parent merely to decide the cascade.
  --
  -- A direct child DELETE still sees its parent and therefore continues through
  -- device_use_assert_year_writable(OLD.class_id), preserving the hard freeze.
  if tg_op = 'DELETE' then
    if not exists (
      select 1
      from public.classes c
      where c.id = old.class_id
    ) then
      return old;
    end if;

    perform public.device_use_assert_year_writable(old.class_id);
    return old;
  end if;

  -- INSERT and UPDATE always validate the NEW owner.
  perform public.device_use_assert_year_writable(new.class_id);

  -- R-010 regression guard: RC6/RC7 deliberately validated both ownership
  -- sides when class_id changes. Without this OLD-side check, a privileged
  -- UPDATE could move a row out of a frozen year into an active year and bypass
  -- the database hard-freeze boundary.
  if tg_op = 'UPDATE'
     and old.class_id is distinct from new.class_id
  then
    perform public.device_use_assert_year_writable(old.class_id);
  end if;

  return new;
end;
$function$;
CREATE OR REPLACE FUNCTION public.get_ai_feedback_memory_stats()
 RETURNS TABLE(total_feedback bigint, revision_after_ai_approve bigint, approve_after_ai_manual bigint, approve_after_ai_revision bigint, last_feedback_at timestamp with time zone, memory_enabled boolean, candidate_limit integer, selected_limit integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.is_teacher() then
    raise exception 'Chỉ giáo viên được xem thống kê bộ nhớ AI.' using errcode='42501';
  end if;

  return query
  select
    count(*)::bigint as total_feedback,
    count(*) filter (where feedback_type in ('teacher_revision_after_ai_approve','legacy_revision_after_ai_approve'))::bigint as revision_after_ai_approve,
    count(*) filter (where feedback_type='teacher_approve_after_ai_manual')::bigint as approve_after_ai_manual,
    count(*) filter (where feedback_type='teacher_approve_after_ai_revision')::bigint as approve_after_ai_revision,
    max(created_at) as last_feedback_at,
    coalesce((select value='true'::jsonb from public.app_settings where key='ai_feedback_memory_enabled'),true) as memory_enabled,
    80::integer as candidate_limit,
    25::integer as selected_limit
  from public.ai_review_feedback;
end;
$function$;
CREATE OR REPLACE FUNCTION public.get_ai_feedback_memory_stats(p_class_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(total_feedback bigint, revision_after_ai_approve bigint, approve_after_ai_manual bigint, approve_after_ai_revision bigint, last_feedback_at timestamp with time zone, memory_enabled boolean, candidate_limit integer, selected_limit integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    count(f.id)::bigint,
    count(f.id) filter(where f.feedback_type in ('teacher_revision_after_ai_approve','legacy_revision_after_ai_approve'))::bigint,
    count(f.id) filter(where f.feedback_type='teacher_approve_after_ai_manual')::bigint,
    count(f.id) filter(where f.feedback_type='teacher_approve_after_ai_revision')::bigint,
    max(f.created_at),
    coalesce((select cs.ai_feedback_memory_enabled from public.class_settings cs where cs.class_id=p_class_id),true),
    80,25
  from public.ai_review_feedback f
  where p_class_id is not null
    and (public.is_root_admin() or public.teacher_has_class(p_class_id))
    and f.class_id=p_class_id
$function$;
CREATE OR REPLACE FUNCTION public.guard_class_deactivation_with_active_learners()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.active=true and new.active=false and exists(
    select 1
    from public.profiles p
    where p.class_id=new.id
      and p.active=true
      and p.role::text in ('student','monitor')
  ) then
    raise exception 'ACTIVE_LEARNERS_EXIST: không thể khóa lớp khi vẫn còn học sinh/cán sự đang hoạt động.';
  end if;
  return new;
end; $function$;
CREATE OR REPLACE FUNCTION public.guard_root_admin_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(current_setting('app.root_admin_transfer',true),'')='on' then
    if tg_op='DELETE' then return old; end if;
    return new;
  end if;

  if tg_op='DELETE' and old.role::text='admin' then
    raise exception 'ROOT_ADMIN_IMMUTABLE';
  end if;

  if tg_op='UPDATE' and old.role::text='admin' and (
       new.role::text<>'admin'
       or new.active is distinct from old.active
       or new.deleted_at is distinct from old.deleted_at
       or new.class_id is not null
     ) then
    raise exception 'ROOT_ADMIN_IMMUTABLE';
  end if;

  if tg_op='DELETE' then return old; end if;
  return new;
end; $function$;
CREATE OR REPLACE FUNCTION public.guard_student_registration_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is not null
     and public.current_app_role()::text in ('student','monitor')
     and old.student_id=auth.uid()
  then
    -- The only student-side soft delete path is canceling their own
    -- emergency registration before that class session actually starts.
    if old.is_emergency=true and old.is_deleted=false and new.is_deleted=true
       and new.deleted_by=auth.uid() and new.deleted_at is not null
       and now()<public.study_session_start(old.class_id,old.week_id,old.weekday,old.period_number)
       and (to_jsonb(new)-'is_deleted'-'deleted_at'-'deleted_by'-'updated_at')
           =(to_jsonb(old)-'is_deleted'-'deleted_at'-'deleted_by'-'updated_at')
    then return new; end if;

    if new.id is distinct from old.id or new.student_id is distinct from old.student_id
       or new.class_id is distinct from old.class_id or new.week_id is distinct from old.week_id
       or new.weekday is distinct from old.weekday or new.period_number is distinct from old.period_number
    then raise exception 'Không được thay đổi chủ sở hữu, lớp hoặc ô thời khóa biểu của đăng ký.' using errcode='42501'; end if;

    if new.teacher_comment is distinct from old.teacher_comment
       or new.auto_review_reason is distinct from old.auto_review_reason
       or new.ai_review_status is distinct from old.ai_review_status
       or new.ai_decision is distinct from old.ai_decision
       or new.ai_category is distinct from old.ai_category
       or new.ai_confidence is distinct from old.ai_confidence
       or new.ai_revision_status is distinct from old.ai_revision_status
       or new.ai_revision_confidence is distinct from old.ai_revision_confidence
       or new.ai_reason is distinct from old.ai_reason
       or new.ai_model is distinct from old.ai_model
       or new.ai_reviewed_at is distinct from old.ai_reviewed_at
       or new.ai_review_count is distinct from old.ai_review_count
       or new.is_emergency is distinct from old.is_emergency
       or new.emergency_reason is distinct from old.emergency_reason
       or new.emergency_requested_at is distinct from old.emergency_requested_at
       or new.device_detection_source is distinct from old.device_detection_source
       or new.device_detection_confidence is distinct from old.device_detection_confidence
       or new.revision_overdue_at is distinct from old.revision_overdue_at
       or new.approved_by is distinct from old.approved_by
       or new.is_deleted is distinct from old.is_deleted
       or new.deleted_at is distinct from old.deleted_at
       or new.deleted_by is distinct from old.deleted_by
    then raise exception 'Không được thay đổi trường do giáo viên hoặc máy chủ quản lý.' using errcode='42501'; end if;

    -- Resubmitting a previously-approved registration is a supported student
    -- action: apply_smart_approval() always reverts it to 'submitted' and
    -- clears the approval trail, forcing approval_source to 'manual' and
    -- approved_at to null regardless of what the client sends. It is
    -- therefore safe to let exactly that reset shape through here; any other
    -- value for these two columns, on any row, is still rejected.
    if old.status = 'approved' then
      if (new.approval_source is distinct from old.approval_source and new.approval_source is distinct from 'manual')
         or (new.approved_at is distinct from old.approved_at and new.approved_at is not null)
      then raise exception 'Không được thay đổi trường do giáo viên hoặc máy chủ quản lý.' using errcode='42501'; end if;
    else
      if new.approval_source is distinct from old.approval_source
         or new.approved_at is distinct from old.approved_at
      then raise exception 'Không được thay đổi trường do giáo viên hoặc máy chủ quản lý.' using errcode='42501'; end if;
    end if;
  end if;
  return new;
end$function$;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.profiles(id,full_name,email,role,active,class_id)
  values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),new.email,'student',false,null)
  on conflict(id) do nothing;
  return new;
end; $function$;
CREATE OR REPLACE FUNCTION public.homework_ai(p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare n public.homework_notices; cand jsonb; score numeric; candidate uuid; st public.homework_settings; final_state text; old jsonb;begin
 select * into n from public.homework_notices where id=(p_data->>'id')::uuid;
 if n.id is null then raise exception 'Không tìm thấy bài';end if;
 perform pg_advisory_xact_lock(hashtextextended('homework:'||n.class_id::text,0));
 select * into n from public.homework_notices where id=n.id;
 if n.id is null then return '{"done":true,"deleted":true}';end if;
 if n.status<>'pending_duplicate_review' then return jsonb_build_object('done',true,'status',n.status);end if;
 -- An error attempt (no score/decision) is retryable, not a completed review.
 if exists(select 1 from public.homework_duplicate_reviews rv where rv.notice_id=n.id and rv.revision=n.revision and (rv.score is not null or rv.decision is not null))then return jsonb_build_object('done',true,'status',n.status);end if;
 cand:=homework_private.candidates(n);
 select * into st from public.homework_settings where class_id=n.class_id;
 if p_action='snapshot' then
 select before_data into old from public.homework_contribution_events where notice_id=n.id and event_type='submit' order by created_at desc,id desc limit 1;
 return jsonb_build_object('notice',to_jsonb(n),'previous',old,'candidates',cand,'fingerprint',md5(cand::text||homework_private.ai_config(st)::text),'settings',homework_private.ai_config(st));
 elsif p_action='finish' then
 if n.revision is distinct from (p_data->>'revision')::int or md5(cand::text||homework_private.ai_config(st)::text) is distinct from (p_data->>'fingerprint') then return '{"stale":true}';end if;

 if not exists(select 1 from public.profiles where id=n.author_id and active and deleted_at is null) or not exists(select 1 from public.classes where id=n.class_id and active) then
 insert into public.homework_duplicate_reviews(notice_id,revision,reason)values(n.id,n.revision,'Tài khoản hoặc lớp đã ngừng hoạt động trong lúc AI xử lý.')on conflict(notice_id,revision)do update set reason=excluded.reason;
 perform homework_private.audit(n.class_id,n.id,null,'ai_authorization_changed');
 return '{"status":"pending_duplicate_review"}';
 end if;
 if p_data->>'error' is not null then
 insert into public.homework_duplicate_reviews(notice_id,revision,reason)values(n.id,n.revision,'AI tạm thời không xử lý được; có thể thử kiểm tra lại.')on conflict(notice_id,revision)do update set reason=excluded.reason;
 perform homework_private.audit(n.class_id,n.id,null,'ai_error',null,jsonb_build_object('code',left(p_data->>'error',80)));
 perform homework_private.notify_managers(n.class_id,n.id,'system','AI Báo bài lỗi; nội dung đã lưu và đang chờ giáo viên.');
 perform homework_private.notify_managers(n.class_id,n.id,'pending','Có Báo bài chưa được AI kiểm tra.');return '{"status":"pending_duplicate_review"}';
 end if;
 score:=(p_data->>'score')::numeric;candidate:=nullif(p_data->>'candidate_id','')::uuid;
 if score is null or score<0 or score>100 or (score<>0 and candidate is null)then raise exception 'Kết quả AI không hợp lệ';end if;
 if candidate is not null and not exists(select 1 from jsonb_array_elements(cand)x where (x->>'id')::uuid=candidate)then raise exception 'Candidate ngoài snapshot';end if;
 final_state:=case when candidate is null then 'published' when score>=st.reject_threshold then 'duplicate_rejected'when score>=st.pending_threshold then 'pending_duplicate_review'else 'published'end;
 update public.homework_notices set status=final_state,duplicate_tombstone_id=null,duplicate_of=case when score>=st.pending_threshold then candidate else null end,
 published_at=case when final_state='published'then coalesce(published_at,now())else published_at end,updated_at=now()where id=n.id;
 insert into public.homework_duplicate_reviews(notice_id,revision,candidate_id,score,reason)values(n.id,n.revision,candidate,score,left(p_data->>'reason',2000))on conflict(notice_id,revision)do update set candidate_id=excluded.candidate_id,score=excluded.score,reason=excluded.reason;
 perform homework_private.audit(n.class_id,n.id,null,'ai_'||final_state,to_jsonb(n),jsonb_build_object('score',score,'candidate',candidate));
 if final_state in('published','pending_duplicate_review')then perform homework_private.notify_managers(n.class_id,n.id,final_state,case when final_state='published'then 'Có Báo bài mới: 'else 'Có bài nghi trùng: 'end||n.title);end if;
 perform homework_private.backlog(n.class_id);return jsonb_build_object('status',final_state);
 end if;raise exception 'Thao tác AI không hợp lệ';end$function$;
CREATE OR REPLACE FUNCTION public.homework_api(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c uuid:=nullif(p_data->>'class_id','')::uuid;begin
 -- An allowlist, not a blocklist: a new mutating action added later is withheld
 -- by default rather than silently permitted against an archived year.
 if c is not null and p_action not in('load','inbox','context','catalog_list','oversight')
  and homework_private.archive_readonly(c) then
  raise exception 'Năm học đã đóng gói và chỉ còn xem được. Dữ liệu cũ nằm trong bản lưu đã tải về.' using errcode='42501';
 end if;
 return homework_private.api_v8(p_action,p_data);
end $function$;
CREATE OR REPLACE FUNCTION public.homework_archive(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.profiles; y public.school_years; ar public.homework_archives;
 st record; removed bigint:=0; total integer; matched integer; reported integer;
 now_counts jsonb; year_id uuid; cls uuid[];
begin
 a:=homework_private.archive_admin();

 if p_action='preflight' then
  year_id:=(p_data->>'school_year_id')::uuid;
  select * into y from public.school_years where id=year_id;
  if y.id is null then raise exception 'Không tìm thấy năm học';end if;
  return jsonb_build_object(
   'school_year_id',y.id,'school_year_name',y.name,'is_active',y.is_active,
   'archive_state',y.archive_state,
   'counts',homework_private.archive_counts(y.id),
   'media_bytes',(select coalesce(sum(size_bytes),0) from public.homework_attachments where school_year_id=y.id and status='active'),
   'blockers',homework_private.archive_blockers(y.id),
   'archives',(select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc),'[]'::jsonb)
     from public.homework_archives r where r.school_year_id=y.id));

 elsif p_action='list' then
  -- RB-710/AC-712: the index outlives the data, so it is readable on its own.
  return jsonb_build_object('archives',(select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc),'[]'::jsonb) from public.homework_archives r));

 elsif p_action='begin' then
  year_id:=(p_data->>'school_year_id')::uuid;
  select * into y from public.school_years where id=year_id for update;
  if y.id is null then raise exception 'Không tìm thấy năm học';end if;
  -- A year that is still being taught cannot be archived: the run would have to
  -- freeze it, and freezing the live year mid-term breaks the school day. Switch
  -- the active year first, which is the real end-of-year sequence anyway.
  if y.is_active then raise exception 'Không đóng gói được năm học đang hoạt động. Hãy chuyển năm học hiện hành sang năm mới trước.' using errcode='42501';end if;
  if jsonb_array_length(homework_private.archive_blockers(y.id))>0 then
   raise exception 'Năm học chưa sẵn sàng để đóng gói. Hãy xử lý các cảnh báo trong bước kiểm tra trước.';
  end if;
  -- The write freeze starts here, not after verification. An archive taken from a
  -- year that can still be written to is out of date the moment it finishes, and
  -- the purge it authorises would delete rows the ZIP never contained.
  update public.school_years set archive_state='archiving' where id=y.id and archive_state='active';
  -- NOT NULL on the column catches a missing key; this catches an empty or
  -- blank one, which is what a client bug actually produces.
  if coalesce(trim(p_data->>'archive_format_version'),'')='' then raise exception 'Thiếu archive_format_version';end if;
  insert into public.homework_archives(school_year_id,school_year_name,archive_format_version,counts,created_by,
   begin_fingerprint,media_count,media_bytes)
  values(y.id,y.name,p_data->>'archive_format_version',homework_private.archive_counts(y.id),a.id,
   homework_private.archive_fingerprint(y.id),
   (select count(*) from public.homework_attachments where school_year_id=y.id and status='active'),
   (select coalesce(sum(size_bytes),0) from public.homework_attachments where school_year_id=y.id and status='active'))
  returning * into ar;
  -- Snapshot the inventory. archive_path is decided here, not by the browser, so
  -- the ZIP layout the viewer expects cannot drift from what was recorded.
  insert into public.homework_archive_media(archive_id,attachment_id,object_key,size_bytes,expected_checksum,archive_path)
  select ar.id,m.id,m.object_key,m.size_bytes,m.checksum,'media/'||m.id::text||'.webp'
   from public.homework_attachments m where m.school_year_id=y.id and m.status='active';
  insert into public.homework_archive_events(archive_id,actor_id,event_type,data)
   values(ar.id,a.id,'archive_begin',jsonb_build_object('school_year_id',y.id,'counts',ar.counts));
  return to_jsonb(ar);

 elsif p_action='media_manifest' then
  -- Deliberately does not return expected_checksum: the client must derive its
  -- answer from the bytes it actually downloaded.
  select * into ar from public.homework_archives where id=(p_data->>'archive_id')::uuid;
  if ar.id is null then raise exception 'Không tìm thấy bản lưu';end if;
  return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object(
    'attachment_id',x.attachment_id,'object_key',x.object_key,'size_bytes',x.size_bytes,'archive_path',x.archive_path)
    order by x.attachment_id),'[]'::jsonb)
   from (select * from public.homework_archive_media where archive_id=ar.id
     and (p_data->>'after' is null or attachment_id>(p_data->>'after')::uuid)
     order by attachment_id limit least(coalesce((p_data->>'limit')::int,200),500)) x));

 elsif p_action='report_media' then
  select * into ar from public.homework_archives where id=(p_data->>'archive_id')::uuid for update;
  if ar.id is null or ar.status<>'building' then raise exception 'Bản lưu không ở trạng thái đang đóng gói';end if;
  update public.homework_archive_media t set reported_checksum=lower(s.checksum),reported_bytes=s.bytes,reported_at=clock_timestamp()
   from jsonb_to_recordset(p_data->'items') as s(attachment_id uuid,checksum text,bytes integer)
   where t.archive_id=ar.id and t.attachment_id=s.attachment_id;
  return jsonb_build_object('ok',true,
   'reported',(select count(*) from public.homework_archive_media where archive_id=ar.id and reported_checksum is not null),
   'total',(select count(*) from public.homework_archive_media where archive_id=ar.id));

 elsif p_action='complete' then
  -- RB-706/RB-707/AC-705/AC-706. Everything that can be checked server-side is
  -- checked here, and the result is either 'verified' or 'failed'. There is no
  -- separate "mark it verified" action for an Admin to reach past this.
  select * into ar from public.homework_archives where id=(p_data->>'archive_id')::uuid for update;
  if ar.id is null or ar.status<>'building' then raise exception 'Bản lưu không ở trạng thái đang đóng gói';end if;
  select count(*),count(reported_checksum),count(*) filter(where reported_checksum=lower(expected_checksum) and reported_bytes=size_bytes)
   into total,reported,matched from public.homework_archive_media where archive_id=ar.id;
  now_counts:=homework_private.archive_counts(ar.school_year_id);
  if coalesce(p_data->>'checksum','') !~ '^[a-f0-9]{64}$' then
   update public.homework_archives set status='failed',failure_reason='missing_checksum' where id=ar.id returning * into ar;
  elsif reported<total then
   -- EC-702: 1248 of 1249 is a failure, not a rounding error.
   update public.homework_archives set status='failed',
    failure_reason='media_missing:'||(total-reported)::text where id=ar.id returning * into ar;
  elsif matched<total then
   -- EC-701/EC-707: the bytes that reached the ZIP are not the bytes recorded.
   update public.homework_archives set status='failed',
    failure_reason='media_checksum_mismatch:'||(total-matched)::text where id=ar.id returning * into ar;
  elsif now_counts<>ar.counts then
   -- The year changed while the archive was being built, so the ZIP is already
   -- out of date and must not become the thing purge is measured against.
   update public.homework_archives set status='failed',failure_reason='year_changed_during_archive' where id=ar.id returning * into ar;
  elsif ar.begin_fingerprint is distinct from homework_private.archive_fingerprint(ar.school_year_id) then
   -- The decisive check. Counts cannot see an update, and the freeze does not
   -- cover the SQL editor or a service-role job, so the only way to know the ZIP
   -- still matches is to compare the content hash against the one taken before
   -- the browser read a single row. Hashing at `complete` alone would absorb the
   -- change instead of catching it.
   update public.homework_archives set status='failed',failure_reason='dataset_changed_during_archive' where id=ar.id returning * into ar;
  else
   -- The stored value is the *begin* fingerprint, which is what the ZIP holds.
   -- It equals the current one here, but saying so explicitly keeps "the archive
   -- represents the dataset it was built from" true by construction.
   update public.homework_archives set status='verified',checksum=lower(p_data->>'checksum'),
    archive_size_bytes=nullif(p_data->>'archive_size_bytes','')::bigint,
    dataset_fingerprint=ar.begin_fingerprint,
    verified_at=clock_timestamp(),verified_by=a.id where id=ar.id returning * into ar;
  end if;
  -- A failed run must not leave the year frozen for ever. The freeze is released
  -- only if nothing else is holding it: another verified archive of the same year
  -- is still waiting to be purged and its freeze must stand.
  if ar.status='failed' then perform homework_private.archive_release(ar.school_year_id);end if;
  insert into public.homework_archive_events(archive_id,actor_id,event_type,data)
   values(ar.id,a.id,'archive_'||ar.status,jsonb_build_object('media_total',total,'media_reported',reported,'media_matched',matched,'failure_reason',ar.failure_reason));
  return to_jsonb(ar);

 elsif p_action='confirm_download' then
  -- RB-708 step 3, made checkable. The Admin re-opens the file they saved; the
  -- viewer recomputes the fingerprint from that file and posts it here. A ticked
  -- box proves nothing about a download that was interrupted (EC-703); a matching
  -- fingerprint proves the file exists, is readable and is this archive.
  select * into ar from public.homework_archives where id=(p_data->>'archive_id')::uuid for update;
  if ar.id is null or ar.status<>'verified' then raise exception 'Chỉ xác nhận được bản lưu đã kiểm tra đạt';end if;
  if lower(coalesce(p_data->>'checksum','')) is distinct from ar.checksum then
   insert into public.homework_archive_events(archive_id,actor_id,event_type,data)
    values(ar.id,a.id,'archive_download_mismatch','{}'::jsonb);
   raise exception 'Tệp vừa mở không khớp với bản lưu này';
  end if;
  update public.homework_archives set download_confirmed_at=clock_timestamp(),download_confirmed_by=a.id
   where id=ar.id returning * into ar;
  insert into public.homework_archive_events(archive_id,actor_id,event_type,data)
   values(ar.id,a.id,'archive_download_confirmed','{}'::jsonb);
  return to_jsonb(ar);

 elsif p_action='set_read_only' then
  -- RB-711: only after a verified archive exists for that year.
  select * into ar from public.homework_archives where id=(p_data->>'archive_id')::uuid;
  if ar.id is null or ar.status not in('verified','purging','purged') then raise exception 'Cần một bản lưu đã kiểm tra đạt trước khi khoá năm học';end if;
  update public.school_years set archive_state='archived_read_only' where id=ar.school_year_id;
  insert into public.homework_archive_events(archive_id,actor_id,event_type,data)
   values(ar.id,a.id,'year_read_only',jsonb_build_object('school_year_id',ar.school_year_id));
  return jsonb_build_object('ok',true,'school_year_id',ar.school_year_id,'archive_state','archived_read_only');

 elsif p_action='abandon' then
  -- A run whose tab was closed leaves the year frozen. Admin can end it, which
  -- marks the archive failed and releases the freeze if nothing else holds it.
  select * into ar from public.homework_archives where id=(p_data->>'archive_id')::uuid for update;
  if ar.id is null or ar.status<>'building' then raise exception 'Chỉ huỷ được bản lưu đang đóng gói dở';end if;
  update public.homework_archives set status='failed',failure_reason='abandoned' where id=ar.id returning * into ar;
  perform homework_private.archive_release(ar.school_year_id);
  insert into public.homework_archive_events(archive_id,actor_id,event_type,data)
   values(ar.id,a.id,'archive_abandoned','{}'::jsonb);
  return to_jsonb(ar);

 elsif p_action='purge_begin' then
  select * into ar from public.homework_archives where id=(p_data->>'archive_id')::uuid for update;
  if ar.id is null then raise exception 'Không tìm thấy bản lưu';end if;
  if ar.status='purging' then return jsonb_build_object('ok',true,'resumed',true)||to_jsonb(ar);end if;
  -- BR-702/AC-707.
  if ar.status<>'verified' then raise exception 'Chỉ xoá được sau khi bản lưu đạt kiểm tra' using errcode='42501';end if;
  -- AC-708.
  if ar.download_confirmed_at is null then raise exception 'Hãy mở lại tệp đã tải để xác nhận trước khi xoá' using errcode='42501';end if;
  if coalesce(trim(p_data->>'reason'),'')='' then raise exception 'Cần nêu lý do xoá';end if;
  if coalesce((p_data->>'confirm_irreversible')::boolean,false) is not true then raise exception 'Cần xác nhận hiểu rằng thao tác này không hoàn tác được';end if;
  select * into y from public.school_years where id=ar.school_year_id for update;
  -- AC-723/EC-712.
  if y.is_active then raise exception 'Không xoá dữ liệu của năm học đang hoạt động' using errcode='42501';end if;
  -- The freeze must still be on. If someone released the year back to active, the
  -- data has been writable since, and this archive can no longer speak for it.
  if y.archive_state='active' then raise exception 'Năm học đã được mở khoá ghi sau khi đóng gói. Hãy đóng gói lại trước khi xoá.' using errcode='42501';end if;
  -- And the decisive check: does the year still hash to what was archived? Counts
  -- cannot see an update, and this runs inside the same statement that flips the
  -- archive to 'purging', so nothing can slip in between the check and the purge.
  -- No audit row is written for a refusal: raising rolls back the insert that
  -- would record it. The refusal reaches the Admin as the error, the archive
  -- stays 'verified', and nothing was touched — which is the state that matters.
  if ar.dataset_fingerprint is distinct from homework_private.archive_fingerprint(ar.school_year_id) then
   raise exception 'Dữ liệu năm học đã thay đổi so với bản lưu này. Hãy đóng gói lại trước khi xoá.' using errcode='42501';
  end if;
  update public.homework_archives set status='purging',purge_reason=trim(p_data->>'reason'),purge_started_at=clock_timestamp()
   where id=ar.id returning * into ar;
  insert into public.homework_archive_steps(archive_id,step,seq)
  values(ar.id,'reactions',1),(ar.id,'reminders',2),(ar.id,'duplicate_reviews',3),
   (ar.id,'reports',4),(ar.id,'corrections',5),(ar.id,'moderation_events',6),(ar.id,'notifications',7),
   (ar.id,'contribution_events',8),(ar.id,'notices',9),
   (ar.id,'english_group_members',10),(ar.id,'english_groups',11),(ar.id,'class_subjects',12),
   -- Last on purpose. The FEAT-006 worker drops an attachment row only once
   -- nothing references it, so queuing before the notices are gone would make
   -- the first worker pass defer every job. Queuing here means the objects are
   -- already unreferenced and the first pass can finish them.
   (ar.id,'media_enqueue',13)
  on conflict do nothing;
  insert into public.homework_archive_events(archive_id,actor_id,event_type,data)
   values(ar.id,a.id,'purge_begin',jsonb_build_object('reason',ar.purge_reason,'school_year_id',ar.school_year_id));
  return to_jsonb(ar)||jsonb_build_object('steps',(select count(*) from public.homework_archive_steps where archive_id=ar.id));

 elsif p_action='purge_step' then
  select * into ar from public.homework_archives where id=(p_data->>'archive_id')::uuid for update;
  if ar.id is null or ar.status<>'purging' then raise exception 'Bản lưu không đang trong quá trình xoá';end if;
  year_id:=ar.school_year_id;
  select array_agg(id) into cls from public.classes where school_year_id=year_id;
  cls:=coalesce(cls,'{}'::uuid[]);
  select * into st from public.homework_archive_steps where archive_id=ar.id and state<>'done' order by seq limit 1;
  if st is null then
   update public.homework_archives set status='purged',purged_at=clock_timestamp(),purged_by=a.id where id=ar.id returning * into ar;
   -- A purged year is a historical record for good. Promoting it from the
   -- temporary run freeze to the permanent state says so, and keeps the year out
   -- of the one path that could otherwise hand it back as writable.
   update public.school_years set archive_state='archived_read_only' where id=ar.school_year_id;
   insert into public.homework_archive_events(archive_id,actor_id,event_type,data)
    values(ar.id,a.id,'purge_complete','{}'::jsonb);
   return to_jsonb(ar)||jsonb_build_object('done',true);
  end if;
  update public.homework_archive_steps set state='running',started_at=coalesce(started_at,clock_timestamp())
   where archive_id=ar.id and step=st.step;
  -- The one key that opens the hard freeze, scoped to this transaction and to
  -- this archive. Set after the gates above have all passed.
  perform set_config('homework.archive_purge',ar.id::text,true);
  -- Every branch is scoped by the year and is idempotent, so a step interrupted
  -- halfway can simply be run again (EC-705/AC-722).
  if st.step='reactions' then
   with d as (delete from public.homework_notice_reactions where notice_id in(select id from public.homework_notices where school_year_id=year_id) returning 1) select count(*) into removed from d;
  elsif st.step='reminders' then
   with d as (delete from public.homework_notice_reminders where notice_id in(select id from public.homework_notices where school_year_id=year_id) returning 1) select count(*) into removed from d;
  elsif st.step='duplicate_reviews' then
   with d as (delete from public.homework_duplicate_reviews where notice_id in(select id from public.homework_notices where school_year_id=year_id) returning 1) select count(*) into removed from d;
  elsif st.step='reports' then
   with d as (delete from public.homework_reports where notice_id in(select id from public.homework_notices where school_year_id=year_id) returning 1) select count(*) into removed from d;
  elsif st.step='corrections' then
   with d as (delete from public.homework_corrections where notice_id in(select id from public.homework_notices where school_year_id=year_id) returning 1) select count(*) into removed from d;
  elsif st.step='moderation_events' then
   with d as (delete from public.homework_moderation_events where class_id=any(cls) returning 1) select count(*) into removed from d;
  elsif st.step='notifications' then
   with d as (delete from public.homework_notifications where class_id=any(cls) returning 1) select count(*) into removed from d;
  elsif st.step='contribution_events' then
   with d as (delete from public.homework_contribution_events where class_id=any(cls) returning 1) select count(*) into removed from d;
  elsif st.step='notices' then
   -- Cascades homework_notice_media and homework_media_history, which is what
   -- lets the FEAT-006 worker finally drop the attachment rows once R2 confirms.
   update public.homework_notices set duplicate_of=null,duplicate_tombstone_id=null where school_year_id=year_id;
   with d as (delete from public.homework_notices where school_year_id=year_id returning 1) select count(*) into removed from d;
  elsif st.step='english_group_members' then
   with d as (delete from public.english_group_members where school_year_id=year_id returning 1) select count(*) into removed from d;
  elsif st.step='english_groups' then
   -- Groups a surviving tombstone still points at are kept; see DEC-091.
   with d as (delete from public.english_groups where school_year_id=year_id
     and id not in(select english_group_id from public.homework_tombstones where english_group_id is not null) returning 1)
   select count(*) into removed from d;
  elsif st.step='class_subjects' then
   -- Per-class rows only. grade_subject_catalog is shared across years and is
   -- never touched (RB-714/EC-706/AC-711). Subjects a surviving tombstone points
   -- at are kept too: FEAT-002 makes the tombstone permanent and undeletable, so
   -- its foreign keys must keep resolving (DEC-091).
   with d as (delete from public.class_subjects where class_id=any(cls)
     and id not in(select subject_id from public.homework_tombstones where subject_id is not null) returning 1)
   select count(*) into removed from d;
  elsif st.step='media_enqueue' then
   -- RB-713: media leaves R2 only through the FEAT-006 outbox, and only now,
   -- after the archive is verified. FEAT-007 adds no deletion path of its own.
   -- Deleting the notices above already queued the referenced objects through
   -- the FEAT-006 trigger; this sweeps up anything the year owns that no
   -- surviving row pointed at, and re-labels every job with the purge reason.
   select count(*) into removed from public.homework_attachments where school_year_id=year_id;
   perform homework_private.media_enqueue(m.id,'year_purge')
    from public.homework_attachments m where m.school_year_id=year_id;
  else raise exception 'Bước xoá không hợp lệ: %',st.step;
  end if;
  update public.homework_archive_steps set state='done',rows_removed=removed,finished_at=clock_timestamp()
   where archive_id=ar.id and step=st.step;
  insert into public.homework_archive_events(archive_id,actor_id,event_type,data)
   values(ar.id,a.id,'purge_step',jsonb_build_object('step',st.step,'rows_removed',removed));
  return jsonb_build_object('done',false,'step',st.step,'rows_removed',removed,
   'remaining',(select count(*) from public.homework_archive_steps where archive_id=ar.id and state<>'done'),
   'steps',(select coalesce(jsonb_agg(to_jsonb(s) order by s.seq),'[]'::jsonb) from public.homework_archive_steps s where s.archive_id=ar.id));

 elsif p_action='purge_status' then
  select * into ar from public.homework_archives where id=(p_data->>'archive_id')::uuid;
  if ar.id is null then raise exception 'Không tìm thấy bản lưu';end if;
  return to_jsonb(ar)||jsonb_build_object(
   'steps',(select coalesce(jsonb_agg(to_jsonb(s) order by s.seq),'[]'::jsonb) from public.homework_archive_steps s where s.archive_id=ar.id),
   'media_pending',(select count(*) from public.homework_attachments where school_year_id=ar.school_year_id));
 end if;
 raise exception 'Thao tác kho lưu trữ không hợp lệ';
end $function$;
CREATE OR REPLACE FUNCTION public.homework_archive_export(p_archive uuid, p_entity text, p_after text DEFAULT NULL::text, p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.profiles; ar public.homework_archives; rows_out jsonb; n integer:=least(coalesce(p_limit,500),1000); year_id uuid; cls uuid[];
begin
 a:=homework_private.archive_admin();
 select * into ar from public.homework_archives where id=p_archive;
 if ar.id is null then raise exception 'Không tìm thấy bản lưu';end if;
 year_id:=ar.school_year_id;
 select coalesce(array_agg(id),'{}'::uuid[]) into cls from public.classes where school_year_id=year_id;
 if p_entity='classes' then
  select jsonb_agg(to_jsonb(c) order by c.id) into rows_out from (select * from public.classes where school_year_id=year_id and (p_after is null or id>p_after::uuid) order by id limit n) c;
 elsif p_entity='students' then
  select jsonb_agg(jsonb_build_object('id',p.id,'full_name',p.full_name,'role',p.role,'active',p.active,'class_id',p.class_id,'deleted_at',p.deleted_at) order by p.id) into rows_out
   from (select * from public.profiles where class_id=any(cls) and (p_after is null or id>p_after::uuid) order by id limit n) p;
 elsif p_entity='subjects' then
  -- The shared catalog rows this year referenced. Exported for readability of the
  -- archive; never purged, because other years still use them.
  select jsonb_agg(to_jsonb(g) order by g.id) into rows_out from (
   select * from public.grade_subject_catalog where id in(select catalog_subject_id from public.class_subjects where class_id=any(cls))
    and (p_after is null or id>p_after::uuid) order by id limit n) g;
 elsif p_entity='class_subjects' then
  select jsonb_agg(to_jsonb(s) order by s.id) into rows_out from (select * from public.class_subjects where class_id=any(cls) and (p_after is null or id>p_after::uuid) order by id limit n) s;
 elsif p_entity='english_groups' then
  select jsonb_agg(to_jsonb(g) order by g.id) into rows_out from (select * from public.english_groups where school_year_id=year_id and (p_after is null or id>p_after::uuid) order by id limit n) g;
 elsif p_entity='english_group_memberships' then
  select jsonb_agg(to_jsonb(m) order by m.id) into rows_out from (select * from public.english_group_members where school_year_id=year_id and (p_after is null or id>p_after::uuid) order by id limit n) m;
 elsif p_entity='homework_notices' then
  select jsonb_agg(to_jsonb(x) order by x.id) into rows_out from (select * from public.homework_notices where school_year_id=year_id and (p_after is null or id>p_after::uuid) order by id limit n) x;
 elsif p_entity='homework_reactions' then
  select jsonb_agg(to_jsonb(x) order by x.notice_id,x.user_id) into rows_out from (
   select * from public.homework_notice_reactions where notice_id in(select id from public.homework_notices where school_year_id=year_id)
    and (p_after is null or (notice_id::text||':'||user_id::text)>p_after) order by notice_id,user_id limit n) x;
 elsif p_entity='homework_reminders' then
  select jsonb_agg(to_jsonb(x) order by x.id) into rows_out from (select * from public.homework_notice_reminders where notice_id in(select id from public.homework_notices where school_year_id=year_id) and (p_after is null or id>p_after::uuid) order by id limit n) x;
 elsif p_entity='homework_reports' then
  select jsonb_agg(to_jsonb(x) order by x.id) into rows_out from (select * from public.homework_reports where notice_id in(select id from public.homework_notices where school_year_id=year_id) and (p_after is null or id>p_after::uuid) order by id limit n) x;
 elsif p_entity='homework_corrections' then
  select jsonb_agg(to_jsonb(x) order by x.id) into rows_out from (select * from public.homework_corrections where notice_id in(select id from public.homework_notices where school_year_id=year_id) and (p_after is null or id>p_after::uuid) order by id limit n) x;
 elsif p_entity='homework_revisions' then
  select jsonb_agg(to_jsonb(x) order by x.correction_id,x.round) into rows_out from (
   select * from public.homework_correction_rounds where correction_id in(
     select id from public.homework_corrections where notice_id in(select id from public.homework_notices where school_year_id=year_id))
    and (p_after is null or (correction_id::text||':'||round::text)>p_after) order by correction_id,round limit n) x;
 elsif p_entity='homework_duplicate_reviews' then
  select jsonb_agg(to_jsonb(x) order by x.id) into rows_out from (select * from public.homework_duplicate_reviews where notice_id in(select id from public.homework_notices where school_year_id=year_id) and (p_after is null or id>p_after::uuid) order by id limit n) x;
 elsif p_entity='homework_tombstones' then
  -- EC-713: the hard-delete record is kept as FEAT-002 wrote it. The archive
  -- preserves the redaction rather than reconstructing what was removed.
  select jsonb_agg(to_jsonb(x) order by x.notice_id) into rows_out from (select * from public.homework_tombstones where class_id=any(cls) and (p_after is null or notice_id>p_after::uuid) order by notice_id limit n) x;
 elsif p_entity='audit' then
  select jsonb_agg(to_jsonb(x) order by x.id) into rows_out from (select * from public.homework_contribution_events where class_id=any(cls) and (p_after is null or id>p_after::uuid) order by id limit n) x;
 elsif p_entity='moderation' then
  select jsonb_agg(to_jsonb(x) order by x.id) into rows_out from (select * from public.homework_moderation_events where class_id=any(cls) and (p_after is null or id>p_after::uuid) order by id limit n) x;
 elsif p_entity='media_index' then
  select jsonb_agg(jsonb_build_object('attachment_id',m.attachment_id,'object_key',m.object_key,'size_bytes',m.size_bytes,
    'archive_path',m.archive_path,
    'notice_id',(select notice_id from public.homework_notice_media where attachment_id=m.attachment_id),
    'history',(select coalesce(jsonb_agg(jsonb_build_object('notice_id',h.notice_id,'revision',h.revision)),'[]'::jsonb) from public.homework_media_history h where h.attachment_id=m.attachment_id),
    'correction_round',(select coalesce(jsonb_agg(jsonb_build_object('correction_id',r.correction_id,'round',r.round)),'[]'::jsonb) from public.homework_correction_rounds r where r.attachment_id=m.attachment_id)) order by m.attachment_id) into rows_out
   from (select * from public.homework_archive_media where archive_id=ar.id and (p_after is null or attachment_id>p_after::uuid) order by attachment_id limit n) m;
 else raise exception 'Thực thể không hợp lệ: %',p_entity;
 end if;
 return jsonb_build_object('entity',p_entity,'rows',coalesce(rows_out,'[]'::jsonb));
end $function$;
CREATE OR REPLACE FUNCTION public.homework_maintenance()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c uuid;begin
 for c in select distinct class_id from public.homework_corrections where status='awaiting_author' order by class_id loop
  perform homework_private.expire_corrections(c);
 end loop;
 perform homework_private.homework_maintenance_v4();
end $function$;
CREATE OR REPLACE FUNCTION public.homework_media(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c uuid:=(p_data->>'class_id')::uuid; a public.profiles; m public.homework_attachments;
 n public.homework_notices;cor public.homework_corrections; target uuid:=nullif(p_data->>'notice_id','')::uuid;
 rid uuid:=nullif(p_data->>'request_id','')::uuid; mid uuid; until_time timestamptz;
begin
 a:=homework_private.actor(c);
 perform pg_advisory_xact_lock(hashtextextended('homework:'||c::text,0));
 if p_action='prepare' then
  if a.role::text not in('student','monitor','teacher') then raise exception 'Chỉ tác giả được tải ảnh' using errcode='42501';end if;
  if rid is null then raise exception 'Thiếu mã yêu cầu';end if;
  if target is not null then
   select * into n from public.homework_notices where id=target and class_id=c for update;
   if n.id is null or n.author_id<>a.id or n.status in('deleted','replaced') then raise exception 'Không có quyền thay ảnh' using errcode='42501';end if;
   select * into cor from public.homework_corrections where notice_id=target and status in('awaiting_author','awaiting_teacher');
   if cor.id is not null then
    if cor.status<>'awaiting_author' or cor.id is distinct from nullif(p_data->>'correction_id','')::uuid or cor.round is distinct from (p_data->>'round')::smallint or cor.version is distinct from (p_data->>'version')::int
     or exists(select 1 from public.homework_correction_rounds where correction_id=cor.id and round=cor.round and due_at<=clock_timestamp()) then raise exception 'Yêu cầu chỉnh sửa đã thay đổi';end if;
   elsif nullif(p_data->>'correction_id','') is not null or n.revision is distinct from (p_data->>'revision')::int then raise exception 'Bài đã thay đổi';end if;
  elsif nullif(p_data->>'correction_id','') is not null then raise exception 'Không có bản chỉnh sửa';end if;
  select * into m from public.homework_attachments where owner_id=a.id and upload_id=coalesce(nullif(p_data->>'upload_id','')::uuid,rid);
  if m.id is not null then
   if m.class_id<>c or m.notice_id is distinct from target or m.checksum is distinct from p_data->>'checksum' or m.size_bytes is distinct from (p_data->>'size_bytes')::int or m.width is distinct from (p_data->>'width')::int or m.height is distinct from (p_data->>'height')::int
    or m.correction_id is distinct from cor.id or m.status<>'pending' or m.expires_at<=clock_timestamp() then raise exception 'Yêu cầu tải ảnh đã thay đổi hoặc hết hạn';end if;
   return to_jsonb(m);
  end if;
  mid:=gen_random_uuid();
  insert into public.homework_attachments(id,owner_id,class_id,school_year_id,notice_id,request_id,upload_id,base_revision,correction_id,correction_round,object_key,staging_key,size_bytes,width,height,checksum)
  values(mid,a.id,c,(select school_year_id from public.classes where id=c),target,rid,coalesce(nullif(p_data->>'upload_id','')::uuid,rid),n.revision,cor.id,cor.round,
   'homework/'||c::text||'/'||mid::text||'/image.webp','pending/'||c::text||'/'||mid::text||'/upload.webp',
   (p_data->>'size_bytes')::int,(p_data->>'width')::int,(p_data->>'height')::int,p_data->>'checksum')returning * into m;
  return to_jsonb(m);
 end if;
 select * into m from public.homework_attachments where id=(p_data->>'attachment_id')::uuid and class_id=c for update;
 if m.id is null or m.status='deleting' then raise exception 'Không có ảnh khả dụng' using errcode='42501';end if;
 if p_action in('ticket','cancel') then
  if m.owner_id<>a.id or a.role::text='admin' or m.status<>'pending' then raise exception 'Chỉ tác giả dùng ảnh chờ' using errcode='42501';end if;
  if p_action='cancel' then perform homework_private.media_enqueue(m.id,'pending_canceled');return '{"ok":true,"cleanup":"queued"}';end if;
  if m.expires_at<=clock_timestamp() then raise exception 'Ảnh chờ đã hết hạn 24 giờ';end if;
  if m.notice_id is not null then
   select * into n from public.homework_notices where id=m.notice_id and author_id=a.id and class_id=c;
   if n.id is null or n.status in('deleted','replaced') then raise exception 'Bài không còn nhận ảnh';end if;
   if m.correction_id is not null then
    if not exists(select 1 from public.homework_corrections x join public.homework_correction_rounds r on r.correction_id=x.id and r.round=x.round where x.id=m.correction_id and x.notice_id=n.id and x.round=m.correction_round and x.status='awaiting_author' and r.due_at>clock_timestamp()) then raise exception 'Correction không còn nhận ảnh';end if;
   elsif n.revision<>m.base_revision or exists(select 1 from public.homework_corrections where notice_id=n.id and status in('awaiting_author','awaiting_teacher')) then raise exception 'Bài đã thay đổi';end if;
  end if;
  -- Covers short PUT/signing + bounded promotion work; cleanup sweeps again after this grant.
  until_time:=least(m.expires_at,clock_timestamp()+interval '5 minutes');
  update public.homework_attachments set grant_until=until_time where id=m.id returning * into m;
  return to_jsonb(m);
 elsif p_action='read' then
  if m.status='pending' then
   if a.id<>m.owner_id or m.verified_at is null or m.expires_at<=clock_timestamp() then raise exception 'Ảnh chờ riêng tư' using errcode='42501';end if;
  else
   select * into n from public.homework_notices where id=m.notice_id and class_id=c;
   if n.id is null then raise exception 'Ảnh đã gỡ' using errcode='42501';end if;
   if exists(select 1 from public.homework_notice_media where notice_id=n.id and attachment_id=m.id) then
    -- FEAT-006 P1: peer image access requires active English membership for
    -- Student AND Monitor; the legacy visible() helper exempts Monitor.
    if not (n.author_id=a.id or a.role::text in('teacher','admin') or (n.status='published' and (
     n.english_group_id is null or exists(
      select 1 from public.english_group_members membership
      where membership.english_group_id=n.english_group_id
       and membership.student_id=a.id and membership.left_at is null
     )
    ))) then raise exception 'Ngoài phạm vi bài' using errcode='42501';end if;
   elsif exists(select 1 from public.homework_media_history where notice_id=n.id and attachment_id=m.id) then
    if not(n.author_id=a.id or a.role::text in('teacher','admin')) then raise exception 'Lịch sử ảnh riêng tư' using errcode='42501';end if;
   elsif exists(select 1 from public.homework_correction_rounds r join public.homework_corrections x on x.id=r.correction_id where x.notice_id=n.id and r.attachment_id=m.id) then
    if not(n.author_id=a.id or a.role::text='teacher') then raise exception 'Ảnh chỉnh sửa riêng tư' using errcode='42501';end if;
   else raise exception 'Ảnh không còn tham chiếu' using errcode='42501';end if;
  end if;
  return jsonb_build_object('id',m.id,'object_key',m.object_key,'width',m.width,'height',m.height);
 end if;
 raise exception 'Thao tác ảnh không hợp lệ';
end $function$;
CREATE OR REPLACE FUNCTION public.homework_media_service(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare m public.homework_attachments;j public.homework_media_outbox;row_item record;result jsonb;begin
 if current_setting('role',true) is distinct from 'service_role' then raise exception 'Service only' using errcode='42501';end if;
 if p_action='seal' then
  select * into m from public.homework_attachments where id=(p_data->>'attachment_id')::uuid;
  perform pg_advisory_xact_lock(hashtextextended('homework:'||m.class_id::text,0));
  select * into m from public.homework_attachments where id=m.id for update;
  if m.id is null or m.owner_id is distinct from (p_data->>'owner_id')::uuid or m.status<>'pending' or m.expires_at<=clock_timestamp() or m.grant_until is null or m.grant_until<=clock_timestamp() then raise exception 'Ảnh chờ không còn khả dụng';end if;
  update public.homework_attachments set verified_at=clock_timestamp() where id=m.id;
  return '{"ok":true}';
 elsif p_action='jobs' then
  for row_item in select id,class_id from public.homework_attachments where status='pending' and expires_at<=clock_timestamp() order by expires_at limit 100 loop
   perform pg_advisory_xact_lock(hashtextextended('homework:'||row_item.class_id::text,0));
   if exists(select 1 from public.homework_attachments where id=row_item.id and status='pending' and expires_at<=clock_timestamp()) then perform homework_private.media_enqueue(row_item.id,'pending_expired');end if;
  end loop;
  with picked as(select attachment_id from public.homework_media_outbox where next_attempt_at<=clock_timestamp() and (p_data->>'attachment_id' is null or attachment_id=(p_data->>'attachment_id')::uuid) order by next_attempt_at for update skip locked limit 50),
  claimed as(update public.homework_media_outbox o set token=gen_random_uuid(),attempts=attempts+1,next_attempt_at=clock_timestamp()+interval '5 minutes' from picked p where p.attachment_id=o.attachment_id returning o.*)
  select coalesce(jsonb_agg(jsonb_build_object('id',att.id,'staging_key',att.staging_key,'object_key',att.object_key,'safe_after',x.safe_after,'kind',x.kind,'token',x.token)),'[]') into result from claimed x join public.homework_attachments att on att.id=x.attachment_id;
  return result;
 elsif p_action='ack' then
  select * into j from public.homework_media_outbox where attachment_id=(p_data->>'attachment_id')::uuid for update;
  if j.attachment_id is null or j.token is distinct from (p_data->>'token')::uuid then return '{"ok":true}';end if;
  if p_data->'success'='true'::jsonb then
   if clock_timestamp()>=j.safe_after and j.kind='staging' then
    delete from public.homework_media_outbox where attachment_id=j.attachment_id;
   elsif clock_timestamp()>=j.safe_after and not homework_private.media_referenced(j.attachment_id) then
    delete from public.homework_attachments where id=j.attachment_id and status='deleting';
   else update public.homework_media_outbox set next_attempt_at=greatest(j.safe_after,clock_timestamp()+interval '1 minute'),last_error=null where attachment_id=j.attachment_id;end if;
  else update public.homework_media_outbox set next_attempt_at=clock_timestamp()+interval '1 minute',last_error='R2_DELETE_FAILED' where attachment_id=j.attachment_id;end if;
  return '{"ok":true}';
 end if;
 raise exception 'Unknown media service action';
end $function$;
CREATE OR REPLACE FUNCTION public.homework_storage(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.profiles; before_bytes bigint; queued integer:=0; m record; target text;
begin
 a:=homework_private.storage_admin();
 if p_action='status' then
  return homework_private.storage_state()||jsonb_build_object('candidates',(
   select coalesce(jsonb_agg(x order by x->>'school_year_id'),'[]'::jsonb) from (
    select jsonb_build_object('school_year_id',at.school_year_id,'media_count',count(*),
     'media_bytes',coalesce(sum(at.size_bytes),0),
     'notice_count',(select count(distinct nm.notice_id) from public.homework_notice_media nm
       join public.homework_attachments a2 on a2.id=nm.attachment_id where a2.school_year_id=at.school_year_id),
     -- FEAT-007 owns archive state; until it exists nothing has been archived.
     'archived',false) x
    from public.homework_attachments at where at.status='active' group by at.school_year_id) c));
 elsif p_action='refresh' then
  perform homework_private.storage_measure();
  return homework_private.storage_state();
 elsif p_action='set_capacity' then
  target:=p_data->>'provider';
  if target not in('database','r2') then raise exception 'Nhà cung cấp không hợp lệ';end if;
  select configured_bytes into before_bytes from public.homework_storage_capacity where provider=target;
  update public.homework_storage_capacity
   set configured_bytes=nullif(p_data->>'configured_bytes','')::bigint,
    note=coalesce(nullif(p_data->>'note',''),note),updated_at=clock_timestamp(),updated_by=a.id
   where provider=target;
  insert into public.homework_storage_events(actor_id,event_type,before_data,after_data)
   values(a.id,'storage_capacity',jsonb_build_object('provider',target,'configured_bytes',before_bytes),
    jsonb_build_object('provider',target,'configured_bytes',nullif(p_data->>'configured_bytes','')::bigint));
  return homework_private.storage_state();
 elsif p_action='cleanup_pending' then
  -- Only pending uploads past the 24h window (DEC-081 case 2). Active and
  -- referenced media are untouched; the FEAT-006 outbox does the actual purge.
  for m in select id from public.homework_attachments
   where status='pending' and expires_at<=clock_timestamp()
   and coalesce(grant_until,clock_timestamp())<=clock_timestamp() loop
   perform homework_private.media_enqueue(m.id,'storage_cleanup');queued:=queued+1;
  end loop;
  -- Queuing a cleanup is not evidence that R2 has shrunk. media_enqueue only
  -- writes an outbox job; the objects are deleted later, asynchronously, and may
  -- fail. RC2 cleared the provider reading here, which let one queued pending
  -- attachment unlock uploads while the bucket could still be over 95% — and
  -- threw away the only evidence about untracked objects the app cannot see.
  -- The reading is left alone: it expires on its own after six hours, and Admin
  -- can ask R2 for a fresh figure at any time. Staying locked a little longer is
  -- the safe direction; unlocking on a promise is not.
  perform homework_private.storage_measure();
  insert into public.homework_storage_events(actor_id,event_type,after_data)
   values(a.id,'storage_cleanup',jsonb_build_object('queued',queued));
  return homework_private.storage_state()||jsonb_build_object('queued',queued);
 end if;
 raise exception 'Thao tác dung lượng không hợp lệ';
end $function$;
CREATE OR REPLACE FUNCTION public.homework_storage_service(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if p_action='record_usage' then
  perform homework_private.storage_measure();
  update public.homework_storage_usage
   set provider_bytes=nullif(p_data->>'provider_bytes','')::bigint,provider_measured_at=clock_timestamp()
   where provider=coalesce(nullif(p_data->>'provider',''),'r2');
  return homework_private.storage_state();
 elsif p_action='state' then
  return homework_private.storage_state();
 elsif p_action='measure' then
  perform homework_private.storage_measure();
  return homework_private.storage_state();
 end if;
 raise exception 'Thao tác dung lượng không hợp lệ';
end $function$;
