CREATE OR REPLACE FUNCTION public.late_tracking_assert_actor(p_class_id uuid, p_student_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role text := public.current_app_role()::text;
begin
  if auth.uid() is null then
    raise exception 'Bạn chưa đăng nhập.' using errcode = '42501';
  end if;
  if v_role is null then
    raise exception 'Tài khoản không còn hoạt động.' using errcode = '42501';
  end if;
  if v_role in ('admin', 'teacher') then
    if not public.can_manage_class(p_class_id) then
      raise exception 'Bạn không phụ trách lớp này.' using errcode = '42501';
    end if;
  elsif v_role = 'monitor' then
    if public.current_student_class_id() is distinct from p_class_id then
      raise exception 'Cán sự chỉ ghi nhận được cho lớp của mình.' using errcode = '42501';
    end if;
    if p_student_id = auth.uid() then
      raise exception 'Cán sự không tự ghi nhận cho chính mình; hãy nhờ giáo viên.' using errcode = '42501';
    end if;
  else
    raise exception 'Chỉ cán sự hoặc giáo viên mới ghi nhận được.' using errcode = '42501';
  end if;
end
$function$;
CREATE OR REPLACE FUNCTION public.late_tracking_can_view(p_class_id uuid, p_student_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    public.can_manage_class(p_class_id)
    or (public.current_app_role()::text = 'monitor' and p_class_id = public.current_student_class_id())
    or p_student_id = auth.uid(),
    false)
$function$;
CREATE OR REPLACE FUNCTION public.normalize_student_registration_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- auth.uid() survives SECURITY DEFINER. Never infer a trusted caller from
  -- current_user: inside this function it is the function owner. A service
  -- writer with no student JWT keeps its existing pipeline and permissions.
  if auth.uid() is not null
     and public.current_app_role()::text in ('student', 'monitor') then
    -- Smart approval can turn a self-approved row into submitted before RLS.
    -- Reject that input here rather than making an invalid INSERT pass policy.
    if new.status is null or new.status::text not in ('draft', 'submitted') then
      raise exception 'Student registrations must start as draft or submitted.'
        using errcode = '42501';
    end if;

    new.teacher_comment := null;
    new.ai_review_count := 0;
    new.approval_source := 'manual';
    new.approved_by := null;
    new.approved_at := null;
    new.ai_review_status := 'not_needed';
    new.ai_decision := null;
    new.ai_category := null;
    new.ai_confidence := null;
    new.ai_revision_status := null;
    new.ai_revision_confidence := null;
    new.ai_reason := null;
    new.ai_model := null;
    new.ai_reviewed_at := null;
    new.auto_review_reason := null;
    new.revision_overdue_at := null;
    new.device_detection_source := 'none';
    new.device_detection_confidence := null;

    -- Do not rewrite owner/class/status/deletion/emergency flags or timestamps.
    -- Existing policy/RPC checks remain responsible for them. The next device
    -- trigger computes effective_uses_electronic_device; smart approval derives
    -- submitted AI/manual state from the class configuration.
  end if;
  return new;
end;
$function$;
CREATE OR REPLACE FUNCTION public.prepare_registration_ai_rereview(p_registration_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_class_id uuid;
begin
  select class_id into v_class_id from public.registrations where id=p_registration_id and is_deleted=false;
  if v_class_id is null then return false; end if;
  if not public.can_manage_class(v_class_id) then raise exception 'Bạn không có quyền duyệt lại đăng ký này.' using errcode='42501'; end if;
  if not public.ai_automation_is_enabled(v_class_id) then raise exception 'Duyệt tự động bằng AI đang tắt cho lớp này.' using errcode='P0001'; end if;
  perform set_config('app.force_ai_rereview','on',true);
  update public.registrations r set status='submitted',approval_source='manual',ai_review_status='pending',
    ai_decision=null,ai_category=null,ai_confidence=null,ai_revision_status=null,ai_revision_confidence=null,
    ai_reason=null,ai_model=null,ai_reviewed_at=null,approved_at=null,approved_by=null,
    auto_review_reason='GV/Admin chủ động yêu cầu AI duyệt lại.',updated_at=now()
  where r.id=p_registration_id and r.class_id=v_class_id and r.is_deleted=false and r.revision_overdue_at is null
    and (r.status='approved' or (r.status='submitted' and r.ai_review_status not in ('pending','processing')));
  return found;
end; $function$;
CREATE OR REPLACE FUNCTION public.prepare_session_ai_rereview(p_class_id uuid, p_week_id uuid, p_weekday integer, p_period_number integer)
 RETURNS TABLE(registration_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.can_manage_class(p_class_id) then raise exception 'Bạn không có quyền duyệt AI cho lớp này.' using errcode='42501'; end if;
  if not public.ai_automation_is_enabled(p_class_id) then raise exception 'Duyệt tự động bằng AI đang tắt cho lớp này.' using errcode='P0001'; end if;
  if p_week_id is null or p_weekday not between 1 and 5 or p_period_number not between 1 and 9 then raise exception 'Thông tin buổi tự học không hợp lệ.' using errcode='22023'; end if;
  return query select r.id from public.registrations r
    where r.class_id=p_class_id and r.week_id=p_week_id and r.weekday=p_weekday and r.period_number=p_period_number
      and r.is_deleted=false and r.revision_overdue_at is null
      and (r.status='approved' or (r.status='submitted' and r.ai_review_status not in ('pending','processing')))
    order by r.updated_at,r.id;
end; $function$;
CREATE OR REPLACE FUNCTION public.prevent_timetable_assignment_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.active and exists(
    select 1 from public.class_timetable_assignments x
    where x.class_id=new.class_id and x.active and x.id<>coalesce(new.id,'00000000-0000-0000-0000-000000000000'::uuid)
      and daterange(x.effective_from,x.effective_to,'[]') && daterange(new.effective_from,new.effective_to,'[]')
  ) then raise exception 'Khoảng hiệu lực TKB của lớp không được chồng nhau.' using errcode='23P01'; end if;
  return new;
end$function$;
CREATE OR REPLACE FUNCTION public.record_late_registration(p_student_id uuid, p_week_id uuid, p_weekday integer, p_period_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_class uuid;
  v_year uuid;
  v_start timestamptz;
  v_threshold integer;
  v_pending integer;
  v_late uuid;
  v_case uuid;
begin
  select p.class_id into v_class
  from public.profiles p
  where p.id = p_student_id
    and p.active = true
    and p.deleted_at is null
    and p.role::text in ('student', 'monitor');
  if v_class is null then
    raise exception 'Không tìm thấy học sinh đang học trong lớp.' using errcode = 'P0002';
  end if;

  perform public.late_tracking_assert_actor(v_class, p_student_id);

  select w.school_year_id into v_year from public.weeks w where w.id = p_week_id;
  if v_year is null then
    raise exception 'Tuần không hợp lệ.' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.classes c where c.id = v_class and c.school_year_id = v_year) then
    raise exception 'Tuần này không thuộc năm học của lớp.' using errcode = '22023';
  end if;

  v_start := public.study_session_start(v_class, p_week_id, p_weekday, p_period_number);
  if v_start is null then
    raise exception 'Chưa xác định được giờ bắt đầu của buổi tự học.' using errcode = '22023';
  end if;
  if now() < v_start then
    raise exception 'Buổi tự học chưa bắt đầu; học sinh vẫn tự đăng ký được trên ứng dụng.' using errcode = '22023';
  end if;

  if exists (
    select 1 from public.registrations r
    where r.student_id = p_student_id and r.week_id = p_week_id
      and r.weekday = p_weekday and r.period_number = p_period_number
      and r.is_deleted = false and r.status::text <> 'draft'
  ) then
    raise exception 'Học sinh đã có đăng ký cho buổi này.' using errcode = '22023';
  end if;

  -- Một học sinh một hàng đợi: hai người bấm cùng lúc không tạo trùng lần cải thiện ý thức.
  perform pg_advisory_xact_lock(hashtextextended('late_registrations:' || p_student_id::text, 0));

  begin
    insert into public.late_registrations
      (class_id, school_year_id, student_id, week_id, weekday, period_number, recorded_by)
    values
      (v_class, v_year, p_student_id, p_week_id, p_weekday, p_period_number, v_actor)
    returning id into v_late;
  exception when unique_violation then
    raise exception 'Đã ghi trễ cho học sinh này ở buổi này rồi.' using errcode = '23505';
  end;

  select coalesce(cs.late_conduct_threshold, 3) into v_threshold
  from public.class_settings cs where cs.class_id = v_class;
  v_threshold := coalesce(v_threshold, 3);

  select count(*) into v_pending
  from public.late_registrations l
  where l.student_id = p_student_id and l.class_id = v_class and l.school_year_id = v_year
    and l.revoked_at is null and l.conduct_case_id is null;

  if v_pending >= v_threshold then
    insert into public.conduct_cases (class_id, school_year_id, student_id, threshold, created_by)
    values (v_class, v_year, p_student_id, v_threshold, v_actor)
    returning id into v_case;

    update public.late_registrations
    set conduct_case_id = v_case
    where id in (
      select l.id from public.late_registrations l
      where l.student_id = p_student_id and l.class_id = v_class and l.school_year_id = v_year
        and l.revoked_at is null and l.conduct_case_id is null
      order by l.recorded_at, l.id
      limit v_threshold
    );
    v_pending := v_pending - v_threshold;
  end if;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, new_data, class_id, source)
  values (v_actor, 'late_registration.record', 'late_registration', v_late::text,
    jsonb_build_object('student_id', p_student_id, 'week_id', p_week_id, 'weekday', p_weekday,
      'period_number', p_period_number, 'conduct_case_id', v_case),
    v_class, 'server');

  return jsonb_build_object(
    'late_id', v_late,
    'pending', v_pending,
    'threshold', v_threshold,
    'conduct_case_id', v_case
  );
end
$function$;
CREATE OR REPLACE FUNCTION public.registration_deadline_for_slot(p_week_id uuid, p_weekday integer)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.registration_deadline_for_slot(public.current_student_class_id(),p_week_id,p_weekday)
$function$;
CREATE OR REPLACE FUNCTION public.registration_deadline_for_slot(p_class_id uuid, p_week_id uuid, p_weekday integer)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case coalesce(nullif(cw.deadline_mode,'inherit'),cs.default_deadline_mode,'per_session_20')
    when 'per_session_20' then
      ((w.start_date+(greatest(1,least(5,p_weekday))-1)-1
        + coalesce(cs.per_session_deadline_time,time '20:00')) at time zone 'Asia/Ho_Chi_Minh')
    when 'week_before_20' then
      ((w.start_date-1 + coalesce(cs.per_session_deadline_time,time '20:00')) at time zone 'Asia/Ho_Chi_Minh')
    when 'specific' then cw.registration_deadline
    else cw.registration_deadline
  end
  from public.weeks w
  left join public.class_weeks cw on cw.week_id=w.id and cw.class_id=p_class_id
  left join public.class_settings cs on cs.class_id=p_class_id
  where w.id=p_week_id
$function$;
CREATE OR REPLACE FUNCTION public.registration_emergency_flag_matches(p_registration_id uuid, p_flag boolean)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select r.is_emergency=p_flag
     from public.registrations r
     where r.id=p_registration_id),
    false
  )
$function$;
CREATE OR REPLACE FUNCTION public.request_registration_revision(p_registration_id uuid, p_teacher_comment text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_actor uuid:=auth.uid();v_registration public.registrations%rowtype;v_comment text:=btrim(coalesce(p_teacher_comment,''));v_session_start timestamptz;v_status text;
begin
  if v_actor is null then raise exception 'Bạn chưa đăng nhập.' using errcode='42501';end if;if v_comment='' then raise exception 'Vui lòng nhập nội dung yêu cầu chỉnh sửa.' using errcode='22023';end if;
  select * into v_registration from public.registrations where id=p_registration_id for update;
  if not found or coalesce(v_registration.is_deleted,false) then raise exception 'Không tìm thấy đăng ký đang hoạt động.' using errcode='P0002';end if;
  if not public.can_manage_class(v_registration.class_id) then raise exception 'Bạn không có quyền yêu cầu sửa đăng ký của lớp này.' using errcode='42501';end if;
  v_status:=v_registration.status::text;if v_status not in('submitted','needs_revision','approved') then raise exception 'Trạng thái đăng ký hiện tại không hỗ trợ yêu cầu sửa.' using errcode='22023';end if;
  if v_registration.revision_overdue_at is not null then raise exception 'Đăng ký đã quá hạn chỉnh sửa.' using errcode='22023';end if;
  v_session_start:=public.study_session_start(v_registration.class_id,v_registration.week_id,v_registration.weekday,v_registration.period_number);
  if v_session_start is null then raise exception 'Không xác định được thời điểm bắt đầu buổi tự học.' using errcode='22023';end if;if now()>=v_session_start then raise exception 'Buổi tự học đã bắt đầu; không thể yêu cầu học sinh sửa đăng ký.' using errcode='22023';end if;
  update public.registrations set status='needs_revision',approval_source='manual',approved_at=null,approved_by=null,teacher_comment=v_comment,ai_review_status='not_needed',ai_decision=null,ai_category=null,ai_confidence=null,ai_revision_status=null,ai_revision_confidence=null,ai_reason=null,ai_model=null,ai_reviewed_at=null,revision_overdue_at=null,updated_at=now() where id=v_registration.id;
  return true;
end$function$;
CREATE OR REPLACE FUNCTION public.resolve_conduct_case(p_case_id uuid, p_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.conduct_cases%rowtype;
  v_note text := nullif(left(btrim(coalesce(p_note, '')), 300), '');
begin
  select * into v_row from public.conduct_cases where id = p_case_id for update;
  if not found or v_row.resolved_at is not null then
    return false;
  end if;

  perform public.late_tracking_assert_actor(v_row.class_id, v_row.student_id);

  update public.conduct_cases
  set resolved_at = now(), resolved_by = auth.uid(), resolution_note = v_note
  where id = p_case_id;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, new_data, class_id, source)
  values (auth.uid(), 'conduct_case.resolve', 'conduct_case', p_case_id::text,
    jsonb_build_object('student_id', v_row.student_id, 'note', v_note),
    v_row.class_id, 'server');

  return true;
end
$function$;
CREATE OR REPLACE FUNCTION public.resolved_timetable_periods(p_class_id uuid, p_date date)
 RETURNS TABLE(period_number smallint, start_time time without time zone, end_time time without time zone, session text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select vp.period_number,vp.start_time,vp.end_time,vp.session
  from public.class_timetable_assignments a
  join public.timetable_version_periods vp on vp.version_id=a.template_version_id
  where a.class_id=p_class_id and a.active and p_date between a.effective_from and a.effective_to
    and vp.weekday=extract(isodow from p_date)::int
  order by vp.period_number
$function$;
CREATE OR REPLACE FUNCTION public.revoke_late_registration(p_late_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.late_registrations%rowtype;
begin
  select * into v_row from public.late_registrations where id = p_late_id for update;
  if not found or v_row.revoked_at is not null then
    return false;
  end if;

  perform public.late_tracking_assert_actor(v_row.class_id, v_row.student_id);

  if v_row.conduct_case_id is not null then
    raise exception 'Lần trễ này đã được tính vào một lần cải thiện ý thức nên không hủy được.' using errcode = '22023';
  end if;

  update public.late_registrations
  set revoked_at = now(), revoked_by = auth.uid()
  where id = p_late_id;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, old_data, class_id, source)
  values (auth.uid(), 'late_registration.revoke', 'late_registration', p_late_id::text,
    jsonb_build_object('student_id', v_row.student_id, 'week_id', v_row.week_id,
      'weekday', v_row.weekday, 'period_number', v_row.period_number),
    v_row.class_id, 'server');

  return true;
end
$function$;
CREATE OR REPLACE FUNCTION public.set_own_avatar_path(p_avatar_path text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_webp text;
  v_gif text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  v_webp := v_uid::text || '/avatar.webp';
  v_gif := v_uid::text || '/avatar.gif';
  if p_avatar_path is not null and p_avatar_path not in (v_webp,v_gif) then
    raise exception 'INVALID_AVATAR_PATH';
  end if;

  update public.profiles
  set avatar_path = p_avatar_path
  where id = v_uid;

  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  return p_avatar_path;
end;
$function$;
CREATE OR REPLACE FUNCTION public.set_registration_class_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_class uuid;
begin
  if tg_op='UPDATE' then new.class_id:=old.class_id; return new; end if;
  select p.class_id into v_class
  from public.profiles p
  join public.classes c on c.id=p.class_id and c.active=true
  where p.id=new.student_id and p.active=true and p.role::text in ('student','monitor');
  if v_class is null then raise exception 'REGISTRATION_STUDENT_HAS_NO_ACTIVE_CLASS'; end if;
  new.class_id:=v_class;
  return new;
end; $function$;
CREATE OR REPLACE FUNCTION public.study_session_start(p_week_id uuid, p_weekday integer, p_period_number integer)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select (
    ((w.start_date+(greatest(1,least(5,p_weekday))-1))::timestamp + coalesce(yp.start_time,p.start_time))
  ) at time zone 'Asia/Ho_Chi_Minh'
  from public.weeks w
  left join public.school_year_periods yp
    on yp.school_year_id=w.school_year_id and yp.period_number=p_period_number
  left join public.periods p on p.period_number=p_period_number
  where w.id=p_week_id and coalesce(yp.start_time,p.start_time) is not null
$function$;
CREATE OR REPLACE FUNCTION public.study_session_start(p_class_id uuid, p_week_id uuid, p_weekday integer, p_period_number integer)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select ((day_date::timestamp+coalesce(tp.start_time,yp.start_time,p.start_time)) at time zone 'Asia/Ho_Chi_Minh')
  from public.weeks w
  cross join lateral (select w.start_date+(greatest(1,least(7,p_weekday))-1) day_date) d
  left join lateral (
    select r.start_time from public.resolved_timetable_periods(p_class_id,d.day_date) r where r.period_number=p_period_number limit 1
  ) tp on true
  left join public.school_year_periods yp on yp.school_year_id=w.school_year_id and yp.period_number=p_period_number
  left join public.periods p on p.period_number=p_period_number
  where w.id=p_week_id and coalesce(tp.start_time,yp.start_time,p.start_time) is not null
$function$;
CREATE OR REPLACE FUNCTION public.sync_class_assignments_on_deactivate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.active=true and new.active=false then
    update public.class_teachers
    set active=false,updated_at=now()
    where class_id=new.id and active=true;
  end if;
  return new;
end; $function$;
CREATE OR REPLACE FUNCTION public.sync_revision_overdue_reports()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_changed integer:=0;
begin
  update public.registrations r
  set revision_overdue_at=coalesce(r.revision_overdue_at,now()),updated_at=now()
  where r.is_deleted=false and r.status='needs_revision' and r.revision_overdue_at is null
    and public.class_week_effective_status(r.class_id,r.week_id)<>'holiday'
    and public.study_session_start(r.class_id,r.week_id,r.weekday,r.period_number) is not null
    and now()>=public.study_session_start(r.class_id,r.week_id,r.weekday,r.period_number);
  get diagnostics v_changed=row_count;
  return v_changed;
end$function$;
CREATE OR REPLACE FUNCTION public.sync_stale_ai_reviews()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_count integer := 0;
begin
  update public.registrations
  set
    status='submitted',
    approval_source='manual',
    ai_review_status='error',
    ai_decision='manual_review',
    ai_category=null,
    ai_confidence=null,
    ai_revision_status=null,
    ai_revision_confidence=null,
    ai_reason='AI không phản hồi trong 2 phút; hệ thống tự chuyển giáo viên duyệt.',
    ai_reviewed_at=now(),
    approved_at=null,
    approved_by=null,
    updated_at=now()
  where is_deleted=false
    and status='submitted'
    and approval_source='manual'
    and ai_review_status in ('pending','processing')
    and updated_at <= now() - interval '2 minutes';

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;
CREATE OR REPLACE FUNCTION public.sync_teacher_assignments_on_profile_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
