 SET search_path TO 'public'
AS $function$
begin
  if not exists(
    select 1
    from public.classes c
    join public.weeks w on w.id=new.week_id
    where c.id=new.class_id
      and c.school_year_id=w.school_year_id
  ) then
    raise exception 'CLASS_WEEK_SCHOOL_YEAR_MISMATCH';
  end if;
