CREATE OR REPLACE FUNCTION public.visible_class_people()
 RETURNS TABLE(id uuid, student_code text, full_name text, role text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  viewer_id uuid := auth.uid();
  viewer_role text;
  viewer_class_id uuid;
begin
  if viewer_id is null then
    return;
  end if;

  select p.role::text, p.class_id
    into viewer_role, viewer_class_id
  from public.profiles p
  where p.id = viewer_id and p.active = true;

  if viewer_role not in ('student','monitor') or viewer_class_id is null then
    return;
  end if;

  return query
  select
    p.id,
    case when p.role::text = 'teacher' then null else p.student_code end,
    p.full_name,
    p.role::text
  from public.profiles p
  where p.active = true
    and (
      (p.role::text in ('student','monitor') and p.class_id = viewer_class_id)
      or
      (p.role::text = 'teacher' and exists(
        select 1
        from public.class_teachers ct
        join public.classes c on c.id = ct.class_id and c.active = true
        where ct.teacher_id = p.id
          and ct.class_id = viewer_class_id
          and ct.active = true
      ))
    )
  order by
    case when p.role::text = 'teacher' then 0 when p.role::text = 'monitor' then 1 else 2 end,
    p.full_name;
end;
$function$;
CREATE OR REPLACE FUNCTION public.week_effective_status(p_week_id uuid)
 RETURNS public.week_status
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with target as (
    select
      w.id,
      w.school_year_id,
      w.start_date,
      w.status
    from public.weeks w
    where w.id = p_week_id
  ),
  clock as (
    select (now() at time zone 'Asia/Ho_Chi_Minh')::date as today
  ),
  anchor as (
    select w.start_date as current_start
    from public.weeks w
    join target t
      on t.school_year_id = w.school_year_id
    cross join clock c
    where c.today between w.start_date and (w.start_date + 6)
    order by w.start_date desc
    limit 1
  ),
  next_week as (
    select min(w.start_date) as next_start
    from public.weeks w
    join target t
      on t.school_year_id = w.school_year_id
    join anchor a
      on true
    where w.start_date > a.current_start
  )
  select
    case
      when t.status = 'holiday'
        then 'holiday'::public.week_status

      -- Trường hợp hôm nay nằm ngoài toàn bộ lịch tuần của năm học.
      when a.current_start is null then
        case
          when (t.start_date + 6) < c.today
            then 'locked'::public.week_status
          else 'upcoming'::public.week_status
        end

      when t.start_date < a.current_start
        then 'locked'::public.week_status

      when t.start_date = a.current_start
        then 'open'::public.week_status

      when n.next_start is not null
           and t.start_date = n.next_start
        then 'open'::public.week_status

      else 'upcoming'::public.week_status
    end
  from target t
  cross join clock c
  left join anchor a on true
  left join next_week n on true
$function$;
CREATE OR REPLACE FUNCTION public.week_registration_is_open(p_week_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.week_registration_is_open(public.current_student_class_id(),p_week_id)
$function$;
CREATE OR REPLACE FUNCTION public.week_registration_is_open(p_class_id uuid, p_week_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    exists(select 1 from public.classes c where c.id=p_class_id and c.active=true)
    and public.class_week_effective_status(p_class_id,p_week_id)='open'::public.week_status,
    false
  )
$function$;
CREATE OR REPLACE FUNCTION storage_live_private.emit_signal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_table_schema <> 'public' or tg_table_name in
     ('storage_change_signals','homework_storage_usage','homework_storage_events') then
    return null;
  end if;
  insert into public.storage_change_signals(source_table,changed_at,affects_r2)
  values(tg_table_name,clock_timestamp(),tg_table_name='homework_attachments')
  on conflict(source_table) do update
    set changed_at=excluded.changed_at,affects_r2=excluded.affects_r2;
  return null;
end $function$;
CREATE OR REPLACE FUNCTION storage_live_private.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select exists(select 1 from public.profiles
    where id=auth.uid() and active and deleted_at is null and role::text='admin')
$function$;

