-- ======================================================================
-- 100 Views
-- ======================================================================
create view public.class_members with (security_invoker=on) as
 SELECT id,
    student_code,
    full_name,
    role,
    class_name,
    active
   FROM public.profiles
  WHERE id = auth.uid() OR public.is_teacher() OR public.current_app_role() = 'monitor'::public.app_role AND class_name = public.current_app_class();

