-- 125 Policies
-- ======================================================================
create policy settings_read on public.app_settings as permissive for select to authenticated using (true);
create policy audit_manager_select_v840 on public.audit_logs as permissive for select to authenticated using ((public.is_root_admin() OR ((class_id IS NOT NULL) AND public.teacher_has_class(class_id))));
create policy class_settings_manage_v840 on public.class_settings as permissive for update to authenticated using (public.can_manage_class(class_id)) with check (public.can_manage_class(class_id));
create policy class_settings_select_v840 on public.class_settings as permissive for select to authenticated using ((public.can_manage_class(class_id) OR (class_id = public.current_student_class_id())));
create policy class_teachers_admin_write_v840 on public.class_teachers as permissive for all to authenticated using (public.is_root_admin()) with check (public.is_root_admin());
create policy class_teachers_select_v840 on public.class_teachers as permissive for select to authenticated using ((( SELECT public.is_root_admin() AS is_root_admin) OR (teacher_id = ( SELECT auth.uid() AS uid))));
create policy class_timetable_assignments_read on public.class_timetable_assignments as permissive for select to authenticated using (true);
create policy class_weeks_manage_v840 on public.class_weeks as permissive for all to authenticated using (public.can_manage_class(class_id)) with check (public.can_manage_class(class_id));
create policy class_weeks_select_v840 on public.class_weeks as permissive for select to authenticated using ((public.can_manage_class(class_id) OR (class_id = public.current_student_class_id())));
create policy classes_admin_write_v840 on public.classes as permissive for all to authenticated using (public.is_root_admin()) with check (public.is_root_admin());
create policy classes_select_v840 on public.classes as permissive for select to authenticated using ((public.is_root_admin() OR public.teacher_has_class(id) OR (id = public.current_student_class_id())));
create policy conduct_cases_select on public.conduct_cases as permissive for select to authenticated using (public.late_tracking_can_view(class_id, student_id));
create policy device_use_lock_intervals_select_v010 on public.device_use_lock_intervals as permissive for select to authenticated using (public.can_manage_class(class_id));
create policy device_use_policy_signals_select_v010 on public.device_use_policy_signals as permissive for select to authenticated using (COALESCE((public.can_manage_class(class_id) OR (class_id = public.current_student_class_id())), false));
create policy device_use_session_overrides_select_v010 on public.device_use_session_overrides as permissive for select to authenticated using (public.can_manage_class(class_id));
create policy late_registrations_select on public.late_registrations as permissive for select to authenticated using (public.late_tracking_can_view(class_id, student_id));
create policy periods_admin_write_v840 on public.periods as permissive for all to authenticated using (public.is_root_admin()) with check (public.is_root_admin());
create policy periods_read_v840 on public.periods as permissive for select to authenticated using (true);
create policy profiles_select_v841 on public.profiles as permissive for select to authenticated using (public.can_view_profile(id));
create policy registrations_manager_update_v840 on public.registrations as permissive for update to authenticated using (public.can_manage_class(class_id)) with check (public.can_manage_class(class_id));
create policy registrations_select_v840 on public.registrations as permissive for select to authenticated using (((is_deleted = false) AND ((student_id = ( SELECT auth.uid() AS uid)) OR ( SELECT public.is_root_admin() AS is_root_admin) OR ((status <> 'draft'::public.registration_status) AND public.teacher_has_class(class_id)) OR ((status <> 'draft'::public.registration_status) AND ((( SELECT public.current_app_role() AS current_app_role))::text = 'monitor'::text) AND (class_id = ( SELECT public.current_student_class_id() AS current_student_class_id))))));
create policy registrations_student_insert_v840 on public.registrations as permissive for insert to authenticated with check ((((( SELECT public.current_app_role() AS current_app_role))::text = ANY (ARRAY['student'::text, 'monitor'::text])) AND (student_id = ( SELECT auth.uid() AS uid)) AND (class_id = ( SELECT public.current_student_class_id() AS current_student_class_id)) AND (is_deleted = false) AND (is_emergency = false) AND (status = ANY (ARRAY['draft'::public.registration_status, 'submitted'::public.registration_status])) AND public.week_registration_is_open(class_id, week_id) AND ((public.registration_deadline_for_slot(class_id, week_id, weekday) IS NULL) OR (now() <= public.registration_deadline_for_slot(class_id, week_id, weekday)))));
create policy registrations_student_update_v840 on public.registrations as permissive for update to authenticated using ((((( SELECT public.current_app_role() AS current_app_role))::text = ANY (ARRAY['student'::text, 'monitor'::text])) AND (student_id = ( SELECT auth.uid() AS uid)) AND (is_deleted = false) AND (class_id = ( SELECT public.current_student_class_id() AS current_student_class_id)) AND (status = ANY (ARRAY['draft'::public.registration_status, 'submitted'::public.registration_status, 'needs_revision'::public.registration_status, 'approved'::public.registration_status])) AND (((status = 'needs_revision'::public.registration_status) AND (revision_overdue_at IS NULL) AND (now() < public.study_session_start(class_id, week_id, weekday, period_number))) OR ((status <> 'needs_revision'::public.registration_status) AND public.week_registration_is_open(class_id, week_id) AND ((public.registration_deadline_for_slot(class_id, week_id, weekday) IS NULL) OR (now() <= public.registration_deadline_for_slot(class_id, week_id, weekday))) AND (now() < public.study_session_start(class_id, week_id, weekday, period_number)))))) with check ((((( SELECT public.current_app_role() AS current_app_role))::text = ANY (ARRAY['student'::text, 'monitor'::text])) AND (student_id = ( SELECT auth.uid() AS uid)) AND (class_id = ( SELECT public.current_student_class_id() AS current_student_class_id)) AND (is_deleted = false) AND (revision_overdue_at IS NULL) AND public.registration_emergency_flag_matches(id, is_emergency) AND (status = ANY (ARRAY['draft'::public.registration_status, 'submitted'::public.registration_status]))));
create policy school_year_periods_read_authenticated on public.school_year_periods as permissive for select to authenticated using (true);
