create policy avatars_owner_delete on storage.objects as permissive for delete to authenticated using (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (name = ANY (ARRAY[((auth.uid())::text || '/avatar.webp'::text), ((auth.uid())::text || '/avatar.gif'::text)]))));
create policy avatars_owner_insert on storage.objects as permissive for insert to authenticated with check (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (name = ANY (ARRAY[((auth.uid())::text || '/avatar.webp'::text), ((auth.uid())::text || '/avatar.gif'::text)]))));
create policy avatars_owner_update on storage.objects as permissive for update to authenticated using (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (name = ANY (ARRAY[((auth.uid())::text || '/avatar.webp'::text), ((auth.uid())::text || '/avatar.gif'::text)])))) with check (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (name = ANY (ARRAY[((auth.uid())::text || '/avatar.webp'::text), ((auth.uid())::text || '/avatar.gif'::text)]))));
create policy avatars_visible_profile_read on storage.objects as permissive for select to authenticated using (((bucket_id = 'avatars'::text) AND (storage.filename(name) = ANY (ARRAY['avatar.webp'::text, 'avatar.gif'::text])) AND ((storage.foldername(name))[1] ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) AND public.can_view_profile(((storage.foldername(name))[1])::uuid)));

